  async getBookings(params?: {
    status?: string;
    limit?: number;
    offset?: number;
    guestUserId?: string;
    hostUserId?: string;
  }) {
    const { status, limit = 50, offset = 0 } = params || {};
    const qb = this.bookingRepo
      .createQueryBuilder('b')
      .leftJoinAndSelect('b.listing', 'listing')
      .orderBy('b.created_at', 'DESC')
      .take(limit)
      .skip(offset);

    if (status && status !== 'all') {
      qb.andWhere('b.status = :status', { status: status.toUpperCase() });
    }
    if (params?.guestUserId) {
      qb.andWhere('b.guest_user_id = :guestUserId', {
        guestUserId: params.guestUserId,
      });
    }
    if (params?.hostUserId) {
      qb.andWhere('listing.host_user_id = :hostUserId', {
        hostUserId: params.hostUserId,
      });
    }

    const [items, total] = await qb.getManyAndCount();
    return { items, total };
  }

  async getBooking(id: string) {
    const booking = await this.bookingRepo.findOne({
      where: { id },
      relations: ['listing', 'occupants'],
    });
    if (!booking) throw new NotFoundException('Booking not found');
    return {
      ...booking,
      occupants:
        booking.occupants?.map((o) => ({
          id: o.id,
          full_name: o.full_name,
          id_number: o.id_number ?? null,
          is_primary: o.is_primary,
          phone: o.phone ?? null,
          email: o.email ?? null,
          gender: o.gender ?? null,
          id_document_front_asset_id: o.id_document_front_asset_id ?? null,
          id_document_back_asset_id: o.id_document_back_asset_id ?? null,
          created_at: o.created_at,
        })) ?? [],
    };
  }

  async getOccupantIdDocumentPath(
    bookingId: string,
    occupantId: string,
    side: 'front' | 'back',
  ): Promise<string> {
    const occupant = await this.occupantRepo.findOne({
      where: { id: occupantId, booking_id: bookingId },
      relations: ['booking'],
    });
    if (!occupant) throw new NotFoundException('Occupant not found');
    const assetId =
      side === 'back'
        ? occupant.id_document_back_asset_id
        : occupant.id_document_front_asset_id;
    if (!assetId) throw new NotFoundException('ID document not uploaded');
    const guestUserId = occupant.booking?.guest_user_id;
    if (!guestUserId) throw new NotFoundException('Booking guest not found');
    return this.staysService.getOccupantIdDocumentPath(
      guestUserId,
      assetId,
      side,
    );
  }

  async getReviews(params?: { limit?: number; offset?: number }) {
    const limit = Math.min(params?.limit ?? 50, 200);
    const offset = params?.offset ?? 0;
    const [items, total] = await this.reviewRepo.findAndCount({
      relations: ['listing'],
      order: { created_at: 'DESC' },
      take: limit,
      skip: offset,
    });
    return { items, total };
  }

  async getAuditLogs(params?: {
    limit?: number;
    offset?: number;
    actorUserId?: string;
    entityId?: string;
  }) {
    const limit = Math.min(params?.limit ?? 100, 500);
    const offset = params?.offset ?? 0;
    const qb = this.auditRepo
      .createQueryBuilder('a')
      .orderBy('a.created_at', 'DESC')
      .take(limit)
      .skip(offset);
    if (params?.actorUserId) {
      qb.andWhere('a.actor_user_id = :actorUserId', {
        actorUserId: params.actorUserId,
      });
    }
    if (params?.entityId) {
      qb.andWhere('a.entity_id = :entityId', { entityId: params.entityId });
    }
    const [items, total] = await qb.getManyAndCount();
    return { items, total };
  }

  async getPersonOverview(userId: string) {
    const itemLimit = AdminStaysService.PERSON_ITEMS_LIMIT;
    const openTicketStatuses = [...AdminStaysService.OPEN_TICKET_STATUSES];
    const upcomingStatuses = AdminStaysService.BOOKING_UPCOMING;
    const completedStatuses = AdminStaysService.BOOKING_COMPLETED;
    const cancelledStatuses = AdminStaysService.BOOKING_CANCELLED;

    const [
      hostRow,
      listingStatusRows,
      latestListings,
      hostBookingRows,
      guestBookingRows,
      hostBookingItems,
      guestBookingItems,
      reviewsWritten,
      hostReviewAgg,
      reportsMade,
      reportsAgainst,
      safetyIssuesMade,
      safetyIssuesAgainst,
      ticketsTotal,
      ticketsOpen,
      ticketItems,
    ] = await Promise.all([
      this.hostProfileRepo.findOne({ where: { user_id: userId } }),
      this.listingRepo
        .createQueryBuilder('l')
        .select('l.status', 'status')
        .addSelect('COUNT(*)', 'count')
        .where('l.host_user_id = :userId', { userId })
        .groupBy('l.status')
        .getRawMany<{ status: string; count: string }>(),
      this.listingRepo
        .createQueryBuilder('l')
        .leftJoinAndSelect('l.rate_plan', 'rate_plan')
        .where('l.host_user_id = :userId', { userId })
        .orderBy('l.created_at', 'DESC')
        .take(itemLimit)
        .getMany(),
      this.bookingRepo
        .createQueryBuilder('b')
        .innerJoin('b.listing', 'l')
        .select('b.status', 'status')
        .addSelect('COUNT(*)', 'count')
        .addSelect('COALESCE(SUM(b.payout_amount), 0)', 'amount')
        .where('l.host_user_id = :userId', { userId })
        .groupBy('b.status')
        .getRawMany<{ status: string; count: string; amount: string }>(),
      this.bookingRepo
        .createQueryBuilder('b')
        .select('b.status', 'status')
        .addSelect('COUNT(*)', 'count')
        .addSelect('COALESCE(SUM(b.total_paid), 0)', 'amount')
        .where('b.guest_user_id = :userId', { userId })
        .groupBy('b.status')
        .getRawMany<{ status: string; count: string; amount: string }>(),
      this.bookingRepo
        .createQueryBuilder('b')
        .innerJoin('b.listing', 'l')
        .where('l.host_user_id = :userId', { userId })
        .orderBy('b.created_at', 'DESC')
        .take(itemLimit)
        .getMany(),
      this.bookingRepo.find({
        where: { guest_user_id: userId },
        order: { created_at: 'DESC' },
        take: itemLimit,
      }),
      this.reviewRepo
        .createQueryBuilder('r')
        .where('r.guest_user_id = :userId', { userId })
        .andWhere("r.status <> 'REMOVED'")
        .getCount(),
      this.reviewRepo
        .createQueryBuilder('r')
        .leftJoin('r.listing', 'l')
        .select('COUNT(*)', 'received')
        .addSelect('AVG(r.rating)', 'average')
        .where(
          '(r.host_user_id = :userId OR (r.host_user_id IS NULL AND l.host_user_id = :userId))',
          { userId },
        )
        .andWhere('r.status = :published', { published: 'PUBLISHED' })
        .getRawOne<{ received: string; average: string | null }>(),
      this.reportRepo.count({ where: { reporter_user_id: userId } }),
      this.reportRepo.count({ where: { reported_user_id: userId } }),
      this.safetyRepo.count({ where: { reporter_user_id: userId } }),
      this.safetyRepo.count({ where: { reported_user_id: userId } }),
      this.ticketRepo.count({ where: { requester_user_id: userId } }),
      this.ticketRepo
        .createQueryBuilder('t')
        .where('t.requester_user_id = :userId', { userId })
        .andWhere('t.status IN (:...statuses)', {
          statuses: openTicketStatuses,
        })
        .getCount(),
      this.ticketRepo.find({
        where: { requester_user_id: userId },
        order: { created_at: 'DESC' },
        take: itemLimit,
      }),
    ]);

    const listingIds = latestListings.map((l) => l.id);
    const bookingCountRows =
      listingIds.length > 0
        ? await this.bookingRepo
            .createQueryBuilder('b')
            .select('b.listing_id', 'listing_id')
            .addSelect('COUNT(*)', 'count')
            .where('b.listing_id IN (:...listingIds)', { listingIds })
            .groupBy('b.listing_id')
            .getRawMany<{ listing_id: string; count: string }>()
        : [];
    const bookingCountByListing = new Map(
      bookingCountRows.map((r) => [r.listing_id, Number(r.count) || 0]),
    );

    const listingsByStatus: Record<string, number> = {};
    let listingsTotal = 0;
    for (const row of listingStatusRows) {
      const n = Number(row.count) || 0;
      listingsByStatus[row.status] = n;
      listingsTotal += n;
    }

    const hostBookings = this.summarizeBookings(
      hostBookingRows,
      upcomingStatuses,
      completedStatuses,
      cancelledStatuses,
    );
    const guestBookings = this.summarizeBookings(
      guestBookingRows,
      upcomingStatuses,
      completedStatuses,
      cancelledStatuses,
    );

    const received = Number(hostReviewAgg?.received ?? 0) || 0;
    const avgRaw = hostReviewAgg?.average;
    const averageRating =
      avgRaw == null || avgRaw === ''
        ? null
        : Number(Number(avgRaw).toFixed(2));

    return {
      userId,
      hostProfile: hostRow
        ? {
            id: hostRow.id,
            userId: hostRow.user_id,
            applicationStatus: hostRow.application_status,
            hostVerificationStatus: hostRow.host_verification_status,
            identityStatus: hostRow.identity_status,
            city: hostRow.city,
            listingFrozen: hostRow.listing_frozen,
            documentType: hostRow.document_type,
            documentFrontAssetId: hostRow.document_front_asset_id,
            documentBackAssetId: hostRow.document_back_asset_id,
            selfieAssetId: hostRow.selfie_asset_id,
            submittedAt: hostRow.submitted_at,
            reviewedAt: hostRow.reviewed_at,
            rejectionReason: hostRow.rejection_reason,
          }
        : null,
      listings: {
        total: listingsTotal,
        byStatus: listingsByStatus,
        items: latestListings.map((l) => ({
          id: l.id,
          title: l.title,
          status: l.status,
          city: l.city,
          price: this.toMoney(l.rate_plan?.base_price),
          bookingCount: bookingCountByListing.get(l.id) ?? 0,
          rating: l.avg_rating != null ? this.toMoney(l.avg_rating) : null,
        })),
      },
      bookingsAsHost: {
        total: hostBookings.total,
        upcoming: hostBookings.upcoming,
        completed: hostBookings.completed,
        cancelled: hostBookings.cancelled,
        totalPayout: hostBookings.amount,
        items: hostBookingItems.map((b) =>
          this.toCompactBooking(b, this.toMoney(b.payout_amount)),
        ),
      },
      bookingsAsGuest: {
        total: guestBookings.total,
        upcoming: guestBookings.upcoming,
        completed: guestBookings.completed,
        cancelled: guestBookings.cancelled,
        totalPaid: guestBookings.amount,
        items: guestBookingItems.map((b) =>
          this.toCompactBooking(b, this.toMoney(b.total_paid)),
        ),
      },
      reviews: {
        asGuest: { written: reviewsWritten },
        asHost: {
          received,
          averageRating: Number.isFinite(averageRating as number)
            ? averageRating
            : null,
        },
      },
      trust: {
        reportsMade,
        reportsAgainst,
        safetyIssuesMade,
        safetyIssuesAgainst,
      },
      tickets: {
        total: ticketsTotal,
        open: ticketsOpen,
        items: ticketItems.map((t) => ({
          id: t.id,
          ticketNumber: t.ticket_number,
          status: t.status,
          subject: t.subject,
          createdAt:
            t.created_at instanceof Date
              ? t.created_at.toISOString()
              : String(t.created_at),
        })),
      },
    };
  }

  async approveHost(
    hostProfileId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    return this.hostOnboarding.approve(hostProfileId, adminUserId, auditContext);
  }

  async rejectHost(
    hostProfileId: string,
    reason: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    return this.hostOnboarding.reject(
      hostProfileId,
      reason,
      adminUserId,
      auditContext,
    );
  }

  async freezeHost(
    hostProfileId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.hostProfileRepo.findOne({
      where: { id: hostProfileId },
    });
    if (!profile) throw new NotFoundException('Host profile not found');
    if (profile.host_verification_status !== 'APPROVED') {
      throw new BadRequestException('Only approved hosts can be frozen');
    }
    profile.listing_frozen = true;
    await this.hostProfileRepo.save(profile);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: hostProfileId,
        action: 'HOST_LISTING_FROZEN',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return {
      listing_frozen: true,
      message: 'Host listing access frozen. They can still book.',
    };
  }

  async unfreezeHost(
    hostProfileId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.hostProfileRepo.findOne({
      where: { id: hostProfileId },
    });
    if (!profile) throw new NotFoundException('Host profile not found');
    profile.listing_frozen = false;
    await this.hostProfileRepo.save(profile);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: hostProfileId,
        action: 'HOST_LISTING_UNFROZEN',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return { listing_frozen: false, message: 'Host can list again.' };
  }

  async approveListing(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({ where: { id: listingId } });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'SUBMITTED') {
      throw new BadRequestException('Only SUBMITTED listings can be approved');
    }
    listing.status = 'APPROVED';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_APPROVED',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return { status: 'APPROVED', message: 'Listing approved' };
  }

  async rejectListing(
    listingId: string,
    reason: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({ where: { id: listingId } });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'SUBMITTED') {
      throw new BadRequestException('Only SUBMITTED listings can be rejected');
    }
    listing.status = 'REJECTED';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_REJECTED',
        metadata: { reason },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    return { status: 'REJECTED', message: 'Listing rejected' };
  }

  async setListingLive(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({ where: { id: listingId } });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'APPROVED') {
      throw new BadRequestException('Only APPROVED listings can be set LIVE');
    }
    listing.status = 'LIVE';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_SET_LIVE',
        metadata: {},
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    void this.domainEvents.publish(EVENTS.LISTING_PUBLISHED, 'stays', {
      listingId,
      hostUserId: listing.host_user_id,
    });
    void this.seoFreshness.refreshForSearchCity(listing.city);
    return { status: 'LIVE', message: 'Listing is now live' };
  }

  /**
   * Admin "Freeze" / "Take Offline": LIVE | APPROVED -> PAUSED.
   * Mirrors the host pause transition (no ownership check) with an admin audit
   * row. PAUSED is an operational, fully recoverable state — never archive here.
   */
  async pauseListing(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({ where: { id: listingId } });
    if (!listing) throw new NotFoundException('Listing not found');
    if (!ADMIN_PAUSABLE_STATUSES.includes(listing.status)) {
      throw new BadRequestException(
        'Only LIVE or APPROVED listings can be paused',
      );
    }
    const previousStatus = listing.status;
    listing.paused_from_status =
      previousStatus === 'APPROVED' ? 'APPROVED' : 'LIVE';
    listing.status = 'PAUSED';
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_PAUSED',
        metadata: { previous_status: previousStatus },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    void this.seoFreshness.refreshForSearchCity(listing.city);
    return {
      status: 'PAUSED',
      message: 'Listing paused and hidden from search. It can be resumed later.',
    };
  }

  /**
   * Admin "Resume": PAUSED -> previous status (LIVE or APPROVED).
   * Respects host-wide `listing_frozen`. Never promotes APPROVED to LIVE —
   * that remains setListingLive only.
   */
  async unpauseListing(
    listingId: string,
    adminUserId: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const listing = await this.listingRepo.findOne({ where: { id: listingId } });
    if (!listing) throw new NotFoundException('Listing not found');
    if (listing.status !== 'PAUSED') {
      throw new BadRequestException('Only PAUSED listings can be resumed');
    }
    const hostProfile = await this.hostProfileRepo.findOne({
      where: { user_id: listing.host_user_id },
    });
    if (hostProfile?.listing_frozen) {
      throw new BadRequestException(
        'Host listing access is frozen. Unfreeze the host before resuming this listing.',
      );
    }
    const restoreTo =
      listing.paused_from_status === 'APPROVED' ? 'APPROVED' : 'LIVE';
    listing.status = restoreTo;
    listing.paused_from_status = null;
    await this.listingRepo.save(listing);
    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: adminUserId,
        actor_role: 'ADMIN',
        entity_type: 'LISTING',
        entity_id: listingId,
        action: 'LISTING_RESUMED',
        metadata: { restored_status: restoreTo },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );
    if (restoreTo === 'LIVE') {
      void this.domainEvents.publish(EVENTS.LISTING_PUBLISHED, 'stays', {
        listingId,
        hostUserId: listing.host_user_id,
      });
    }
    void this.seoFreshness.refreshForSearchCity(listing.city);
    return {
      status: restoreTo,
      message:
        restoreTo === 'LIVE'
          ? 'Listing is live again'
          : 'Listing restored to approved (not live). Use set-live when ready.',
    };
  }

  async checkHealth(): Promise<{ status: string; db: string }> {
    try {
      await this.listingRepo.query('SELECT 1');
      return { status: 'ok', db: 'connected' };
    } catch {
      return { status: 'degraded', db: 'disconnected' };
    }
  }

  private toMoney(value: unknown): number {
    const n = Number(value);
    return Number.isFinite(n) ? n : 0;
  }

  private toIsoDate(value: Date | string | null | undefined): string | null {
    if (value == null) return null;
    if (value instanceof Date) return value.toISOString().slice(0, 10);
    return String(value).slice(0, 10);
  }

  private summarizeBookings(
    rows: Array<{ status: string; count: string; amount: string }>,
    upcoming: readonly string[],
    completed: readonly string[],
    cancelled: readonly string[],
  ) {
    let total = 0;
    let upcomingCount = 0;
    let completedCount = 0;
    let cancelledCount = 0;
    let amount = 0;
    for (const row of rows) {
      const n = Number(row.count) || 0;
      total += n;
      amount += this.toMoney(row.amount);
      if (upcoming.includes(row.status)) upcomingCount += n;
      else if (completed.includes(row.status)) completedCount += n;
      else if (cancelled.includes(row.status)) cancelledCount += n;
    }
    return {
      total,
      upcoming: upcomingCount,
      completed: completedCount,
      cancelled: cancelledCount,
      amount,
    };
  }

  private toCompactBooking(booking: StaysBooking, amount: number) {
    return {
      id: booking.id,
      reference: booking.booking_reference,
      status: booking.status,
      checkinDate: this.toIsoDate(booking.checkin_date),
      checkoutDate: this.toIsoDate(booking.checkout_date),
      listingId: booking.listing_id,
      amount,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, IsNull, LessThan, In } from 'typeorm';
import { StaysMessageAttachment } from './entities/stays-message-attachment.entity';
import { StaysAttachmentSession } from './entities/stays-attachment-session.entity';
import { AttachmentService } from './attachment.service';
import { AttachmentSessionService } from './attachment-session.service';

const ORPHAN_AGE_MS = 24 * 60 * 60 * 1000;

@Injectable()
export class AttachmentCleanupScheduler {
  private readonly logger = new Logger(AttachmentCleanupScheduler.name);

  constructor(
    @InjectRepository(StaysMessageAttachment)
    private readonly attachmentRepo: Repository<StaysMessageAttachment>,
    @InjectRepository(StaysAttachmentSession)
    private readonly sessionRepo: Repository<StaysAttachmentSession>,
    private readonly attachments: AttachmentService,
    private readonly sessions: AttachmentSessionService,
  ) {}

  @Cron(CronExpression.EVERY_DAY_AT_2AM)
  async cleanupOrphanAttachments(): Promise<void> {
    const cutoff = new Date(Date.now() - ORPHAN_AGE_MS);
    let removed = 0;

    const abandonedSessions = await this.sessions.markExpiredSessionsAbandoned();
    if (abandonedSessions > 0) {
      this.logger.log(`Marked ${abandonedSessions} expired attachment sessions abandoned`);
    }

    const staleSessions = await this.sessionRepo.find({
      where: {
        status: In(['ABANDONED', 'CREATED', 'UPLOADING', 'READY']),
        updated_at: LessThan(cutoff),
      },
    });
    for (const session of staleSessions) {
      if (session.status === 'COMPLETED') continue;
      const items = await this.attachmentRepo.find({
        where: { session_id: session.id, message_id: IsNull() },
      });
      for (const row of items) {
        await this.attachments.deleteUnlinkedAttachment(row);
        removed++;
      }
      await this.sessionRepo.delete(session.id);
    }

    const orphanRows = await this.attachmentRepo
      .createQueryBuilder('a')
      .where('a.message_id IS NULL')
      .andWhere('a.session_id IS NULL')
      .andWhere('a.created_at < :cutoff', { cutoff })
      .andWhere(
        "(a.original_filename IS NULL OR a.original_filename NOT LIKE 'report-evidence:%')",
      )
      .getMany();
    for (const row of orphanRows) {
      await this.attachments.deleteUnlinkedAttachment(row);
      removed++;
    }

    if (removed > 0) {
      this.logger.log(`Cleaned up ${removed} orphan messaging attachments`);
    }
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, In, IsNull, LessThan } from 'typeorm';
import { StaysAttachmentSession } from './entities/stays-attachment-session.entity';
import { StaysMessageAttachment } from './entities/stays-message-attachment.entity';
import { StaysConversation } from './entities/stays-conversation.entity';
import { MessagingPermissionsService } from './permissions.service';
import { AttachmentService } from './attachment.service';
import type { AttachmentSessionDto } from './messaging.types';

const SESSION_TTL_MS = 24 * 60 * 60 * 1000;

@Injectable()
export class AttachmentSessionService {
  constructor(
    @InjectRepository(StaysAttachmentSession)
    private readonly sessionRepo: Repository<StaysAttachmentSession>,
    @InjectRepository(StaysMessageAttachment)
    private readonly attachmentRepo: Repository<StaysMessageAttachment>,
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    private readonly permissions: MessagingPermissionsService,
    private readonly attachments: AttachmentService,
  ) {}

  async createSession(
    conversationId: string,
    userId: string,
  ): Promise<AttachmentSessionDto> {
    const conv = await this.getWritableConversation(conversationId, userId);
    const expiresAt = new Date(Date.now() + SESSION_TTL_MS);
    const session = this.sessionRepo.create({
      conversation_id: conv.id,
      owner_user_id: userId,
      status: 'CREATED',
      expires_at: expiresAt,
    });
    const saved = await this.sessionRepo.save(session);
    return this.toDto(saved, []);
  }

  async getSession(
    sessionId: string,
    userId: string,
  ): Promise<AttachmentSessionDto> {
    const session = await this.getOwnedSession(sessionId, userId);
    const items = await this.attachmentRepo.find({
      where: { session_id: session.id },
      order: { created_at: 'ASC' },
    });
    return this.toDto(
      session,
      items.map((row) => this.attachments.toDto(row)),
    );
  }

  async uploadToSession(
    sessionId: string,
    userId: string,
    file: Express.Multer.File,
  ) {
    const session = await this.getOwnedSession(sessionId, userId);
    if (session.status === 'COMPLETED' || session.status === 'ABANDONED') {
      throw new BadRequestException('Session is closed');
    }
    if (session.expires_at.getTime() < Date.now()) {
      await this.sessionRepo.update(session.id, { status: 'ABANDONED' });
      throw new BadRequestException('Session expired');
    }

    if (session.status === 'CREATED') {
      await this.sessionRepo.update(session.id, { status: 'UPLOADING' });
    }

    const dto = await this.attachments.createFromUploadInSession(
      session.conversation_id,
      session.id,
      userId,
      file,
    );

    return dto;
  }

  async completeSession(
    sessionId: string,
    userId: string,
  ): Promise<AttachmentSessionDto> {
    const session = await this.getOwnedSession(sessionId, userId);
    if (session.status === 'COMPLETED') {
      return this.getSession(sessionId, userId);
    }
    if (session.status === 'ABANDONED') {
      throw new BadRequestException('Session abandoned');
    }

    const items = await this.attachmentRepo.find({
      where: { session_id: session.id },
    });
    if (!items.length) {
      throw new BadRequestException('No attachments in session');
    }

    const notReady = items.filter((a) => a.status !== 'READY');
    if (notReady.length) {
      throw new BadRequestException('Not all attachments are ready');
    }

    await this.sessionRepo.update(session.id, { status: 'READY' });
    const refreshed = await this.sessionRepo.findOneOrFail({
      where: { id: session.id },
    });
    return this.toDto(
      refreshed,
      items.map((row) => this.attachments.toDto(row)),
    );
  }

  async deleteAttachmentFromSession(
    sessionId: string,
    attachmentId: string,
    userId: string,
  ): Promise<void> {
    const session = await this.getOwnedSession(sessionId, userId);
    if (session.status === 'COMPLETED') {
      throw new BadRequestException('Session is finalized');
    }

    const row = await this.attachmentRepo.findOne({
      where: {
        id: attachmentId,
        session_id: session.id,
        uploader_user_id: userId,
        message_id: IsNull(),
      },
    });
    if (!row) throw new NotFoundException('Attachment not found');

    await this.attachments.deleteUnlinkedAttachment(row);
  }

  async abandonSession(sessionId: string, userId: string): Promise<void> {
    const session = await this.getOwnedSession(sessionId, userId);
    if (session.status === 'COMPLETED') {
      throw new BadRequestException('Session is finalized');
    }

    const items = await this.attachmentRepo.find({
      where: { session_id: session.id, message_id: IsNull() },
    });
    for (const row of items) {
      await this.attachments.deleteUnlinkedAttachment(row);
    }
    await this.sessionRepo.update(session.id, { status: 'ABANDONED' });
  }

  async assertSessionReadyForSend(
    conversationId: string,
    userId: string,
    sessionId: string,
  ): Promise<{ session: StaysAttachmentSession; attachments: StaysMessageAttachment[] }> {
    const session = await this.sessionRepo.findOne({
      where: { id: sessionId, conversation_id: conversationId, owner_user_id: userId },
    });
    if (!session) throw new BadRequestException('Invalid session');
    if (session.status !== 'READY') {
      throw new BadRequestException('Session not ready — call complete first');
    }
    if (session.expires_at.getTime() < Date.now()) {
      throw new BadRequestException('Session expired');
    }

    const attachments = await this.attachmentRepo.find({
      where: { session_id: session.id, message_id: IsNull() },
      order: { created_at: 'ASC' },
    });
    if (!attachments.length) {
      throw new BadRequestException('Session has no attachments');
    }
    for (const row of attachments) {
      if (row.status !== 'READY') {
        throw new BadRequestException('Attachment not ready');
      }
    }
    return { session, attachments };
  }

  async finalizeSession(sessionId: string): Promise<void> {
    await this.sessionRepo.update(sessionId, { status: 'COMPLETED' });
  }

  async markExpiredSessionsAbandoned(): Promise<number> {
    const now = new Date();
    const expired = await this.sessionRepo.find({
      where: {
        status: In(['CREATED', 'UPLOADING', 'READY']),
        expires_at: LessThan(now),
      },
    });
    for (const session of expired) {
      await this.abandonSessionInternal(session.id);
    }
    return expired.length;
  }

  private async abandonSessionInternal(sessionId: string): Promise<void> {
    const items = await this.attachmentRepo.find({
      where: { session_id: sessionId, message_id: IsNull() },
    });
    for (const row of items) {
      await this.attachments.deleteUnlinkedAttachment(row);
    }
    await this.sessionRepo.update(sessionId, { status: 'ABANDONED' });
  }

  private toDto(
    session: StaysAttachmentSession,
    attachments: AttachmentSessionDto['attachments'],
  ): AttachmentSessionDto {
    return {
      id: session.id,
      conversationId: session.conversation_id,
      status: session.status,
      expiresAt: session.expires_at.toISOString(),
      attachments,
    };
  }

  private async getOwnedSession(
    sessionId: string,
    userId: string,
  ): Promise<StaysAttachmentSession> {
    const session = await this.sessionRepo.findOne({ where: { id: sessionId } });
    if (!session || session.owner_user_id !== userId) {
      throw new NotFoundException('Session not found');
    }
    await this.getParticipantConversation(session.conversation_id, userId);
    return session;
  }

  private async getWritableConversation(
    conversationId: string,
    userId: string,
  ): Promise<StaysConversation> {
    const conv = await this.getParticipantConversation(conversationId, userId);
    const perms = this.permissions.resolve(conv, userId);
    if (!perms.canUpload) throw new ForbiddenException('Upload not allowed');
    return conv;
  }

  private async getParticipantConversation(
    conversationId: string,
    userId: string,
  ): Promise<StaysConversation> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    return conv;
  }
}

import {
  BadRequestException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, In, IsNull, EntityManager } from 'typeorm';
import { StaysMessageAttachment } from './entities/stays-message-attachment.entity';
import { StaysConversation } from './entities/stays-conversation.entity';
import { StaysMediaAsset } from './entities/stays-media-asset.entity';
import { MessagingPermissionsService } from './permissions.service';
import { MessagingMediaService } from './messaging-media.service';
import { MediaAssetService } from './media-asset.service';
import { isImageMime } from '../../common/utils/attachment-mime.util';
import type { AttachmentDto } from './messaging.types';

const MAX_BYTES = 20 * 1024 * 1024;
const ALLOWED_DECLARED_MIMES = new Set([
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp',
  'image/gif',
  'application/pdf',
  'audio/webm',
  'audio/ogg',
  'audio/mp4',
  'audio/mpeg',
  'audio/mp3',
  'audio/x-m4a',
]);

@Injectable()
export class AttachmentService {
  constructor(
    @InjectRepository(StaysMessageAttachment)
    private readonly attachmentRepo: Repository<StaysMessageAttachment>,
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    @InjectRepository(StaysMediaAsset)
    private readonly mediaAssetRepo: Repository<StaysMediaAsset>,
    private readonly permissions: MessagingPermissionsService,
    private readonly media: MessagingMediaService,
    private readonly mediaAssets: MediaAssetService,
  ) {}

  /** @deprecated Prefer attachment session upload flow */
  async createFromUpload(
    conversationId: string,
    userId: string,
    file: Express.Multer.File,
  ): Promise<AttachmentDto> {
    const conv = await this.getWritableConversation(conversationId, userId);
    return this.ingestFile(conv.id, null, userId, file);
  }

  /**
   * Report/safety evidence upload — participant only (works when messaging is locked).
   * Images only; max 3 referenced later via report/safety attachmentIds.
   */
  async createEvidenceFromUpload(
    conversationId: string,
    userId: string,
    file: Express.Multer.File,
  ): Promise<AttachmentDto> {
    await this.getParticipantConversation(conversationId, userId);
    if (!file?.buffer?.length) throw new BadRequestException('No file uploaded');
    const declaredMime = (file.mimetype || '').toLowerCase().split(';')[0].trim();
    if (!declaredMime.startsWith('image/') || !ALLOWED_DECLARED_MIMES.has(declaredMime)) {
      throw new BadRequestException('Only image screenshots are allowed');
    }
    return this.ingestFile(conversationId, null, userId, file);
  }

  /** Keep evidence out of orphan attachment cleanup after a successful report. */
  async markAsReportEvidence(attachmentIds: string[]): Promise<void> {
    if (!attachmentIds.length) return;
    const rows = await this.attachmentRepo.find({
      where: { id: In(attachmentIds), message_id: IsNull() },
    });
    for (const row of rows) {
      const name = row.original_filename ?? 'screenshot';
      if (name.startsWith('report-evidence:')) continue;
      await this.attachmentRepo.update(row.id, {
        original_filename: `report-evidence:${name}`.slice(0, 500),
      });
    }
  }

  async createFromUploadInSession(
    conversationId: string,
    sessionId: string,
    userId: string,
    file: Express.Multer.File,
  ): Promise<AttachmentDto> {
    await this.getWritableConversation(conversationId, userId);
    return this.ingestFile(conversationId, sessionId, userId, file);
  }

  async getAttachment(
    conversationId: string,
    attachmentId: string,
    userId: string,
  ): Promise<AttachmentDto> {
    await this.getParticipantConversation(conversationId, userId);
    const row = await this.attachmentRepo.findOne({
      where: { id: attachmentId, conversation_id: conversationId },
    });
    if (!row) throw new NotFoundException('Attachment not found');
    return this.toDto(row);
  }

  async linkToMessage(
    messageId: string,
    attachmentIds: string[],
    conversationId?: string,
    manager?: EntityManager,
  ): Promise<void> {
    if (!attachmentIds.length) return;
    const repo = manager
      ? manager.getRepository(StaysMessageAttachment)
      : this.attachmentRepo;
    await repo.update(
      { id: In(attachmentIds), message_id: IsNull() },
      { message_id: messageId },
    );
    if (conversationId) {
      await this.bumpAttachmentVersion(conversationId, manager);
    }
  }

  async loadForMessages(
    messages: Array<{ id: string; metadata?: Record<string, unknown> }>,
  ): Promise<Map<string, AttachmentDto[]>> {
    if (!messages.length) return new Map();

    for (const message of messages) {
      const attachmentIds = (message.metadata?.attachment_ids as string[] | undefined) ?? [];
      if (attachmentIds.length) {
        await this.linkToMessage(message.id, attachmentIds);
      }
    }

    const messageIds = messages.map((m) => m.id);
    const rows = await this.attachmentRepo.find({
      where: { message_id: In(messageIds) },
      order: { created_at: 'ASC' },
    });
    const map = new Map<string, AttachmentDto[]>();
    for (const row of rows) {
      if (!row.message_id) continue;
      const list = map.get(row.message_id) ?? [];
      list.push(this.toDto(row));
      map.set(row.message_id, list);
    }
    return map;
  }

  async assertReadyForSend(
    conversationId: string,
    userId: string,
    attachmentIds: string[],
  ): Promise<StaysMessageAttachment[]> {
    if (!attachmentIds.length) return [];
    const rows = await this.attachmentRepo.find({
      where: {
        id: In(attachmentIds),
        conversation_id: conversationId,
        uploader_user_id: userId,
      },
    });
    if (rows.length !== attachmentIds.length) {
      throw new BadRequestException('Invalid attachment references');
    }
    for (const row of rows) {
      if (row.status !== 'READY') {
        throw new BadRequestException('Attachment not ready');
      }
    }
    return rows;
  }

  async assertEvidenceReady(
    conversationId: string,
    userId: string,
    attachmentIds: string[],
  ): Promise<StaysMessageAttachment[]> {
    const rows = await this.assertReadyForSend(conversationId, userId, attachmentIds);
    for (const row of rows) {
      if (!row.mime || !isImageMime(row.mime)) {
        throw new BadRequestException('Only image screenshots are allowed');
      }
    }
    return rows;
  }

  async deleteUnlinkedAttachment(row: StaysMessageAttachment): Promise<void> {
    if (row.message_id) return;

    if (row.media_asset_id) {
      const asset = await this.mediaAssetRepo.findOne({
        where: { id: row.media_asset_id },
      });
      if (asset) {
        await this.safeUnlink(asset.storage_key);
        if (asset.thumbnail_storage_key) {
          await this.safeUnlink(asset.thumbnail_storage_key);
        }
        await this.mediaAssetRepo.delete(asset.id);
      }
    } else {
      await this.safeUnlink(row.storage_url);
      if (row.thumbnail_url && row.thumbnail_url !== row.storage_url) {
        await this.safeUnlink(row.thumbnail_url);
      }
    }

    await this.attachmentRepo.delete(row.id);
  }

  resolveStoragePath(storageUrl: string): string {
    return this.mediaAssets.resolveStoragePath(storageUrl);
  }

  resolveDelivery(storageUrl: string): Promise<string> {
    return this.mediaAssets.resolveDelivery(storageUrl);
  }

  toDto(row: StaysMessageAttachment): AttachmentDto {
    const version = row.media_version ?? 1;
    const thumb = row.thumbnail_url
      ? this.media.resolveAttachment(row.id, 'thumb', version)
      : null;
    const full =
      row.status === 'READY'
        ? this.media.resolveAttachment(row.id, 'full', version)
        : null;
    return {
      id: row.id,
      sessionId: row.session_id,
      mediaAssetId: row.media_asset_id,
      processingStatus: row.status,
      status: row.status,
      virusScanStatus: row.virus_scan_status,
      mime: row.mime,
      sizeBytes: row.size_bytes ? Number(row.size_bytes) : null,
      width: row.width,
      height: row.height,
      orientation: row.orientation,
      durationMs: row.duration_ms,
      checksum: row.checksum_sha256,
      blurhash: row.blurhash,
      originalFilename: row.original_filename,
      thumbnail: thumb,
      full,
      original: full,
    };
  }

  async bumpAttachmentVersion(
    conversationId: string,
    manager?: EntityManager,
  ): Promise<number> {
    const convRepo = manager
      ? manager.getRepository(StaysConversation)
      : this.convRepo;
    const conv = await convRepo.findOne({ where: { id: conversationId } });
    if (!conv) return 1;
    const next = (conv.attachment_version ?? 1) + 1;
    await convRepo.update(conversationId, { attachment_version: next });
    return next;
  }

  private async ingestFile(
    conversationId: string,
    sessionId: string | null,
    userId: string,
    file: Express.Multer.File,
  ): Promise<AttachmentDto> {
    if (!file?.buffer?.length) throw new BadRequestException('No file uploaded');
    if (file.size > MAX_BYTES) throw new BadRequestException('File too large');

    const declaredMime = (file.mimetype || '').toLowerCase().split(';')[0].trim();
    if (declaredMime && !ALLOWED_DECLARED_MIMES.has(declaredMime)) {
      throw new BadRequestException('Unsupported file type');
    }

    const row = this.attachmentRepo.create({
      conversation_id: conversationId,
      session_id: sessionId,
      uploader_user_id: userId,
      message_id: null,
      status: 'UPLOADING',
      storage_url: '',
      thumbnail_url: null,
      original_filename: file.originalname || 'upload',
      mime: declaredMime || null,
      virus_scan_status: 'PENDING',
    });
    const pending = await this.attachmentRepo.save(row);

    try {
      await this.attachmentRepo.update(pending.id, { status: 'PROCESSING' });

      const processed = await this.mediaAssets.processAndStore({
        buffer: file.buffer,
        declaredMime,
        conversationId,
      });

      const isImage = isImageMime(processed.mime);
      const virusStatus = isImage ? 'SAFE' : 'PENDING';

      await this.attachmentRepo.update(pending.id, {
        media_asset_id: processed.asset.id,
        storage_url: processed.storageKey,
        thumbnail_url: processed.thumbnailKey ?? (isImage ? processed.storageKey : null),
        mime: processed.mime,
        width: processed.width,
        height: processed.height,
        checksum_sha256: processed.checksum,
        size_bytes: String(file.size),
        status: 'READY',
        virus_scan_status: virusStatus,
        media_version: 1,
      });

      const saved = await this.attachmentRepo.findOneOrFail({
        where: { id: pending.id },
      });
      return this.toDto(saved);
    } catch (err) {
      await this.attachmentRepo.update(pending.id, { status: 'FAILED' });
      const message = err instanceof Error ? err.message : 'Upload failed';
      throw new BadRequestException(message);
    }
  }

  private async safeUnlink(storageKey: string): Promise<void> {
    try {
      await this.mediaAssets.deleteObject(storageKey);
    } catch {
      // ignore missing files
    }
  }

  private async getWritableConversation(
    conversationId: string,
    userId: string,
  ): Promise<StaysConversation> {
    const conv = await this.getParticipantConversation(conversationId, userId);
    const perms = this.permissions.resolve(conv, userId);
    if (!perms.canUpload) throw new ForbiddenException('Upload not allowed');
    return conv;
  }

  private async getParticipantConversation(
    conversationId: string,
    userId: string,
  ): Promise<StaysConversation> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    return conv;
  }
}

import { Injectable } from '@nestjs/common';
import { StaysConversation } from './entities/stays-conversation.entity';
import { MessagingMediaService } from './messaging-media.service';
import { IdentityProfilePhotoClient } from '../../common/identity/identity-profile-photo.client';
import { ParticipantPresentationService } from './participant-presentation.service';
import { IdentityUserClient } from '../../common/identity/identity-user.client';
import type {
  ConversationPresentation,
  ConversationSyncMeta,
  ReservationPresentation,
  ReservationSnapshot,
  SignedMedia,
} from './messaging.types';

function formatShortDate(value: string): string {
  return new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function bookingLifecycleSubtitle(
  status: string | null | undefined,
  messagingState?: string,
): string {
  const s = (status ?? '').toUpperCase();
  if (messagingState === 'ARCHIVED') return 'Archived';
  if (s === 'COMPLETED') return 'Stay completed';
  if (s === 'CHECKED_IN') return 'Current Stay';
  if (s === 'CONFIRMED') return 'Upcoming Stay';
  if (s === 'CANCELLED' || s === 'CANCELLED_BY_GUEST' || s === 'CANCELLED_BY_HOST') {
    return 'Cancelled';
  }
  if (s === 'EXPIRED') return 'Expired';
  return 'Stay';
}

@Injectable()
export class ConversationPresentationService {
  constructor(
    private readonly media: MessagingMediaService,
    private readonly profilePhotos: IdentityProfilePhotoClient,
    private readonly participants: ParticipantPresentationService,
    private readonly identityUsers: IdentityUserClient,
  ) {}

  async buildPresentation(
    conv: StaysConversation,
    viewerUserId: string,
    snapshot: ReservationSnapshot,
    bookingStatus?: string | null,
  ): Promise<ConversationPresentation> {
    if (conv.type === 'SUPPORT') {
      return this.buildSupportPresentation(conv, snapshot);
    }

    const isGuest = conv.guest_user_id === viewerUserId;
    const counterpartId = isGuest ? conv.host_user_id : conv.guest_user_id;
    const counterpart = await this.participants.resolveCounterpartIdentity(
      conv.host_user_id ?? '',
      conv.guest_user_id,
      conv.booking_id,
      isGuest,
    );

    const profileSummary = counterpartId
      ? await this.identityUsers.getProfileSummary(counterpartId)
      : null;

    const avatar = counterpartId
      ? await this.resolveCounterpartAvatar(counterpartId, conv.snapshot_version ?? 1)
      : null;
    const reservation = this.buildReservationPresentation(conv, snapshot);
    const subtitle = bookingLifecycleSubtitle(bookingStatus, conv.messaging_state);
    const bookingChip = `${snapshot.listingTitle} • ${formatShortDate(snapshot.checkinDate)}–${formatShortDate(snapshot.checkoutDate)} • ${snapshot.guestCount} guests`;

    return {
      title: profileSummary?.fullName ?? counterpart.displayName,
      subtitle,
      avatar,
      bookingChip,
      statusChip: subtitle,
      counterpart: {
        id: counterpartId ?? '',
        displayName: profileSummary?.fullName ?? counterpart.displayName,
        verified: profileSummary?.verified ?? false,
        rating: null,
      },
      listing: {
        title: snapshot.listingTitle ?? 'Stay',
        city: snapshot.city ?? null,
      },
      reservation,
    };
  }

  /** Customer ↔ Nexa Support threads have no host counterpart or stay dates. */
  private buildSupportPresentation(
    conv: StaysConversation,
    snapshot: ReservationSnapshot,
  ): ConversationPresentation {
    const subject =
      snapshot.listingTitle?.trim() ||
      snapshot.hostDisplayName?.trim() ||
      'Support request';
    const ticketRef = snapshot.bookingReference?.trim() || null;
    const subtitle = ticketRef ?? 'Support';
    const reservation = this.buildReservationPresentation(conv, {
      ...snapshot,
      listingTitle: subject,
      checkinDate: snapshot.checkinDate || '',
      checkoutDate: snapshot.checkoutDate || '',
      guestCount: snapshot.guestCount ?? 0,
      hostDisplayName: 'Nexa Support',
    });

    return {
      title: 'Nexa Support',
      subtitle,
      avatar: null,
      bookingChip: ticketRef ? `${subject} • ${ticketRef}` : subject,
      statusChip: 'Support',
      counterpart: {
        id: '',
        displayName: 'Nexa Support',
        verified: true,
        rating: null,
      },
      listing: {
        title: subject,
        city: snapshot.city ?? null,
      },
      reservation,
    };
  }

  buildSyncMeta(conv: StaysConversation, viewerUserId: string): ConversationSyncMeta {
    const isGuest = conv.guest_user_id === viewerUserId;
    const unreadCount = isGuest ? conv.unread_guest ?? 0 : conv.unread_host ?? 0;
    const messageId = isGuest
      ? conv.guest_last_read_message_id
      : conv.host_last_read_message_id;
    const readAt = isGuest ? conv.guest_last_read_at : conv.host_last_read_at;

    return {
      conversationVersion: conv.conversation_version,
      snapshotVersion: conv.snapshot_version ?? 1,
      attachmentVersion: conv.attachment_version ?? 1,
      lastMessageId: conv.last_message_id ?? null,
      unreadCount,
      lastReadPointer: {
        messageId: messageId ?? null,
        readAt: readAt?.toISOString() ?? null,
      },
    };
  }

  private async resolveCounterpartAvatar(
    userId: string,
    version: number,
  ): Promise<SignedMedia | null> {
    if (!userId) return null;
    const hasPhoto = await this.profilePhotos.hasProfilePhoto(userId);
    if (!hasPhoto) return null;
    return this.media.resolveAvatar(userId, version);
  }

  private buildReservationPresentation(
    conv: StaysConversation,
    snapshot: ReservationSnapshot,
  ): ReservationPresentation {
    const listingId = snapshot.listingId ?? conv.listing_id ?? null;
    const coverMediaId = snapshot.coverMediaId ?? null;
    const coverMedia =
      listingId && coverMediaId
        ? this.media.resolveListingCover(listingId, coverMediaId, {
            w: 640,
            h: 360,
            fit: 'crop',
          }, conv.snapshot_version ?? 1)
        : null;

    return {
      listingTitle: snapshot.listingTitle ?? 'Stay',
      listingId,
      coverMedia,
      addressDisplay: snapshot.addressDisplay ?? null,
      city: snapshot.city ?? null,
      country: snapshot.country ?? null,
      checkinDate: snapshot.checkinDate,
      checkoutDate: snapshot.checkoutDate,
      guestCount: snapshot.guestCount,
      bookingReference: snapshot.bookingReference ?? null,
      bookingId: conv.booking_id ?? null,
    };
  }
}

import {
  Injectable,
  Logger,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
} from '@nestjs/common';
import { DataSource, EntityManager } from 'typeorm';
import { StaysBooking } from '../stays/entities/stays-booking.entity';
import { StaysListing } from '../stays/entities/stays-listing.entity';
import { StaysConversation } from './entities/stays-conversation.entity';
import { MessagingOutboxService } from './outbox.service';
import { TimelineSeederService } from './timeline-seeder.service';
import { ParticipantPresentationService } from './participant-presentation.service';
import { MESSAGING_INTERNAL_EVENTS } from './messaging-internal.events';
import { EVENTS } from '@nexa/event-bus';

const MESSAGEABLE_BOOKING_STATUSES = new Set([
  'CONFIRMED',
  'CHECKED_IN',
  'COMPLETED',
]);

function resolvePaymentProviderIntentId(
  bookingId: string,
  providerIntentId?: string | null,
  paymentIntentId?: string | null,
): string {
  const candidate = (providerIntentId ?? paymentIntentId ?? '').trim();
  return candidate || `booking-${bookingId}`;
}

@Injectable()
export class ConversationProvisionService {
  private readonly logger = new Logger(ConversationProvisionService.name);

  constructor(
    private readonly dataSource: DataSource,
    private readonly timelineSeeder: TimelineSeederService,
    private readonly outbox: MessagingOutboxService,
    private readonly participants: ParticipantPresentationService,
  ) {}

  /**
   * Must run inside the payment success transaction.
   */
  async provisionWithinTransaction(
    manager: EntityManager,
    booking: StaysBooking,
    listingId: string,
    provider?: string,
    providerIntentId?: string,
  ): Promise<StaysConversation | null> {
    const convRepo = manager.getRepository(StaysConversation);
    const listingRepo = manager.getRepository(StaysListing);
    const existing = await convRepo.findOne({ where: { booking_id: booking.id } });
    if (existing) return existing;

    const listing = await listingRepo.findOne({
      where: { id: listingId },
      relations: ['media', 'check_in_contact'],
    });
    if (!listing) return null;

    if (!listing.host_user_id) {
      this.logger.warn(`No host for booking ${booking.id}; skipping conversation`);
      return null;
    }

    const hostName = await this.participants.resolveHostDisplayName(listing.host_user_id);
    const guestName = await this.participants.resolveGuestDisplayName(booking.id);

    const snapshot = this.timelineSeeder.buildSnapshot(booking, listing, {
      hostDisplayName: hostName,
      guestDisplayName: guestName,
    });

    const conversation = await convRepo.save(
      convRepo.create({
        booking_id: booking.id,
        type: 'BOOKING',
        messaging_state: 'ACTIVE',
        listing_id: listing.id,
        host_user_id: listing.host_user_id,
        guest_user_id: booking.guest_user_id,
        snapshot_version: 1,
        reservation_snapshot: snapshot as unknown as Record<string, unknown>,
        conversation_version: 1,
      }),
    );

    await this.timelineSeeder.seedBookingConfirmed(manager, conversation, snapshot, listing);

    const total = Number(booking.total_paid ?? 0);
    const currency = booking.currency ?? 'MAD';

    await this.outbox.enqueue(manager, EVENTS.BOOKING_CONFIRMED, {
      bookingId: booking.id,
      listingId: listing.id,
      hostUserId: listing.host_user_id,
      guestUserId: booking.guest_user_id,
      amount: String(total),
      currency,
      conversationId: conversation.id,
    });

    await this.outbox.enqueue(manager, EVENTS.PAYMENT_SUCCEEDED, {
      bookingId: booking.id,
      guestUserId: booking.guest_user_id,
      provider: provider ?? 'payment',
      providerIntentId: resolvePaymentProviderIntentId(
        booking.id,
        providerIntentId,
        booking.payment_intent_id,
      ),
      amount: String(total),
      currency,
    });

    return conversation;
  }

  /** Backfill or return the booking thread (guest or host). */
  async ensureForBooking(
    bookingId: string,
    userId: string,
  ): Promise<StaysConversation> {
    const conv = await this.dataSource.transaction(async (manager) => {
      const convRepo = manager.getRepository(StaysConversation);
      const existing = await convRepo.findOne({ where: { booking_id: bookingId } });
      if (existing) {
        if (
          existing.guest_user_id !== userId &&
          existing.host_user_id !== userId
        ) {
          throw new ForbiddenException('Not a participant on this booking');
        }
        await this.outbox.enqueue(manager, MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED, {
          conversationId: existing.id,
        });
        return existing;
      }

      const bookingRepo = manager.getRepository(StaysBooking);
      const booking = await bookingRepo.findOne({
        where: { id: bookingId },
      });
      if (!booking) {
        throw new NotFoundException('Booking not found');
      }

      const listingRepo = manager.getRepository(StaysListing);
      const listing = await listingRepo.findOne({
        where: { id: booking.listing_id },
      });
      const hostUserId = listing?.host_user_id ?? null;
      const isGuest = booking.guest_user_id === userId;
      const isHost = hostUserId === userId;
      if (!isGuest && !isHost) {
        throw new ForbiddenException('Not a participant on this booking');
      }
      if (!MESSAGEABLE_BOOKING_STATUSES.has(booking.status)) {
        throw new BadRequestException(
          'Messaging is available after the booking is confirmed',
        );
      }

      const created = await this.provisionWithinTransaction(
        manager,
        booking,
        booking.listing_id,
        'backfill',
        booking.payment_intent_id ?? undefined,
      );
      if (!created) {
        throw new BadRequestException(
          'Could not open conversation for this booking',
        );
      }
      return created;
    });

    await this.outbox.enqueueDirect(MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED, {
      conversationId: conv.id,
    });

    return conv;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { DataSource, In } from 'typeorm';
import { StaysBooking } from '../stays/entities/stays-booking.entity';
import { StaysListing } from '../stays/entities/stays-listing.entity';
import { StaysConversation } from './entities/stays-conversation.entity';
import { StaysMessage } from './entities/stays-message.entity';
import { TimelineSeederService } from './timeline-seeder.service';
import { ParticipantPresentationService } from './participant-presentation.service';
import { ConversationProvisionService } from './conversation-provision.service';
import { formatInboxPreview } from './message-preview.util';

const MESSAGEABLE_STATUSES = new Set(['CONFIRMED', 'CHECKED_IN', 'COMPLETED']);

type OrphanRow = { conversation_id: string };

@Injectable()
export class ConversationRepairService {
  private readonly logger = new Logger(ConversationRepairService.name);

  constructor(
    private readonly dataSource: DataSource,
    private readonly timelineSeeder: TimelineSeederService,
    private readonly participants: ParticipantPresentationService,
    private readonly provision: ConversationProvisionService,
  ) {}

  /** Restore missing inbox threads for the current user (orphaned messages + missing booking threads). */
  async repairForUser(userId: string): Promise<void> {
    await this.repairOrphanedThreads(userId);
    await this.dedupeDuplicateBookingThreads(userId);
    await this.ensureMissingBookingThreads(userId);
  }

  private async repairOrphanedThreads(userId: string): Promise<void> {
    const orphans = await this.dataSource.query<OrphanRow[]>(`
      SELECT DISTINCT m.conversation_id
      FROM stays_messages m
      LEFT JOIN stays_conversations c ON c.id = m.conversation_id
      WHERE c.id IS NULL
    `);

    for (const { conversation_id: conversationId } of orphans) {
      try {
        await this.repairOrphanThread(conversationId, userId);
      } catch (err) {
        this.logger.warn(
          `Failed to repair orphaned thread ${conversationId}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }
  }

  private async repairOrphanThread(
    conversationId: string,
    userId: string,
  ): Promise<void> {
    const messageRepo = this.dataSource.getRepository(StaysMessage);
    const messages = await messageRepo.find({
      where: { conversation_id: conversationId },
      order: { conversation_sequence: 'ASC' },
    });
    if (messages.length === 0) return;

    const bookingId =
      this.resolveBookingIdFromMessages(messages) ??
      (await this.resolveBookingIdFromParticipants(messages));
    if (!bookingId) {
      this.logger.warn(`Orphan thread ${conversationId} has no booking reference`);
      return;
    }

    const bookingRepo = this.dataSource.getRepository(StaysBooking);
    const listingRepo = this.dataSource.getRepository(StaysListing);
    const booking = await bookingRepo.findOne({ where: { id: bookingId } });
    if (!booking) return;

    const listing = await listingRepo.findOne({
      where: { id: booking.listing_id },
      relations: ['media', 'check_in_contact'],
    });
    if (!listing?.host_user_id) return;

    const isParticipant =
      booking.guest_user_id === userId || listing.host_user_id === userId;
    if (!isParticipant) return;

    const existing = await this.dataSource
      .getRepository(StaysConversation)
      .findOne({ where: { booking_id: bookingId } });
    if (existing) {
      if (existing.id !== conversationId) {
        await this.mergeMessagesIntoConversation(conversationId, existing.id);
        this.logger.log(
          `Merged orphan thread ${conversationId} into booking conversation ${existing.id}`,
        );
      }
      return;
    }

    const hostName = await this.participants.resolveHostDisplayName(listing.host_user_id);
    const guestName = await this.participants.resolveGuestDisplayName(booking.id);
    const snapshot = this.timelineSeeder.buildSnapshot(booking, listing, {
      hostDisplayName: hostName,
      guestDisplayName: guestName,
    });

    const lastMessage = messages[messages.length - 1];
    const preview = formatInboxPreview({
      type: lastMessage.type,
      body: lastMessage.body,
      metadata: lastMessage.metadata,
    });

    await this.dataSource.query(
      `
      INSERT INTO stays_conversations (
        id, booking_id, type, messaging_state, guest_visibility, host_visibility,
        conversation_version, snapshot_version, attachment_version, reservation_snapshot,
        listing_id, host_user_id, guest_user_id, last_message_id, last_message_sequence,
        last_message_preview, last_message_at, created_at, updated_at
      ) VALUES (
        $1, $2, 'BOOKING', 'ACTIVE', 'ACTIVE', 'ACTIVE',
        1, 1, 1, $3::jsonb,
        $4, $5, $6, $7, $8,
        $9, $10, NOW(), NOW()
      )
      ON CONFLICT (id) DO NOTHING
      `,
      [
        conversationId,
        bookingId,
        JSON.stringify(snapshot),
        listing.id,
        listing.host_user_id,
        booking.guest_user_id,
        lastMessage.id,
        lastMessage.conversation_sequence,
        preview,
        lastMessage.created_at,
      ],
    );

    this.logger.log(`Repaired orphaned conversation ${conversationId} for booking ${bookingId}`);
  }

  private resolveBookingIdFromMessages(messages: StaysMessage[]): string | null {
    for (const message of messages) {
      const meta = message.metadata as Record<string, unknown> | null;
      const bookingId = meta?.bookingId;
      if (typeof bookingId === 'string' && bookingId.length > 0) {
        return bookingId;
      }
    }

    for (const message of messages) {
      const meta = message.metadata as Record<string, unknown> | null;
      const actions = meta?.actions;
      if (!Array.isArray(actions)) continue;
      for (const action of actions) {
        if (!action || typeof action !== 'object') continue;
        const url = (action as { url?: unknown }).url;
        if (typeof url !== 'string') continue;
        const match = /\/bookings\/([0-9a-f-]{36})/i.exec(url);
        if (match?.[1]) return match[1];
      }
    }

    return null;
  }

  private async resolveBookingIdFromParticipants(
    messages: StaysMessage[],
  ): Promise<string | null> {
    const senderIds = [
      ...new Set(
        messages
          .map((m) => m.sender_id)
          .filter((id): id is string => typeof id === 'string' && id.length > 0),
      ),
    ];
    if (senderIds.length === 0) return null;

    let listingId: string | null = null;
    for (const message of messages) {
      const meta = message.metadata as Record<string, unknown> | null;
      if (typeof meta?.listingId === 'string') {
        listingId = meta.listingId;
        break;
      }
      const snapshot = meta?.snapshot as { primaryPhotoUrl?: unknown } | undefined;
      if (typeof snapshot?.primaryPhotoUrl === 'string') {
        const match = /\/listings\/([0-9a-f-]{36})\//i.exec(snapshot.primaryPhotoUrl);
        if (match?.[1]) {
          listingId = match[1];
          break;
        }
      }
    }
    if (!listingId) return null;

    const bookingRepo = this.dataSource.getRepository(StaysBooking);
    const candidates = await bookingRepo.find({
      where: { listing_id: listingId },
      order: { created_at: 'DESC' },
      take: 20,
    });

    for (const senderId of senderIds) {
      const match = candidates.find(
        (b) => MESSAGEABLE_STATUSES.has(b.status) && b.guest_user_id === senderId,
      );
      if (match) return match.id;
    }

    return null;
  }

  private async mergeMessagesIntoConversation(
    fromConversationId: string,
    toConversationId: string,
  ): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      const messageRepo = manager.getRepository(StaysMessage);
      const convRepo = manager.getRepository(StaysConversation);

      const orphanMessages = await messageRepo.find({
        where: { conversation_id: fromConversationId },
        order: { conversation_sequence: 'ASC' },
      });
      if (orphanMessages.length === 0) {
        await convRepo.delete({ id: fromConversationId });
        return;
      }

      const maxSeqRow = await messageRepo
        .createQueryBuilder('m')
        .select('COALESCE(MAX(m.conversation_sequence), 0)', 'maxSeq')
        .where('m.conversation_id = :cid', { cid: toConversationId })
        .getRawOne<{ maxSeq: string }>();
      let nextSeq = Number(maxSeqRow?.maxSeq ?? 0);

      for (const message of orphanMessages) {
        nextSeq += 1;
        await messageRepo.update(message.id, {
          conversation_id: toConversationId,
          conversation_sequence: String(nextSeq),
        });
      }

      const lastMessage = await messageRepo.findOne({
        where: { conversation_id: toConversationId },
        order: { conversation_sequence: 'DESC' },
      });
      if (lastMessage) {
        const preview = formatInboxPreview({
          type: lastMessage.type,
          body: lastMessage.body,
          metadata: lastMessage.metadata,
        });
        await convRepo.update(toConversationId, {
          last_message_id: lastMessage.id,
          last_message_sequence: String(lastMessage.conversation_sequence),
          last_message_preview: preview,
          last_message_at: lastMessage.created_at,
        });
      }

      await convRepo.delete({ id: fromConversationId });
    });
  }

  private async dedupeDuplicateBookingThreads(userId: string): Promise<void> {
    const duplicates = await this.dataSource.query<
      { booking_id: string; conv_ids: string[] }[]
    >(
      `
      SELECT booking_id, array_agg(id ORDER BY created_at ASC) AS conv_ids
      FROM stays_conversations
      WHERE booking_id IS NOT NULL
        AND (guest_user_id = $1 OR host_user_id = $1)
      GROUP BY booking_id
      HAVING COUNT(*) > 1
      `,
      [userId],
    );

    for (const row of duplicates) {
      const [keepId, ...dropIds] = row.conv_ids;
      for (const dropId of dropIds) {
        try {
          await this.mergeMessagesIntoConversation(dropId, keepId);
          this.logger.log(
            `Deduped conversation ${dropId} into ${keepId} for booking ${row.booking_id}`,
          );
        } catch (err) {
          this.logger.warn(
            `Failed to dedupe conversation ${dropId}: ${err instanceof Error ? err.message : String(err)}`,
          );
        }
      }
    }
  }

  private async ensureMissingBookingThreads(userId: string): Promise<void> {
    const bookingRepo = this.dataSource.getRepository(StaysBooking);
    const convRepo = this.dataSource.getRepository(StaysConversation);
    const listingRepo = this.dataSource.getRepository(StaysListing);

    const hostListings = await listingRepo.find({
      where: { host_user_id: userId },
      select: ['id'],
    });
    const hostListingIds = hostListings.map((l) => l.id);

    const guestBookings = await bookingRepo.find({
      where: { guest_user_id: userId },
      select: ['id', 'status'],
    });
    const hostBookings =
      hostListingIds.length > 0
        ? await bookingRepo.find({
            where: { listing_id: In(hostListingIds) },
            select: ['id', 'status'],
          })
        : [];

    const bookingIds = [...guestBookings, ...hostBookings]
      .filter((b) => MESSAGEABLE_STATUSES.has(b.status))
      .map((b) => b.id);

    if (bookingIds.length === 0) return;

    const existing = await convRepo.find({
      where: { booking_id: In(bookingIds) },
      select: ['booking_id'],
    });
    const existingIds = new Set(
      existing.map((c) => c.booking_id).filter((id): id is string => !!id),
    );

    for (const bookingId of bookingIds) {
      if (existingIds.has(bookingId)) continue;
      try {
        await this.provision.ensureForBooking(bookingId, userId);
      } catch (err) {
        this.logger.warn(
          `Could not provision conversation for booking ${bookingId}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  Inject,
  forwardRef,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository, Brackets, In } from 'typeorm';
import { StaysConversation } from './entities/stays-conversation.entity';
import { StaysMessage } from './entities/stays-message.entity';
import { StaysBooking } from '../stays/entities/stays-booking.entity';
import { formatInboxPreview, resolveInboxSenderLabel } from './message-preview.util';
import { MessagingPermissionsService } from './permissions.service';
import { MessagesService } from './messages.service';
import { MessagingAuditService } from './audit.service';
import { ConversationProvisionService } from './conversation-provision.service';
import { ConversationPresentationService } from './conversation-presentation.service';
import { SnapshotRepairService } from './snapshot-repair.service';
import { MessagingOutboxService } from './outbox.service';
import { MESSAGING_INTERNAL_EVENTS } from './messaging-internal.events';
import { ConversationRepairService } from './conversation-repair.service';
import { MessagingStateService } from './messaging-state.service';
import { SupportTicketsService } from '../support/support-tickets.service';
import type {
  ConversationDetailResponse,
  ConversationDomain,
  ConversationListResponse,
  ReservationSnapshot,
} from './messaging.types';

@Injectable()
export class ConversationsService {
  constructor(
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    @InjectRepository(StaysMessage)
    private readonly messageRepo: Repository<StaysMessage>,
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    private readonly permissions: MessagingPermissionsService,
    private readonly messagesService: MessagesService,
    private readonly audit: MessagingAuditService,
    private readonly conversationProvision: ConversationProvisionService,
    private readonly presentation: ConversationPresentationService,
    private readonly snapshotRepair: SnapshotRepairService,
    private readonly outbox: MessagingOutboxService,
    private readonly repair: ConversationRepairService,
    private readonly messagingState: MessagingStateService,
    @Inject(forwardRef(() => SupportTicketsService))
    private readonly supportTickets: SupportTicketsService,
  ) {}

  async listConversations(
    userId: string,
    filter: string = 'active',
    q?: string,
  ): Promise<ConversationListResponse[]> {
    await this.repair.repairForUser(userId);

    const qb = this.convRepo
      .createQueryBuilder('c')
      .where(
        new Brackets((w) => {
          w.where('c.guest_user_id = :uid', { uid: userId }).orWhere(
            'c.host_user_id = :uid',
            { uid: userId },
          );
        }),
      );

    if (filter === 'unread') {
      qb.andWhere(
        new Brackets((w) => {
          w.where(
            '(c.guest_user_id = :uid AND c.unread_guest > 0)',
          ).orWhere('(c.host_user_id = :uid AND c.unread_host > 0)');
        }),
      );
    } else if (filter === 'active') {
      qb.andWhere('c.type = :t', { t: 'BOOKING' });
      qb.innerJoin(StaysBooking, 'b', 'b.id = c.booking_id');
      qb.andWhere(
        new Brackets((w) => {
          w.where(
            "(b.status IN ('CONFIRMED', 'CHECKED_IN') AND b.checkout_date >= CURRENT_DATE)",
          ).orWhere(
            "(b.status = 'COMPLETED' AND c.post_stay_ends_at IS NOT NULL AND c.post_stay_ends_at > NOW())",
          );
        }),
      );
    } else if (filter === 'archived') {
      qb.andWhere(
        new Brackets((w) => {
          w.where("c.messaging_state = 'ARCHIVED'")
            .orWhere("(c.guest_user_id = :uid AND c.guest_visibility = 'ARCHIVED')")
            .orWhere("(c.host_user_id = :uid AND c.host_visibility = 'ARCHIVED')");
        }),
      );
    } else if (filter === 'hosts') {
      qb.andWhere('c.type = :t', { t: 'BOOKING' });
    } else if (filter === 'support') {
      qb.andWhere('c.type = :t', { t: 'SUPPORT' });
      qb.andWhere("c.messaging_state != 'ARCHIVED'");
    }

    if (q?.trim()) {
      const term = `%${q.trim().toLowerCase()}%`;
      qb.andWhere(
        new Brackets((w) => {
          w.where('LOWER(c.last_message_preview) LIKE :term', { term })
            .orWhere("LOWER(c.reservation_snapshot->>'listingTitle') LIKE :term", { term })
            .orWhere("LOWER(c.reservation_snapshot->>'hostDisplayName') LIKE :term", { term })
            .orWhere("LOWER(c.reservation_snapshot->>'guestDisplayName') LIKE :term", { term })
            .orWhere("LOWER(c.reservation_snapshot->>'bookingReference') LIKE :term", { term })
            .orWhere("LOWER(c.reservation_snapshot->>'listingReference') LIKE :term", { term })
            .orWhere("LOWER(c.reservation_snapshot->>'city') LIKE :term", { term })
            .orWhere("LOWER(c.reservation_snapshot->>'country') LIKE :term", { term })
            .orWhere(
              `EXISTS (
                SELECT 1 FROM stays_messages sm
                WHERE sm.conversation_id = c.id
                  AND sm.deleted_at IS NULL
                  AND sm.type = 'TEXT'
                  AND LOWER(sm.body) LIKE :term
              )`,
            );
        }),
      );
    }

    qb.orderBy(
      `CASE WHEN (c.guest_user_id = :uid AND c.unread_guest > 0) OR (c.host_user_id = :uid AND c.unread_host > 0) THEN 0 ELSE 1 END`,
      'ASC',
    );
    qb.addOrderBy('c.last_message_at', 'DESC', 'NULLS LAST');
    qb.addOrderBy(
      `CASE WHEN c.messaging_state = 'ARCHIVED' THEN 1 ELSE 0 END`,
      'ASC',
    );

    const rows = await qb.getMany();
    const deduped = this.dedupeByBookingId(rows);
    const filtered = deduped
      .filter((c) => this.permissions.visibilityFor(c, userId) !== 'DELETED')
      .filter((c) => {
        const vis = this.permissions.visibilityFor(c, userId);
        if (filter === 'active') return vis !== 'ARCHIVED';
        if (filter === 'archived') return vis !== 'DELETED';
        return true;
      });

    for (const conv of filtered) {
      if (conv.type === 'SUPPORT') continue;
      const snapshot = conv.reservation_snapshot as unknown as ReservationSnapshot;
      if (this.snapshotRepair.isSnapshotIncomplete(snapshot)) {
        void this.outbox.enqueueDirect(MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED, {
          conversationId: conv.id,
        });
      }
    }

    const lastMessageIds = filtered
      .map((c) => c.last_message_id)
      .filter((id): id is string => !!id);
    const lastMessages = lastMessageIds.length
      ? await this.messageRepo.find({ where: { id: In(lastMessageIds) } })
      : [];
    const lastMessageById = new Map(lastMessages.map((m) => [m.id, m]));
    const closedIds = await this.supportTickets.closedConversationIds(
      filtered.filter((c) => c.type === 'SUPPORT').map((c) => c.id),
    );

    return Promise.all(
      filtered.map(async (c) =>
        this.toListResponse(
          c,
          userId,
          lastMessageById.get(c.last_message_id ?? ''),
          closedIds.has(c.id),
        ),
      ),
    );
  }

  async getUnreadCount(userId: string): Promise<number> {
    const rows = await this.convRepo.find({
      where: [{ guest_user_id: userId }, { host_user_id: userId }],
    });
    return rows.reduce((sum, c) => {
      if (this.permissions.visibilityFor(c, userId) === 'DELETED') return sum;
      if (c.guest_user_id === userId) return sum + (c.unread_guest ?? 0);
      if (c.host_user_id === userId) return sum + (c.unread_host ?? 0);
      return sum;
    }, 0);
  }

  async getConversationByBooking(
    bookingId: string,
    userId: string,
  ): Promise<ConversationListResponse | null> {
    const conv = await this.convRepo.findOne({ where: { booking_id: bookingId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) return null;
    if (this.permissions.visibilityFor(conv, userId) === 'DELETED') return null;
    return this.toListResponse(conv, userId, await this.loadLastMessage(conv.last_message_id));
  }

  async ensureConversationForBooking(
    bookingId: string,
    userId: string,
  ): Promise<ConversationListResponse> {
    const conv = await this.conversationProvision.ensureForBooking(
      bookingId,
      userId,
    );
    return this.toListResponse(conv, userId, await this.loadLastMessage(conv.last_message_id));
  }

  async getConversation(
    conversationId: string,
    userId: string,
    beforeSequence?: number,
  ): Promise<ConversationDetailResponse> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    if (this.permissions.visibilityFor(conv, userId) === 'DELETED') {
      throw new NotFoundException('Conversation not found');
    }

    const snapshot = conv.reservation_snapshot as unknown as ReservationSnapshot;
    if (
      conv.type !== 'SUPPORT' &&
      this.snapshotRepair.isSnapshotIncomplete(snapshot)
    ) {
      void this.outbox.enqueueDirect(MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED, {
        conversationId: conv.id,
      });
    }

    const { messages, hasMore } = await this.messagesService.listMessages(
      conversationId,
      userId,
      30,
      beforeSequence,
    );

    let bookingStatus: string | null = null;
    if (conv.booking_id) {
      const booking = await this.bookingRepo.findOne({ where: { id: conv.booking_id } });
      bookingStatus = booking?.status ?? null;
    }

    const list = await this.toListResponse(
      conv,
      userId,
      await this.loadLastMessage(conv.last_message_id),
    );
    return {
      conversation: list.conversation,
      presentation: list.presentation,
      timeline: messages,
      permissions: list.permissions,
      sync: list.sync,
      hasMore,
      bookingStatus,
    };
  }

  async updateVisibility(
    conversationId: string,
    userId: string,
    action: 'archive' | 'delete' | 'restore',
  ): Promise<{ conversationVersion: number }> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    const perms = this.permissions.resolve(conv, userId);
    if (action === 'archive' && !perms.canArchive) throw new ForbiddenException();
    if (action === 'delete' && !perms.canDelete) throw new ForbiddenException();

    const isGuest = conv.guest_user_id === userId;
    const field = isGuest ? 'guest_visibility' : 'host_visibility';
    let value: 'ACTIVE' | 'ARCHIVED' | 'DELETED' = 'ACTIVE';
    if (action === 'archive') value = 'ARCHIVED';
    if (action === 'delete') value = 'DELETED';

    const nextVersion = conv.conversation_version + 1;
    await this.convRepo.update(conv.id, {
      [field]: value,
      conversation_version: nextVersion,
    });
    await this.audit.log(`visibility_${action}`, conv.id, userId, { field, value });
    return { conversationVersion: nextVersion };
  }

  async report(
    conversationId: string,
    userId: string,
    reason?: string,
    attachmentIds: string[] = [],
  ): Promise<{
    reportId: string;
    ticketId?: string;
    ticketNumber?: string;
    supportConversationId?: string;
  }> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    if (conv.type === 'SUPPORT') {
      throw new NotFoundException('Conversation not found');
    }
    const { report, ticket } = await this.supportTickets.provisionReportWithTicket({
      conversationId: conv.id,
      reporterUserId: userId,
      reason,
      attachmentIds,
      bookingId: conv.booking_id,
      listingId: conv.listing_id,
      reportedUserId:
        conv.guest_user_id === userId
          ? conv.host_user_id
          : conv.host_user_id === userId
            ? conv.guest_user_id
            : null,
      sourceConversation: conv,
    });
    await this.audit.log('conversation_reported', conv.id, userId, {
      reason: reason ?? '',
      reportId: report.id,
      ...(attachmentIds.length ? { attachmentIds } : {}),
    });
    return {
      reportId: report.id,
      ticketId: ticket.id,
      ticketNumber: ticket.ticket_number,
      supportConversationId: ticket.conversation_id,
    };
  }

  async block(conversationId: string, userId: string): Promise<void> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    const isGuest = conv.guest_user_id === userId;
    await this.convRepo.update(conv.id, {
      ...(isGuest ? { blocked_by_guest: true } : { blocked_by_host: true }),
      messaging_state: 'LOCKED',
      locked_at: new Date(),
      conversation_version: conv.conversation_version + 1,
    });
    await this.audit.log('user_blocked', conv.id, userId, {});
  }

  async safety(
    conversationId: string,
    userId: string,
    payload: { category: string; details?: string; attachmentIds?: string[] },
  ): Promise<{
    supportUrl: string;
    safetyIssueId: string;
    ticketId?: string;
    ticketNumber?: string;
    supportConversationId?: string;
  }> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    if (conv.type === 'SUPPORT') {
      throw new NotFoundException('Conversation not found');
    }
    const attachmentIds = payload.attachmentIds ?? [];
    const { safety, ticket } =
      await this.supportTickets.provisionSafetyIssueWithTicket({
        conversationId: conv.id,
        reporterUserId: userId,
        category: payload.category,
        details: payload.details,
        attachmentIds,
        bookingId: conv.booking_id,
        listingId: conv.listing_id,
        reportedUserId:
          conv.guest_user_id === userId
            ? conv.host_user_id
            : conv.host_user_id === userId
              ? conv.guest_user_id
              : null,
        sourceConversation: conv,
      });
    await this.audit.log('safety_issue', conv.id, userId, {
      category: payload.category,
      details: payload.details?.trim() || undefined,
      safetyIssueId: safety.id,
      ...(attachmentIds.length ? { attachmentIds } : {}),
    });
    return {
      supportUrl: `/contact?safety=1&safety_issue_id=${encodeURIComponent(safety.id)}`,
      safetyIssueId: safety.id,
      ticketId: ticket.id,
      ticketNumber: ticket.ticket_number,
      supportConversationId: ticket.conversation_id,
    };
  }

  async reopenConversation(
    conversationId: string,
    userId: string,
    options: { reason?: string; disableAutoArchive?: boolean } = {},
  ): Promise<ConversationListResponse> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    const updated = await this.messagingState.reopenConversation(conversationId, options);
    await this.audit.log('conversation_reopened', updated.id, userId, options);
    return this.toListResponse(updated, userId, await this.loadLastMessage(updated.last_message_id));
  }

  /** Keep a single inbox row per booking when duplicate threads exist. */
  private dedupeByBookingId(rows: StaysConversation[]): StaysConversation[] {
    const winnerByBooking = new Map<string, StaysConversation>();
    for (const row of rows) {
      if (!row.booking_id) continue;
      const existing = winnerByBooking.get(row.booking_id);
      const rowTs = row.last_message_at?.getTime() ?? 0;
      const existingTs = existing?.last_message_at?.getTime() ?? 0;
      if (!existing || rowTs > existingTs) {
        winnerByBooking.set(row.booking_id, row);
      }
    }

    return rows.filter((row) => {
      if (!row.booking_id) return true;
      return winnerByBooking.get(row.booking_id)?.id === row.id;
    });
  }

  private hasUnread(c: StaysConversation, userId: string): boolean {
    if (c.guest_user_id === userId) return (c.unread_guest ?? 0) > 0;
    if (c.host_user_id === userId) return (c.unread_host ?? 0) > 0;
    return false;
  }

  private async loadLastMessage(
    messageId: string | null | undefined,
  ): Promise<StaysMessage | undefined> {
    if (!messageId) return undefined;
    return (await this.messageRepo.findOne({ where: { id: messageId } })) ?? undefined;
  }

  private toDomain(conv: StaysConversation, userId: string): ConversationDomain {
    return {
      id: conv.id,
      type: conv.type,
      bookingId: conv.booking_id,
      listingId: conv.listing_id,
      messagingState: conv.messaging_state,
      visibility: this.permissions.visibilityFor(conv, userId),
      postStayEndsAt: conv.post_stay_ends_at?.toISOString() ?? null,
      autoArchiveDisabled: conv.auto_archive_disabled ?? false,
      archiveReason: conv.archive_reason ?? null,
    };
  }

  private async toListResponse(
    conv: StaysConversation,
    userId: string,
    lastMessage?: StaysMessage,
    ticketClosedKnown?: boolean,
  ): Promise<ConversationListResponse> {
    const snapshot = conv.reservation_snapshot as unknown as ReservationSnapshot;
    let status: string | null = null;
    if (conv.booking_id) {
      const booking = await this.bookingRepo.findOne({ where: { id: conv.booking_id } });
      status = booking?.status ?? null;
    }

    const presentation = await this.presentation.buildPresentation(conv, userId, snapshot, status);

    const senderLabel = lastMessage
      ? resolveInboxSenderLabel({
          senderId: lastMessage.sender_id,
          viewerUserId: userId,
          guestUserId: conv.guest_user_id,
          hostUserId: conv.host_user_id,
          hostDisplayName: snapshot.hostDisplayName,
          guestDisplayName: snapshot.guestDisplayName,
          counterpartDisplayName: presentation.counterpart.displayName,
        })
      : null;

    const ticketClosed =
      ticketClosedKnown ??
      (conv.type === 'SUPPORT'
        ? (await this.supportTickets.closedConversationIds([conv.id])).has(
            conv.id,
          )
        : false);
    const perms = this.permissions.resolve(conv, userId, { ticketClosed });

    const preview = lastMessage
      ? formatInboxPreview({
          type: lastMessage.type,
          body: lastMessage.body,
          metadata: lastMessage.metadata,
          senderLabel,
          viewerRole: perms.viewerRole,
        })
      : conv.last_message_preview;

    return {
      conversation: this.toDomain(conv, userId),
      presentation,
      sync: this.presentation.buildSyncMeta(conv, userId),
      lastMessage: {
        preview,
        at: conv.last_message_at?.toISOString() ?? null,
      },
      permissions: perms,
    };
  }
}

