import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { createHash, randomUUID } from 'crypto';
import { Repository } from 'typeorm';
import sharp from 'sharp';
import { StaysMediaAsset } from './entities/stays-media-asset.entity';
import {
  detectAttachmentMime,
  extensionForMime,
  isImageMime,
  type AllowedAttachmentMime,
} from '../../common/utils/attachment-mime.util';
import { MediaStorageService } from '../../common/media/media-storage.module';
import { assertSafeRelativeStorageKey } from '../../common/media/media-storage-policy';

const THUMB_MAX_PX = 640;

export interface ProcessedMediaInput {
  buffer: Buffer;
  declaredMime: string;
  conversationId: string;
}

export interface ProcessedMediaResult {
  asset: StaysMediaAsset;
  storageKey: string;
  thumbnailKey: string | null;
  mime: AllowedAttachmentMime;
  width: number | null;
  height: number | null;
  checksum: string;
}

@Injectable()
export class MediaAssetService {
  private readonly uploadRoot =
    process.env.MEDIA_STORAGE_ROOT?.trim() || 'uploads';

  constructor(
    @InjectRepository(StaysMediaAsset)
    private readonly assetRepo: Repository<StaysMediaAsset>,
    private readonly mediaStorage: MediaStorageService,
  ) {}

  async processAndStore(input: ProcessedMediaInput): Promise<ProcessedMediaResult> {
    const detected = detectAttachmentMime(input.buffer);
    if (!detected) {
      throw new Error('Unsupported or invalid file content');
    }

    const declared = input.declaredMime?.toLowerCase() ?? '';
    if (declared && !declared.startsWith('application/octet') && declared !== detected) {
      if (!(declared === 'image/jpg' && detected === 'image/jpeg')) {
        throw new Error('File content does not match declared type');
      }
    }

    const checksum = createHash('sha256').update(input.buffer).digest('hex');
    const assetId = randomUUID();
    const ext = extensionForMime(detected);
    const storageKey = `messaging/${input.conversationId}/${assetId}${ext}`;

    await this.mediaStorage.store({
      buffer: input.buffer,
      relativeKey: storageKey,
      mimeType: detected,
      assetId,
    });

    let width: number | null = null;
    let height: number | null = null;
    let orientation: number | null = null;
    let thumbnailKey: string | null = null;

    if (isImageMime(detected)) {
      const meta = await sharp(input.buffer).metadata();
      width = meta.width ?? null;
      height = meta.height ?? null;
      orientation = meta.orientation ?? null;

      const thumbBuffer = await sharp(input.buffer)
        .rotate()
        .resize(THUMB_MAX_PX, THUMB_MAX_PX, { fit: 'inside', withoutEnlargement: true })
        .jpeg({ quality: 82 })
        .toBuffer();
      thumbnailKey = `messaging/${input.conversationId}/${assetId}_thumb.jpg`;
      await this.mediaStorage.store({
        buffer: thumbBuffer,
        relativeKey: thumbnailKey,
        mimeType: 'image/jpeg',
        assetId: randomUUID(),
      });
    }

    const asset = this.assetRepo.create({
      storage_key: storageKey,
      checksum_sha256: checksum,
      mime: detected,
      size_bytes: String(input.buffer.length),
      width,
      height,
      orientation,
      duration_ms: null,
      thumbnail_storage_key: thumbnailKey,
      encryption_key_id: null,
      media_version: 1,
    });

    const saved = await this.assetRepo.save(asset);
    return {
      asset: saved,
      storageKey,
      thumbnailKey,
      mime: detected,
      width,
      height,
      checksum,
    };
  }

  /**
   * Local absolute path for streaming when backend is local.
   * Callers that receive http(s) URLs must redirect instead.
   */
  resolveStoragePath(storageKey: string): string {
    return assertSafeRelativeStorageKey(this.uploadRoot, storageKey);
  }

  resolveDelivery(storageKey: string): Promise<string> {
    return this.mediaStorage.resolveDelivery(storageKey);
  }

  async deleteObject(storageKey: string): Promise<void> {
    await this.mediaStorage.delete(storageKey);
  }
}

import type { StaysMessage } from './entities/stays-message.entity';
import type { AttachmentDto, MessagePayload, TimelineCardPayload } from './messaging.types';

export type DeliveryState = 'PERSISTED' | 'SENT' | 'DELIVERED' | 'READ' | 'PENDING';

export function resolveDeliveryState(message: StaysMessage): DeliveryState {
  if (message.status === 'READ' || message.read_at) return 'READ';
  if (message.status === 'DELIVERED' || message.delivered_at) return 'DELIVERED';
  if (message.status === 'PERSISTED' && message.sent_at) return 'SENT';
  if (message.status === 'PERSISTED') return 'PERSISTED';
  return 'PENDING';
}

export function buildMessagePayload(
  type: string,
  body: string | null,
  metadata: Record<string, unknown>,
  attachments: AttachmentDto[] = [],
): MessagePayload {
  const meta = metadata ?? {};
  const cardTypes = new Set([
    'BOOKING_CARD',
    'PROPERTY_CARD',
    'CHECKIN_CARD',
    'WIFI_CARD',
    'LOCATION_CARD',
    'REVIEW_CARD',
    'PAYMENT_CARD',
    'SYSTEM_EVENT',
    'SYSTEM_NOTICE',
  ]);

  if (type === 'TEXT') {
    return { text: body ?? '' };
  }

  if (type === 'IMAGE' || type === 'FILE') {
    const ids =
      (meta.attachment_ids as string[] | undefined) ??
      attachments.map((a) => a.id);
    return {
      attachmentIds: ids,
      caption: (meta.caption as string | undefined) ?? body ?? undefined,
      attachments,
    };
  }

  if (cardTypes.has(type) || meta.kind) {
    return {
      kind: String(meta.kind ?? type.replace(/_CARD$/, '').toLowerCase()),
      title: String(meta.title ?? body ?? ''),
      body: meta.body as string | undefined,
      icon: meta.icon as string | undefined,
      actions: (meta.actions as TimelineCardPayload['actions']) ?? [],
      coverMediaId: meta.coverMediaId as string | null | undefined,
      listingId: meta.listingId as string | null | undefined,
      bookingId: meta.bookingId as string | null | undefined,
      snapshot: meta.snapshot as Record<string, unknown> | undefined,
    };
  }

  return { text: body ?? '' };
}

export function payloadToStorage(
  type: string,
  payload: MessagePayload,
): { body: string | null; metadata: Record<string, unknown> } {
  if ('text' in payload && type === 'TEXT') {
    return {
      body: payload.text,
      metadata: { source: 'USER', schemaVersion: 1, cardVersion: 1, presentationVersion: 1 },
    };
  }

  if ('attachmentIds' in payload) {
    return {
      body: payload.caption ?? null,
      metadata: {
        source: 'USER',
        schemaVersion: 1,
        cardVersion: 1,
        presentationVersion: 1,
        attachment_ids: payload.attachmentIds,
        caption: payload.caption,
      },
    };
  }

  if ('kind' in payload) {
    return {
      body: null,
      metadata: {
        source: 'SYSTEM',
        schemaVersion: 1,
        cardVersion: 1,
        presentationVersion: 1,
        kind: payload.kind,
        title: payload.title,
        body: payload.body,
        icon: payload.icon,
        actions: payload.actions ?? [],
        coverMediaId: payload.coverMediaId,
        listingId: payload.listingId,
        bookingId: payload.bookingId,
        snapshot: payload.snapshot,
      },
    };
  }

  return { body: null, metadata: {} };
}

import type { MessageType } from './entities/stays-message.entity';
import type { ConversationViewerRole } from './messaging.types';

type PreviewInput = {
  type: MessageType | string;
  body?: string | null;
  metadata?: Record<string, unknown> | null;
  senderLabel?: string | null;
  viewerRole?: ConversationViewerRole;
};

type SenderContext = {
  senderId?: string | null;
  viewerUserId: string;
  guestUserId: string | null;
  hostUserId: string | null;
  hostDisplayName?: string | null;
  guestDisplayName?: string | null;
  counterpartDisplayName?: string | null;
};

function pickText(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

function sentMediaPreview(
  mediaLabel: string,
  senderLabel?: string | null,
  fallback?: string,
): string {
  if (senderLabel) return `${senderLabel} sent a ${mediaLabel}`;
  return fallback ?? mediaLabel.charAt(0).toUpperCase() + mediaLabel.slice(1);
}

/** Resolve "You" vs counterpart/sender name for inbox preview copy. */
export function resolveInboxSenderLabel(ctx: SenderContext): string | null {
  const { senderId, viewerUserId, guestUserId, hostUserId } = ctx;
  if (!senderId) return null;
  if (senderId === viewerUserId) return 'You';

  if (senderId === hostUserId) {
    return ctx.hostDisplayName ?? ctx.counterpartDisplayName ?? 'Host';
  }
  if (senderId === guestUserId) {
    return ctx.guestDisplayName ?? ctx.counterpartDisplayName ?? 'Guest';
  }
  return ctx.counterpartDisplayName ?? null;
}

function readRoleViewTitle(
  meta: Record<string, unknown>,
  viewerRole?: ConversationViewerRole,
): string | null {
  const reviewed = meta.reviewed === true;
  const viewKey = viewerRole === 'host' ? 'hostView' : 'guestView';
  const view = meta[viewKey];
  if (view && typeof view === 'object' && view !== null) {
    const title = pickText((view as Record<string, unknown>).title);
    if (title) return title;
  }

  if (viewerRole === 'host') {
    return reviewed ? 'Guest reviewed successfully' : 'Review request sent';
  }
  if (reviewed) return 'Thanks for reviewing!';
  return pickText(meta.title) ?? 'Review your stay';
}

/** Human-readable inbox preview for the chronologically latest message. */
export function formatInboxPreview(input: PreviewInput): string {
  const meta = input.metadata ?? {};
  const body = pickText(input.body);
  const caption = pickText(meta.caption);
  const title = pickText(meta.title);
  const cardBody = pickText(meta.body);
  const senderLabel = input.senderLabel ?? null;

  switch (input.type) {
    case 'TEXT':
      return body ?? '';
    case 'IMAGE':
      if (caption) return caption;
      return sentMediaPreview('photo', senderLabel, 'Photo');
    case 'FILE':
      if (caption && caption !== 'Voice message') return caption;
      if (caption === 'Voice message') {
        return sentMediaPreview('voice message', senderLabel, 'Voice message');
      }
      return sentMediaPreview('file', senderLabel, 'File');
    case 'VIDEO':
      if (caption) return caption;
      return sentMediaPreview('video', senderLabel, 'Video');
    case 'VOICE':
      return sentMediaPreview('voice message', senderLabel, 'Voice message');
    case 'LOCATION':
      if (caption) return caption;
      return sentMediaPreview('location', senderLabel, 'Location');
    case 'SYSTEM_EVENT':
      return body ?? title ?? 'Booking update';
    case 'SYSTEM_NOTICE':
      return body ?? title ?? 'Notice';
    case 'BOOKING_CARD':
      return title ?? cardBody ?? 'Booking confirmed';
    case 'PROPERTY_CARD':
      return title ?? cardBody ?? 'Property details';
    case 'CHECKIN_CARD':
      return title ?? cardBody ?? 'Check-in details';
    case 'WIFI_CARD':
      return title ?? (cardBody ? `Wi-Fi · ${cardBody}` : 'Wi-Fi details');
    case 'LOCATION_CARD':
      return title ?? cardBody ?? 'Location';
    case 'REVIEW_CARD':
      return readRoleViewTitle(meta, input.viewerRole) ?? 'Review your stay';
    case 'PAYMENT_CARD':
      return title ?? cardBody ?? 'Payment update';
    default:
      return title ?? cardBody ?? body ?? 'Message';
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysMessage } from './entities/stays-message.entity';
import { StaysConversation } from './entities/stays-conversation.entity';
import { MessagingPermissionsService } from './permissions.service';

export type SearchResultType = 'message' | 'file' | 'photo' | 'link' | 'card';

export interface ConversationSearchResult {
  messageId: string;
  conversationSequence: number;
  resultType: SearchResultType;
  highlight: string;
  snippet: string;
  createdAt: string;
}

@Injectable()
export class MessageSearchService {
  constructor(
    @InjectRepository(StaysMessage)
    private readonly messageRepo: Repository<StaysMessage>,
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    private readonly permissions: MessagingPermissionsService,
  ) {}

  async search(
    conversationId: string,
    userId: string,
    q: string,
    types: SearchResultType[] = ['message', 'file', 'photo', 'link', 'card'],
  ): Promise<ConversationSearchResult[]> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }

    const term = q?.trim();
    if (!term || term.length < 2) return [];

    const like = `%${term.replace(/[%_]/g, '')}%`;
    const rows = await this.messageRepo
      .createQueryBuilder('m')
      .where('m.conversation_id = :id', { id: conversationId })
      .andWhere('m.deleted_at IS NULL')
      .andWhere("m.type != 'SYSTEM_INTERNAL'")
      .andWhere(
        `(m.body ILIKE :like OR m.metadata::text ILIKE :like)`,
        { like },
      )
      .orderBy('m.conversation_sequence', 'DESC')
      .take(50)
      .getMany();

    const results: ConversationSearchResult[] = [];
    for (const row of rows) {
      const resultType = this.classify(row);
      if (!types.includes(resultType)) continue;
      const snippet = row.body ?? String((row.metadata as { title?: string })?.title ?? '');
      results.push({
        messageId: row.id,
        conversationSequence: Number(row.conversation_sequence),
        resultType,
        highlight: term,
        snippet: snippet.slice(0, 160),
        createdAt: row.created_at.toISOString(),
      });
    }
    return results;
  }

  private classify(row: StaysMessage): SearchResultType {
    if (row.type === 'IMAGE') return 'photo';
    if (row.type === 'FILE') return 'file';
    if (row.type.endsWith('_CARD')) return 'card';
    const meta = row.metadata as { actions?: Array<{ url?: string }> };
    if (meta.actions?.some((a) => a.url?.startsWith('http'))) return 'link';
    return 'message';
  }
}

import {
  Injectable,
  NotFoundException,
  ForbiddenException,
  BadRequestException,
  Inject,
  forwardRef,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, Repository, EntityManager } from 'typeorm';
import { StaysConversation } from './entities/stays-conversation.entity';
import { StaysMessage } from './entities/stays-message.entity';
import { MessagingPermissionsService } from './permissions.service';
import { MessagingRateLimitService } from './rate-limit.service';
import { TimelineSeederService } from './timeline-seeder.service';
import { MessagingOutboxService } from './outbox.service';
import { AttachmentService } from './attachment.service';
import { AttachmentSessionService } from './attachment-session.service';
import { ParticipantPresentationService } from './participant-presentation.service';
import type { MessageDto } from './messaging.types';
import { SendMessageDto } from './dto/send-message.dto';
import {
  buildMessagePayload,
  resolveDeliveryState,
} from './message-payload.mapper';
import { EVENTS } from '@nexa/event-bus';
import { MessagingRealtimeService } from './messaging-realtime.service';
import { SupportTicketsService } from '../support/support-tickets.service';

@Injectable()
export class MessagesService {
  constructor(
    private readonly dataSource: DataSource,
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    @InjectRepository(StaysMessage)
    private readonly messageRepo: Repository<StaysMessage>,
    private readonly permissions: MessagingPermissionsService,
    private readonly rateLimit: MessagingRateLimitService,
    private readonly timelineSeeder: TimelineSeederService,
    private readonly outbox: MessagingOutboxService,
    private readonly attachments: AttachmentService,
    private readonly attachmentSessions: AttachmentSessionService,
    private readonly participants: ParticipantPresentationService,
    private readonly realtime: MessagingRealtimeService,
    @Inject(forwardRef(() => SupportTicketsService))
    private readonly supportTickets: SupportTicketsService,
  ) {}

  realtimeStream(userId: string) {
    return this.realtime.stream(userId);
  }

  async listMessages(
    conversationId: string,
    userId: string,
    limit = 30,
    beforeSequence?: number,
  ): Promise<{ messages: MessageDto[]; hasMore: boolean }> {
    const conv = await this.getParticipantConversation(conversationId, userId);
    const take = Math.min(Math.max(limit, 1), 50);

    const qb = this.messageRepo
      .createQueryBuilder('m')
      .where('m.conversation_id = :id', { id: conv.id })
      .andWhere("m.type != 'SYSTEM_INTERNAL'")
      .andWhere('m.deleted_at IS NULL')
      .orderBy('m.conversation_sequence', 'DESC')
      .take(take + 1);

    if (beforeSequence != null) {
      qb.andWhere('m.conversation_sequence < :seq', { seq: beforeSequence });
    }

    const rows = await qb.getMany();
    const hasMore = rows.length > take;
    const slice = hasMore ? rows.slice(0, take) : rows;
    slice.reverse();

    const unreadFromOther = slice.filter(
      (m) => m.sender_id && m.sender_id !== userId && m.status !== 'READ',
    );
    if (unreadFromOther.length > 0) {
      const delivered = await this.messageRepo
        .createQueryBuilder()
        .update(StaysMessage)
        .set({ status: 'DELIVERED', delivered_at: new Date() })
        .where('id IN (:...ids)', { ids: unreadFromOther.map((m) => m.id) })
        .andWhere("status = 'PERSISTED'")
        .execute();
      if ((delivered.affected ?? 0) > 0) {
        for (const senderId of new Set(unreadFromOther.map((message) => message.sender_id))) {
          this.realtime.publish(senderId, {
            conversationId: conv.id,
            reason: 'MESSAGE_DELIVERED',
          });
        }
      }
    }

    const attachmentMap = await this.attachments.loadForMessages(
      slice.map((m) => ({ id: m.id, metadata: m.metadata ?? {} })),
    );

    return {
      messages: slice.map((m) =>
        this.toDto(m, userId, attachmentMap.get(m.id) ?? []),
      ),
      hasMore,
    };
  }

  async sendMessage(
    conversationId: string,
    userId: string,
    dto: SendMessageDto,
  ): Promise<MessageDto> {
    const type = dto.type ?? 'TEXT';
    const attachmentIds = dto.attachment_ids ?? [];

    if (type === 'TEXT') {
      return this.sendText(conversationId, userId, dto.body ?? '', dto.client_message_id);
    }

    if (type === 'IMAGE' || type === 'FILE') {
      if (dto.session_id) {
        return this.sendWithSession(
          conversationId,
          userId,
          type,
          dto.session_id,
          dto.caption ?? dto.body,
          dto.client_message_id,
        );
      }
      if (!attachmentIds.length) {
        throw new BadRequestException('attachment_ids or session_id required');
      }
      return this.sendWithAttachments(
        conversationId,
        userId,
        type,
        attachmentIds,
        dto.caption ?? dto.body,
        dto.client_message_id,
      );
    }

    throw new BadRequestException('Unsupported message type');
  }

  async sendText(
    conversationId: string,
    userId: string,
    body: string,
    clientMessageId?: string,
  ): Promise<MessageDto> {
    const trimmed = body?.trim();
    if (!trimmed) throw new BadRequestException('Message body required');
    if (trimmed.length > 2000) throw new BadRequestException('Message too long');

    const conv = await this.getParticipantConversation(conversationId, userId);
    const perms = this.permissions.resolve(conv, userId);
    if (!perms.canSend) throw new ForbiddenException('Cannot send messages');

    if (clientMessageId) {
      const existing = await this.messageRepo.findOne({
        where: { conversation_id: conv.id, client_message_id: clientMessageId },
      });
      if (existing) return this.toDto(existing, userId, []);
    }

    await this.rateLimit.assertCanSend(userId, conv.id, trimmed);

    const saved = await this.dataSource.transaction(async (manager) => {
      const supportTicket = await this.prepareCustomerSupportSend(
        manager,
        conv,
        userId,
      );

      const senderDisplayName = await this.resolveSenderDisplayName(conv, userId);
      const message = await this.timelineSeeder.insertMessage(manager, conv, {
        type: 'TEXT',
        body: trimmed,
        metadata: { source: 'USER', schemaVersion: 1, cardVersion: 1, presentationVersion: 1 },
        senderId: userId,
        clientMessageId: clientMessageId ?? null,
        senderDisplayName,
      });

      await this.enqueueDeliveryEvents(manager, conv, message, userId, trimmed);
      if (supportTicket) {
        await this.supportTickets.applyCustomerSupportMessageEffects(
          manager,
          supportTicket,
          trimmed,
        );
      }
      return message;
    });

    this.publishMessageCreated(conv, userId, saved.id);
    if (conv.type === 'SUPPORT') {
      void this.supportTickets.safeEvaluateConversation(conv.id);
    }

    return this.toDto(saved, userId, []);
  }

  private async sendWithAttachments(
    conversationId: string,
    userId: string,
    type: 'IMAGE' | 'FILE',
    attachmentIds: string[],
    caption?: string,
    clientMessageId?: string,
  ): Promise<MessageDto> {
    const conv = await this.getParticipantConversation(conversationId, userId);
    const perms = this.permissions.resolve(conv, userId);
    if (!perms.canSend) throw new ForbiddenException('Cannot send messages');

    if (clientMessageId) {
      const existing = await this.messageRepo.findOne({
        where: { conversation_id: conv.id, client_message_id: clientMessageId },
      });
      if (existing) {
        const atts = await this.attachments.loadForMessages([
          { id: existing.id, metadata: existing.metadata ?? {} },
        ]);
        return this.toDto(existing, userId, atts.get(existing.id) ?? []);
      }
    }

    await this.attachments.assertReadyForSend(conv.id, userId, attachmentIds);

    const senderDisplayName = await this.resolveSenderDisplayName(conv, userId);
    const preview =
      caption?.trim() ||
      (type === 'IMAGE' ? `${senderDisplayName} sent a photo` : 'File');
    await this.rateLimit.assertCanSend(userId, conv.id, preview);

    const saved = await this.dataSource.transaction(async (manager) => {
      const supportTicket = await this.prepareCustomerSupportSend(
        manager,
        conv,
        userId,
      );

      const message = await this.timelineSeeder.insertMessage(manager, conv, {
        type,
        body: caption?.trim() ?? null,
        metadata: {
          source: 'USER',
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          attachment_ids: attachmentIds,
          caption: caption?.trim(),
        },
        senderId: userId,
        clientMessageId: clientMessageId ?? null,
        senderDisplayName,
      });

      await this.attachments.linkToMessage(message.id, attachmentIds, conv.id, manager);
      await this.enqueueDeliveryEvents(manager, conv, message, userId, preview);
      if (supportTicket) {
        await this.supportTickets.applyCustomerSupportMessageEffects(
          manager,
          supportTicket,
          preview,
        );
      }
      return message;
    });

    this.publishMessageCreated(conv, userId, saved.id);
    if (conv.type === 'SUPPORT') {
      void this.supportTickets.safeEvaluateConversation(conv.id);
    }

    const atts = await this.attachments.loadForMessages([
      { id: saved.id, metadata: saved.metadata ?? {} },
    ]);
    return this.toDto(saved, userId, atts.get(saved.id) ?? []);
  }

  private async sendWithSession(
    conversationId: string,
    userId: string,
    type: 'IMAGE' | 'FILE',
    sessionId: string,
    caption?: string,
    clientMessageId?: string,
  ): Promise<MessageDto> {
    const conv = await this.getParticipantConversation(conversationId, userId);
    const perms = this.permissions.resolve(conv, userId);
    if (!perms.canSend) throw new ForbiddenException('Cannot send messages');

    if (clientMessageId) {
      const existing = await this.messageRepo.findOne({
        where: { conversation_id: conv.id, client_message_id: clientMessageId },
      });
      if (existing) {
        const atts = await this.attachments.loadForMessages([
          { id: existing.id, metadata: existing.metadata ?? {} },
        ]);
        return this.toDto(existing, userId, atts.get(existing.id) ?? []);
      }
    }

    const { session, attachments: sessionAttachments } =
      await this.attachmentSessions.assertSessionReadyForSend(
        conv.id,
        userId,
        sessionId,
      );
    const attachmentIds = sessionAttachments.map((a) => a.id);

    const senderDisplayName = await this.resolveSenderDisplayName(conv, userId);
    const preview =
      caption?.trim() ||
      (type === 'IMAGE' ? `${senderDisplayName} sent a photo` : 'File');
    await this.rateLimit.assertCanSend(userId, conv.id, preview);

    const saved = await this.dataSource.transaction(async (manager) => {
      const supportTicket = await this.prepareCustomerSupportSend(
        manager,
        conv,
        userId,
      );

      const message = await this.timelineSeeder.insertMessage(manager, conv, {
        type,
        body: caption?.trim() ?? null,
        metadata: {
          source: 'USER',
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          attachment_ids: attachmentIds,
          session_id: session.id,
          caption: caption?.trim(),
        },
        senderId: userId,
        clientMessageId: clientMessageId ?? null,
        senderDisplayName,
      });

      await this.attachments.linkToMessage(message.id, attachmentIds, conv.id, manager);
      await this.attachmentSessions.finalizeSession(session.id);
      await this.enqueueDeliveryEvents(manager, conv, message, userId, preview);
      if (supportTicket) {
        await this.supportTickets.applyCustomerSupportMessageEffects(
          manager,
          supportTicket,
          preview,
        );
      }
      return message;
    });

    this.publishMessageCreated(conv, userId, saved.id);
    if (conv.type === 'SUPPORT') {
      void this.supportTickets.safeEvaluateConversation(conv.id);
    }

    const atts = await this.attachments.loadForMessages([
      { id: saved.id, metadata: saved.metadata ?? {} },
    ]);
    return this.toDto(saved, userId, atts.get(saved.id) ?? []);
  }

  async markRead(conversationId: string, userId: string): Promise<{ conversationVersion: number }> {
    const conv = await this.getParticipantConversation(conversationId, userId);
    const isGuest = conv.guest_user_id === userId;
    const now = new Date();
    const nextVersion = conv.conversation_version + 1;

    const lastMsg = conv.last_message_id
      ? await this.messageRepo.findOne({ where: { id: conv.last_message_id } })
      : null;

    let changedMessages = 0;
    await this.dataSource.transaction(async (manager) => {
      const convRepo = manager.getRepository(StaysConversation);
      const msgRepo = manager.getRepository(StaysMessage);

      if (isGuest) {
        await convRepo.update(conv.id, {
          guest_last_read_at: now,
          guest_last_read_message_id: lastMsg?.id ?? null,
          unread_guest: 0,
          conversation_version: nextVersion,
        });
      } else {
        await convRepo.update(conv.id, {
          host_last_read_at: now,
          host_last_read_message_id: lastMsg?.id ?? null,
          unread_host: 0,
          conversation_version: nextVersion,
        });
      }

      const updated = await msgRepo
        .createQueryBuilder()
        .update(StaysMessage)
        .set({ status: 'READ', read_at: now })
        .where('conversation_id = :cid', { cid: conv.id })
        .andWhere('sender_id IS NOT NULL')
        .andWhere('sender_id != :uid', { uid: userId })
        .andWhere('read_at IS NULL')
        .execute();
      changedMessages = Number(updated.affected ?? 0);

      await this.outbox.enqueue(manager, EVENTS.MESSAGE_READ, {
        conversationId: conv.id,
        readerUserId: userId,
      });
    });

    const unreadWas = isGuest ? conv.unread_guest ?? 0 : conv.unread_host ?? 0;
    if (unreadWas > 0 || changedMessages > 0) {
      const counterpartUserId =
        userId === conv.guest_user_id ? conv.host_user_id : conv.guest_user_id;
      this.realtime.publish(userId, {
        conversationId: conv.id,
        reason: 'MESSAGE_READ',
        messageId: lastMsg?.id,
      });
      if (counterpartUserId) {
        this.realtime.publish(counterpartUserId, {
          conversationId: conv.id,
          reason: 'MESSAGE_READ',
          messageId: lastMsg?.id,
        });
      }
    }

    return { conversationVersion: nextVersion };
  }

  /**
   * SUPPORT customer sends: lock ticket (FOR UPDATE) and reject CLOSED before insert.
   */
  private async prepareCustomerSupportSend(
    manager: EntityManager,
    conv: StaysConversation,
    senderUserId: string,
  ) {
    if (conv.type !== 'SUPPORT') return null;
    const isRequester =
      senderUserId === conv.guest_user_id || senderUserId === conv.host_user_id;
    if (!isRequester) return null;
    return this.supportTickets.lockTicketForCustomerSend(manager, conv.id);
  }

  private publishMessageCreated(
    conv: StaysConversation,
    senderUserId: string,
    messageId: string,
  ): void {
    const recipientUserId =
      senderUserId === conv.guest_user_id
        ? conv.host_user_id
        : conv.guest_user_id;
    this.realtime.publish(recipientUserId, {
      conversationId: conv.id,
      reason: 'MESSAGE_CREATED',
      messageId,
    });
  }

  private async enqueueDeliveryEvents(
    manager: EntityManager,
    conv: StaysConversation,
    message: StaysMessage,
    userId: string,
    preview: string,
  ): Promise<void> {
    const refreshed = await manager.getRepository(StaysConversation).findOne({
      where: { id: conv.id },
    });

    const recipientId =
      userId === conv.guest_user_id ? conv.host_user_id : conv.guest_user_id;

    const senderName =
      userId === conv.guest_user_id
        ? (await this.guestDisplayName(conv, userId))
        : conv.host_user_id
          ? (await this.participants.resolveHostDisplayName(conv.host_user_id)) ?? 'Host'
          : 'Host';

    const snapshot = conv.reservation_snapshot as { listingTitle?: string };

    if (recipientId) {
      await this.outbox.enqueue(manager, EVENTS.MESSAGE_RECEIVED, {
        messageId: message.id,
        conversationId: conv.id,
        recipientUserId: recipientId,
        senderUserId: userId,
        senderName,
        preview: preview.slice(0, 120),
        bookingId: conv.booking_id,
        conversationVersion: refreshed?.conversation_version ?? conv.conversation_version + 1,
        lastMessageId: message.id,
        lastMessageSequence: Number(message.conversation_sequence),
        listingTitle: snapshot.listingTitle ?? '',
      });
    }

    await this.outbox.enqueue(manager, EVENTS.MESSAGE_SENT, {
      messageId: message.id,
      conversationId: conv.id,
      senderUserId: userId,
    });

    const visField = userId === conv.guest_user_id ? 'host_visibility' : 'guest_visibility';
    await manager
      .getRepository(StaysConversation)
      .createQueryBuilder()
      .update()
      .set({ [visField]: 'ACTIVE' })
      .where('id = :id', { id: conv.id })
      .andWhere(`${visField} = 'ARCHIVED'`)
      .execute();
  }

  private async guestDisplayName(
    conv: StaysConversation,
    userId: string,
  ): Promise<string> {
    if (!conv.booking_id) return 'Guest';
    return (
      (await this.participants.resolveGuestDisplayName(conv.booking_id, userId)) ??
      'Guest'
    );
  }

  private async getParticipantConversation(
    conversationId: string,
    userId: string,
  ): Promise<StaysConversation> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || !this.permissions.isParticipant(conv, userId)) {
      throw new NotFoundException('Conversation not found');
    }
    return conv;
  }

  private toDto(
    message: StaysMessage,
    userId: string,
    attachments: MessageDto['attachments'],
  ): MessageDto {
    const meta = (message.metadata ?? {}) as { presentationVersion?: number };
    const payload = buildMessagePayload(
      message.type,
      message.body,
      message.metadata ?? {},
      attachments,
    );
    return {
      id: message.id,
      conversationId: message.conversation_id,
      conversationSequence: Number(message.conversation_sequence),
      senderId: message.sender_id,
      type: message.type,
      body: message.body,
      metadata: message.metadata ?? {},
      payload,
      status: message.status,
      deliveryState: resolveDeliveryState(message),
      sentAt: message.sent_at?.toISOString() ?? null,
      deliveredAt: message.delivered_at?.toISOString() ?? null,
      readAt: message.read_at?.toISOString() ?? null,
      isSystem: message.is_system,
      clientMessageId: message.client_message_id,
      createdAt: message.created_at.toISOString(),
      isOwn: message.sender_id === userId,
      presentationVersion: meta.presentationVersion ?? 1,
      attachments,
    };
  }

  private async resolveSenderDisplayName(
    conv: StaysConversation,
    userId: string,
  ): Promise<string> {
    if (conv.guest_user_id === userId) {
      return this.guestDisplayName(conv, userId);
    }
    if (conv.host_user_id) {
      return (
        (await this.participants.resolveHostDisplayName(conv.host_user_id)) ?? 'Host'
      );
    }
    return 'Host';
  }
}

/** Internal messaging outbox events — handled locally, not published to domain event bus. */
export const MESSAGING_INTERNAL_EVENTS = {
  SNAPSHOT_REPAIR_REQUESTED: 'conversation.snapshot.repair.requested',
} as const;

export function isMessagingInternalEvent(eventType: string | null | undefined): boolean {
  if (!eventType) return false;
  return (
    eventType === MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED ||
    eventType.startsWith('conversation.')
  );
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysConversation } from './entities/stays-conversation.entity';
import { MessagingStateService } from './messaging-state.service';

@Injectable()
export class MessagingLifecycleScheduler {
  private readonly logger = new Logger(MessagingLifecycleScheduler.name);

  constructor(
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    private readonly messagingState: MessagingStateService,
  ) {}

  /** Auto-archive post-stay conversations past grace deadline. */
  @Cron(CronExpression.EVERY_HOUR)
  async archiveDuePostStayConversations(): Promise<void> {
    const count = await this.messagingState.archiveDueConversations();
    if (count > 0) {
      this.logger.log(`Auto-archived ${count} post-stay conversation(s)`);
    }
  }

  @Cron(CronExpression.EVERY_DAY_AT_1AM)
  async syncMessagingStates(): Promise<void> {
    const bookingConversations = await this.convRepo.find({
      where: { type: 'BOOKING' },
      select: ['booking_id'],
    });
    for (const conv of bookingConversations) {
      if (!conv.booking_id) continue;
      try {
        await this.messagingState.syncFromBooking(conv.booking_id);
      } catch (err) {
        this.logger.warn(`Failed to sync messaging state for ${conv.booking_id}: ${err}`);
      }
    }
  }
}

import {
  Controller,
  Get,
  Inject,
  NotFoundException,
  Param,
  Query,
  Res,
  forwardRef,
} from '@nestjs/common';
import { ApiOperation, ApiTags } from '@nestjs/swagger';
import type { Response } from 'express';
import { Readable } from 'stream';
import { ReadableStream } from 'stream/web';
import { Public } from '../../common/decorators/public.decorator';
import { deliverStoredMedia } from '../../common/media/deliver-stored-media';
import { MessagingMediaService } from './messaging-media.service';
import { StaysService } from '../stays/stays.service';
import { IdentityProfilePhotoClient } from '../../common/identity/identity-profile-photo.client';
import { AttachmentService } from './attachment.service';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysMessageAttachment } from './entities/stays-message-attachment.entity';

@ApiTags('messaging-media')
@Controller('messaging/media')
export class MessagingMediaController {
  constructor(
    private readonly media: MessagingMediaService,
    @Inject(forwardRef(() => StaysService))
    private readonly staysService: StaysService,
    private readonly profilePhotos: IdentityProfilePhotoClient,
    private readonly attachmentService: AttachmentService,
    @InjectRepository(StaysMessageAttachment)
    private readonly attachmentRepo: Repository<StaysMessageAttachment>,
  ) {}

  @Get('avatars/:userId')
  @Public()
  @ApiOperation({ summary: 'Signed avatar URL (messaging-owned media)' })
  async getAvatar(
    @Param('userId') userId: string,
    @Query('exp') exp: string,
    @Query('v') version: string,
    @Query('sig') sig: string,
    @Res() res: Response,
  ) {
    const expNum = Number(exp);
    if (!sig || !expNum || Date.now() > expNum) {
      throw new NotFoundException();
    }
    const valid = this.media.verifySignature(
      { userId, exp: expNum, v: Number(version) || 1, kind: 'avatar' },
      sig,
    );
    if (!valid) throw new NotFoundException();

    const photo = await this.profilePhotos.fetchProfilePhoto(userId);
    if (!photo) throw new NotFoundException();

    res.setHeader('Content-Type', photo.contentType);
    res.setHeader('Cache-Control', 'public, max-age=3600');
    res.setHeader('Cross-Origin-Resource-Policy', 'cross-origin');
    Readable.fromWeb(photo.body as unknown as ReadableStream<Uint8Array>).pipe(res);
  }

  @Get('listings/:listingId/cover/:mediaId')
  @Public()
  @ApiOperation({ summary: 'Signed listing cover thumbnail for messaging cards' })
  async getListingCover(
    @Param('listingId') listingId: string,
    @Param('mediaId') mediaId: string,
    @Query('exp') exp: string,
    @Query('v') version: string,
    @Query('w') w: string,
    @Query('h') h: string,
    @Query('fit') fit: string,
    @Query('sig') sig: string,
    @Res() res: Response,
  ) {
    const expNum = Number(exp);
    if (!sig || !expNum || Date.now() > expNum) {
      throw new NotFoundException();
    }
    const valid = this.media.verifySignature(
      {
        listingId,
        mediaId,
        exp: expNum,
        v: Number(version) || 1,
        w: Number(w) || 640,
        h: Number(h) || 360,
        fit: fit || 'crop',
        kind: 'listing_cover',
      },
      sig,
    );
    if (!valid) throw new NotFoundException();

    const fullPath = await this.staysService.getListingMediaPath(listingId, mediaId);
    await deliverStoredMedia(res, fullPath);
  }

  @Get('attachments/:attachmentId')
  @Public()
  @ApiOperation({ summary: 'Signed messaging attachment (thumb or full)' })
  async getAttachment(
    @Param('attachmentId') attachmentId: string,
    @Query('exp') exp: string,
    @Query('v') version: string,
    @Query('variant') variant: string,
    @Query('sig') sig: string,
    @Res() res: Response,
  ) {
    const expNum = Number(exp);
    const variantNorm = variant === 'thumb' ? 'thumb' : 'full';
    if (!sig || !expNum || Date.now() > expNum) {
      throw new NotFoundException();
    }
    const valid = this.media.verifySignature(
      {
        attachmentId,
        exp: expNum,
        v: Number(version) || 1,
        variant: variantNorm,
        kind: 'attachment',
      },
      sig,
    );
    if (!valid) throw new NotFoundException();

    const row = await this.attachmentRepo.findOne({ where: { id: attachmentId } });
    if (!row || row.status !== 'READY') throw new NotFoundException();

    const rel =
      variantNorm === 'thumb' && row.thumbnail_url
        ? row.thumbnail_url
        : row.storage_url;
    const fullPath = await this.attachmentService.resolveDelivery(rel);
    await deliverStoredMedia(res, fullPath, {
      contentType: row.mime ?? undefined,
    });
  }
}

import { Injectable } from '@nestjs/common';
import { createHmac, timingSafeEqual } from 'crypto';
import type { SignedMedia } from './messaging.types';
import { isProductionRuntime, requirePublicBaseUrl } from '../../common/security/secrets';

const DEFAULT_TTL_MS = 60 * 60 * 1000;

export interface ListingCoverVariant {
  w?: number;
  h?: number;
  fit?: 'crop' | 'cover';
}

@Injectable()
export class MessagingMediaService {
  private signingSecret(): string {
    const fromEnv =
      process.env.MESSAGING_MEDIA_SECRET?.trim() ||
      process.env.JWT_SECRET?.trim();
    if (fromEnv) return fromEnv;
    if (isProductionRuntime()) {
      throw new Error(
        'MESSAGING_MEDIA_SECRET or JWT_SECRET is required in production for signed media URLs.',
      );
    }
    return 'nexa-messaging-media-dev';
  }

  private publicBaseUrl(): string {
    const base = requirePublicBaseUrl('STAYS_PUBLIC_URL', 'http://127.0.0.1:3002');
    const withApi = base.endsWith('/api/v1') ? base : `${base}/api/v1`;
    return withApi;
  }

  signPayload(payload: Record<string, string | number>): string {
    const canonical = Object.keys(payload)
      .sort()
      .map((k) => `${k}=${payload[k]}`)
      .join('&');
    return createHmac('sha256', this.signingSecret()).update(canonical).digest('hex');
  }

  verifySignature(
    payload: Record<string, string | number>,
    signature: string,
  ): boolean {
    const expected = this.signPayload(payload);
    try {
      return timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
    } catch {
      return false;
    }
  }

  resolveAvatar(userId: string, version = 1, ttlMs = DEFAULT_TTL_MS): SignedMedia {
    const exp = Date.now() + ttlMs;
    const sig = this.signPayload({ userId, exp, v: version, kind: 'avatar' });
    return {
      url: `${this.publicBaseUrl()}/messaging/media/avatars/${encodeURIComponent(userId)}?exp=${exp}&v=${version}&sig=${sig}`,
      version,
      expiresAt: new Date(exp).toISOString(),
    };
  }

  resolveListingCover(
    listingId: string,
    coverMediaId: string | null,
    variant?: ListingCoverVariant,
    version = 1,
    ttlMs = DEFAULT_TTL_MS,
  ): SignedMedia | null {
    if (!coverMediaId || !listingId) return null;
    const exp = Date.now() + ttlMs;
    const w = variant?.w ?? 640;
    const h = variant?.h ?? 360;
    const fit = variant?.fit ?? 'crop';
    const sig = this.signPayload({
      listingId,
      mediaId: coverMediaId,
      exp,
      v: version,
      w,
      h,
      fit,
      kind: 'listing_cover',
    });
    return {
      url: `${this.publicBaseUrl()}/messaging/media/listings/${encodeURIComponent(listingId)}/cover/${encodeURIComponent(coverMediaId)}?exp=${exp}&v=${version}&w=${w}&h=${h}&fit=${fit}&sig=${sig}`,
      version,
      expiresAt: new Date(exp).toISOString(),
    };
  }

  resolveAttachment(
    attachmentId: string,
    variant: 'thumb' | 'full',
    version = 1,
    ttlMs = DEFAULT_TTL_MS,
  ): SignedMedia {
    const exp = Date.now() + ttlMs;
    const sig = this.signPayload({
      attachmentId,
      exp,
      v: version,
      variant,
      kind: 'attachment',
    });
    return {
      url: `${this.publicBaseUrl()}/messaging/media/attachments/${encodeURIComponent(attachmentId)}?exp=${exp}&v=${version}&variant=${variant}&sig=${sig}`,
      version,
      expiresAt: new Date(exp).toISOString(),
    };
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
