import { DomainEventsService } from '../../common/events/domain-events.service';
import { EVENTS } from '@nexa/event-bus';

function parseCheckoutDateTime(
  checkoutDate: Date | string,
  checkoutTime: string,
): Date {
  const dateStr =
    checkoutDate instanceof Date
      ? checkoutDate.toISOString().slice(0, 10)
      : String(checkoutDate).slice(0, 10);
  const [hourPart, minutePart] = checkoutTime.split(':');
  const hours = Number(hourPart) || 11;
  const minutes = Number(minutePart) || 0;
  return new Date(
    `${dateStr}T${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:00`,
  );
}

@Injectable()
export class MessagingStateService {
  private readonly logger = new Logger(MessagingStateService.name);

  constructor(
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    private readonly dataSource: DataSource,
    private readonly timelineSeeder: TimelineSeederService,
    private readonly domainEvents: DomainEventsService,
  ) {}

  getPostStayGraceHours(): number {
    const raw = Number(process.env.POST_STAY_GRACE_HOURS ?? 72);
    return Number.isFinite(raw) && raw > 0 ? raw : 72;
  }

  computePostStayEndsAt(booking: StaysBooking, listing?: StaysListing | null): Date {
    const checkoutAt =
      booking.completed_at ??
      parseCheckoutDateTime(booking.checkout_date, listing?.checkout_time ?? '11:00');
    const graceMs = this.getPostStayGraceHours() * 60 * 60 * 1000;
    return new Date(checkoutAt.getTime() + graceMs);
  }

  /** Sync booking status → conversation state (cancel lock, post-stay entry, overdue archive). */
  async syncFromBooking(bookingId: string): Promise<void> {
    const booking = await this.bookingRepo.findOne({
      where: { id: bookingId },
      relations: ['listing'],
    });
    const conv = await this.convRepo.findOne({ where: { booking_id: bookingId } });
    if (!booking || !conv) return;

    const now = new Date();
    if (
      booking.status === 'CANCELLED_BY_GUEST' ||
      booking.status === 'CANCELLED_BY_HOST'
    ) {
      await this.convRepo.update(conv.id, {
        messaging_state: 'LOCKED',
        locked_at: conv.locked_at ?? now,
        conversation_version: conv.conversation_version + 1,
      });
      return;
    }

    if (booking.status === 'COMPLETED') {
      if (conv.messaging_state === 'ARCHIVED') return;
      if (conv.post_stay_ends_at && conv.post_stay_ends_at <= now && !conv.auto_archive_disabled) {
        await this.archiveConversation(conv.id, 'AUTO');
        return;
      }
      await this.enterPostStay(bookingId);
    }
  }

  /** Checkout → post-stay: chat stays active until post_stay_ends_at. */
  async enterPostStay(bookingId: string): Promise<void> {
    const booking = await this.bookingRepo.findOne({ where: { id: bookingId } });
    const conv = await this.convRepo.findOne({ where: { booking_id: bookingId } });
    if (!booking || !conv || booking.status !== 'COMPLETED') return;
    if (conv.messaging_state === 'ACTIVE' && conv.post_stay_ends_at) return;

    const listing = booking.listing_id
      ? await this.listingRepo.findOne({ where: { id: booking.listing_id } })
      : null;
    const postStayEndsAt = this.computePostStayEndsAt(booking, listing);

    await this.dataSource.transaction(async (manager) => {
      const messageRepo = manager.getRepository(StaysMessage);
      const convRepo = manager.getRepository(StaysConversation);

      const hasReviewCard = await messageRepo.exists({
        where: { conversation_id: conv.id, type: 'REVIEW_CARD' },
      });
      if (!hasReviewCard) {
        await this.timelineSeeder.seedCheckoutComplete(manager, conv, booking);
      }

      await convRepo.update(conv.id, {
        messaging_state: 'ACTIVE',
        guest_visibility: 'ACTIVE',
        host_visibility: 'ACTIVE',
        post_stay_ends_at: postStayEndsAt,
        archived_at: null,
        read_only_at: null,
        archive_reason: null,
        conversation_version: conv.conversation_version + 1,
      });
    });

    this.logger.log(
      `Post-stay started for booking ${bookingId}; archive scheduled at ${postStayEndsAt.toISOString()}`,
    );
  }

  async archiveConversation(
    conversationId: string,
    reason: ArchiveReason | string = 'AUTO',
  ): Promise<void> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv || conv.messaging_state === 'ARCHIVED') return;

    const booking = conv.booking_id
      ? await this.bookingRepo.findOne({ where: { id: conv.booking_id } })
      : null;
    const listing = booking?.listing_id
      ? await this.listingRepo.findOne({ where: { id: booking.listing_id } })
      : null;

    const now = new Date();

    await this.dataSource.transaction(async (manager) => {
      const messageRepo = manager.getRepository(StaysMessage);
      const convRepo = manager.getRepository(StaysConversation);

      const hasArchiveNotice = await messageRepo.exists({
        where: { conversation_id: conv.id, type: 'SYSTEM_NOTICE' },
      });

      if (!hasArchiveNotice) {
        await this.timelineSeeder.seedConversationArchived(
          manager,
          conv,
          booking?.id ?? conv.booking_id,
        );
      }

      await convRepo.update(conv.id, {
        messaging_state: 'ARCHIVED',
        guest_visibility: 'ARCHIVED',
        host_visibility: 'ARCHIVED',
        archived_at: conv.archived_at ?? now,
        read_only_at: conv.read_only_at ?? now,
        archive_reason: reason,
        conversation_version: conv.conversation_version + 1,
      });
    });

    if (conv.booking_id && conv.guest_user_id && conv.host_user_id) {
      void this.domainEvents.publish(EVENTS.CONVERSATION_ARCHIVED, 'stays', {
        bookingId: conv.booking_id,
        listingId: conv.listing_id ?? booking?.listing_id ?? '',
        conversationId: conv.id,
        guestUserId: conv.guest_user_id,
        hostUserId: conv.host_user_id,
        listingTitle: listing?.title,
      });
    }

    this.logger.log(`Archived conversation ${conversationId} (${reason})`);
  }

  async reopenConversation(
    conversationId: string,
    options: { reason?: string; disableAutoArchive?: boolean } = {},
  ): Promise<StaysConversation> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv) throw new NotFoundException('Conversation not found');

    const booking = conv.booking_id
      ? await this.bookingRepo.findOne({ where: { id: conv.booking_id } })
      : null;
    const listing = booking?.listing_id
      ? await this.listingRepo.findOne({ where: { id: booking.listing_id } })
      : null;

    const postStayEndsAt =
      booking?.status === 'COMPLETED' && !options.disableAutoArchive
        ? this.computePostStayEndsAt(booking, listing)
        : conv.post_stay_ends_at;

    await this.convRepo.update(conv.id, {
      messaging_state: 'ACTIVE',
      guest_visibility: 'ACTIVE',
      host_visibility: 'ACTIVE',
      archived_at: null,
      read_only_at: null,
      archive_reason: null,
      post_stay_ends_at: postStayEndsAt,
      auto_archive_disabled: options.disableAutoArchive ?? false,
      auto_archive_disabled_reason: options.disableAutoArchive
        ? (options.reason ?? 'manual')
        : null,
      conversation_version: conv.conversation_version + 1,
    });

    const updated = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!updated) throw new NotFoundException('Conversation not found');
    return updated;
  }

  async archiveDueConversations(): Promise<number> {
    const due = await this.convRepo
      .createQueryBuilder('c')
      .where('c.type = :t', { t: 'BOOKING' })
      .andWhere("c.messaging_state = 'ACTIVE'")
      .andWhere('c.post_stay_ends_at IS NOT NULL')
      .andWhere('c.post_stay_ends_at <= NOW()')
      .andWhere('c.auto_archive_disabled = FALSE')
      .getMany();

    for (const conv of due) {
      try {
        await this.archiveConversation(conv.id, 'AUTO');
      } catch (err) {
        this.logger.warn(
          `Failed to auto-archive ${conv.id}: ${err instanceof Error ? err.message : String(err)}`,
        );
      }
    }
    return due.length;
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  ParseUUIDPipe,
  Patch,
  Post,
  Query,
  Sse,
  UploadedFile,
  UseInterceptors,
} from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { memoryStorage } from 'multer';
import { ApiBearerAuth, ApiConsumes, ApiOperation, ApiTags } from '@nestjs/swagger';
import { multerLimits } from '../../common/security/multer-limits';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { ConversationsService } from './conversations.service';
import { MessagesService } from './messages.service';
import { AttachmentService } from './attachment.service';
import { AttachmentSessionService } from './attachment-session.service';
import { MessageSearchService } from './message-search.service';
import { SendMessageDto } from './dto/send-message.dto';
import { UpdateVisibilityDto } from './dto/update-visibility.dto';
import { ReportConversationDto } from './dto/report-conversation.dto';
import { SafetyIssueDto } from './dto/safety-issue.dto';
import { ReopenConversationDto } from './dto/reopen-conversation.dto';

const MAX_ATTACHMENT_BYTES = 20 * 1024 * 1024;

@ApiTags('messaging')
@ApiBearerAuth()
@Controller('messaging')
export class MessagingController {
  constructor(
    private readonly conversations: ConversationsService,
    private readonly messages: MessagesService,
    private readonly attachments: AttachmentService,
    private readonly attachmentSessions: AttachmentSessionService,
    private readonly search: MessageSearchService,
  ) {}

  @Sse('realtime')
  @ApiOperation({ summary: 'Authenticated live messaging event stream' })
  realtime(@CurrentUser() user: { userId: string }) {
    return this.messages.realtimeStream(user.userId);
  }

  @Get('conversations')
  @ApiOperation({ summary: 'List conversations for current user' })
  list(
    @CurrentUser() user: { userId: string },
    @Query('filter') filter?: string,
    @Query('q') q?: string,
  ) {
    return this.conversations.listConversations(user.userId, filter ?? 'active', q);
  }

  @Get('conversations/unread-count')
  @ApiOperation({ summary: 'Unread conversation count' })
  unreadCount(@CurrentUser() user: { userId: string }) {
    return this.conversations.getUnreadCount(user.userId).then((count) => ({ count }));
  }

  @Get('conversations/by-booking/:bookingId')
  @ApiOperation({ summary: 'Find conversation for a booking' })
  byBooking(
    @CurrentUser() user: { userId: string },
    @Param('bookingId', ParseUUIDPipe) bookingId: string,
  ) {
    return this.conversations.getConversationByBooking(bookingId, user.userId);
  }

  @Post('conversations/ensure-for-booking/:bookingId')
  @ApiOperation({
    summary: 'Ensure inbox thread exists for a confirmed booking (backfill)',
  })
  ensureForBooking(
    @CurrentUser() user: { userId: string },
    @Param('bookingId', ParseUUIDPipe) bookingId: string,
  ) {
    return this.conversations.ensureConversationForBooking(
      bookingId,
      user.userId,
    );
  }

  @Get('conversations/:id')
  @ApiOperation({ summary: 'Get conversation with messages' })
  getOne(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Query('before_sequence') beforeSequence?: string,
  ) {
    const seq = beforeSequence ? Number(beforeSequence) : undefined;
    return this.conversations.getConversation(id, user.userId, seq);
  }

  @Get('conversations/:id/messages')
  @ApiOperation({ summary: 'List messages (cursor pagination)' })
  listMessages(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Query('limit') limit?: string,
    @Query('before_sequence') beforeSequence?: string,
  ) {
    return this.messages.listMessages(
      id,
      user.userId,
      limit ? Number(limit) : 30,
      beforeSequence ? Number(beforeSequence) : undefined,
    );
  }

  @Get('conversations/:id/search')
  @ApiOperation({ summary: 'Search messages, files, photos, links, and cards' })
  searchConversation(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Query('q') q?: string,
    @Query('types') types?: string,
  ) {
    const parsedTypes = types
      ? (types.split(',').filter(Boolean) as Array<'message' | 'file' | 'photo' | 'link' | 'card'>)
      : undefined;
    return this.search.search(id, user.userId, q ?? '', parsedTypes);
  }

  @Post('conversations/:id/attachment-sessions')
  @ApiOperation({ summary: 'Create attachment upload session' })
  createAttachmentSession(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    return this.attachmentSessions.createSession(id, user.userId);
  }

  @Get('attachment-sessions/:sessionId')
  @ApiOperation({ summary: 'Get attachment session with uploads' })
  getAttachmentSession(
    @CurrentUser() user: { userId: string },
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
  ) {
    return this.attachmentSessions.getSession(sessionId, user.userId);
  }

  @Post('attachment-sessions/:sessionId/attachments')
  @ApiOperation({ summary: 'Upload file into attachment session' })
  @ApiConsumes('multipart/form-data')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: memoryStorage(),
      limits: multerLimits(MAX_ATTACHMENT_BYTES),
    }),
  )
  uploadToAttachmentSession(
    @CurrentUser() user: { userId: string },
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
    @UploadedFile() file: Express.Multer.File,
  ) {
    return this.attachmentSessions.uploadToSession(sessionId, user.userId, file);
  }

  @Post('attachment-sessions/:sessionId/complete')
  @ApiOperation({ summary: 'Mark session ready after all uploads succeed' })
  completeAttachmentSession(
    @CurrentUser() user: { userId: string },
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
  ) {
    return this.attachmentSessions.completeSession(sessionId, user.userId);
  }

  @Delete('attachment-sessions/:sessionId/attachments/:attachmentId')
  @ApiOperation({ summary: 'Remove attachment from session before send' })
  deleteSessionAttachment(
    @CurrentUser() user: { userId: string },
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
    @Param('attachmentId', ParseUUIDPipe) attachmentId: string,
  ) {
    return this.attachmentSessions
      .deleteAttachmentFromSession(sessionId, attachmentId, user.userId)
      .then(() => ({ ok: true }));
  }

  @Delete('attachment-sessions/:sessionId')
  @ApiOperation({ summary: 'Abandon attachment session and delete staged uploads' })
  abandonAttachmentSession(
    @CurrentUser() user: { userId: string },
    @Param('sessionId', ParseUUIDPipe) sessionId: string,
  ) {
    return this.attachmentSessions.abandonSession(sessionId, user.userId).then(() => ({ ok: true }));
  }

  @Post('conversations/:id/attachments')
  @ApiOperation({ summary: 'Upload attachment (legacy — prefer attachment sessions)' })
  @ApiConsumes('multipart/form-data')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: memoryStorage(),
      limits: multerLimits(MAX_ATTACHMENT_BYTES),
    }),
  )
  uploadAttachment(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @UploadedFile() file: Express.Multer.File,
  ) {
    return this.attachments.createFromUpload(id, user.userId, file);
  }

  @Post('conversations/:id/report-evidence')
  @ApiOperation({ summary: 'Upload screenshot evidence for report or safety issue' })
  @ApiConsumes('multipart/form-data')
  @UseInterceptors(
    FileInterceptor('file', {
      storage: memoryStorage(),
      limits: multerLimits(MAX_ATTACHMENT_BYTES),
    }),
  )
  uploadReportEvidence(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @UploadedFile() file: Express.Multer.File,
  ) {
    return this.attachments.createEvidenceFromUpload(id, user.userId, file);
  }

  @Get('conversations/:id/attachments/:attachmentId')
  @ApiOperation({ summary: 'Get attachment status and signed URLs' })
  getAttachment(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Param('attachmentId', ParseUUIDPipe) attachmentId: string,
  ) {
    return this.attachments.getAttachment(id, attachmentId, user.userId);
  }

  @Post('conversations/:id/messages')
  @ApiOperation({ summary: 'Send a message (text or with attachment references)' })
  send(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: SendMessageDto,
  ) {
    if (dto.body && !dto.type && !dto.attachment_ids?.length) {
      return this.messages.sendText(id, user.userId, dto.body, dto.client_message_id);
    }
    return this.messages.sendMessage(id, user.userId, dto);
  }

  @Post('conversations/:id/read')
  @ApiOperation({ summary: 'Mark conversation as read' })
  markRead(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    return this.messages.markRead(id, user.userId);
  }

  @Patch('conversations/:id/visibility')
  @ApiOperation({ summary: 'Archive, delete, or restore conversation for caller' })
  visibility(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: UpdateVisibilityDto,
  ) {
    return this.conversations.updateVisibility(id, user.userId, dto.action);
  }

  @Post('conversations/:id/reopen')
  @ApiOperation({ summary: 'Reopen an archived conversation' })
  reopen(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: ReopenConversationDto,
  ) {
    return this.conversations.reopenConversation(id, user.userId, {
      reason: dto.reason,
      disableAutoArchive: dto.disableAutoArchive,
    });
  }

  @Post('conversations/:id/report')
  async report(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: ReportConversationDto,
  ) {
    const attachmentIds = dto.attachmentIds ?? [];
    if (attachmentIds.length) {
      await this.attachments.assertEvidenceReady(id, user.userId, attachmentIds);
      await this.attachments.markAsReportEvidence(attachmentIds);
    }
    const result = await this.conversations.report(
      id,
      user.userId,
      dto.reason,
      attachmentIds,
    );
    return {
      ok: true,
      reportId: result.reportId,
      ticketId: result.ticketId,
      ticketNumber: result.ticketNumber,
      supportConversationId: result.supportConversationId,
    };
  }

  @Post('conversations/:id/block')
  block(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    return this.conversations.block(id, user.userId).then(() => ({ ok: true }));
  }

  @Post('conversations/:id/safety')
  async safety(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Body() dto: SafetyIssueDto,
  ) {
    const attachmentIds = dto.attachmentIds ?? [];
    if (attachmentIds.length) {
      await this.attachments.assertEvidenceReady(id, user.userId, attachmentIds);
      await this.attachments.markAsReportEvidence(attachmentIds);
    }
    return this.conversations.safety(id, user.userId, {
      category: dto.category,
      details: dto.details,
      attachmentIds,
    });
  }
}

export type NotificationLevel = 'ALL' | 'IMPORTANT' | 'MUTED';

export type ConversationViewerRole = 'guest' | 'host';

export interface ConversationPermissions {
  canSend: boolean;
  canUpload: boolean;
  canCall: boolean;
  canReport: boolean;
  canBlock: boolean;
  canReview: boolean;
  viewerRole: ConversationViewerRole;
  isReadOnly: boolean;
  canArchive: boolean;
  canDelete: boolean;
  notificationLevel: NotificationLevel;
}

export interface SignedMedia {
  url: string;
  version: number;
  expiresAt: string;
}

export interface ReservationSnapshot {
  listingTitle: string;
  listingId?: string | null;
  coverMediaId?: string | null;
  /** @deprecated derive via MessagingMediaService */
  primaryPhotoUrl?: string | null;
  addressDisplay?: string | null;
  city?: string | null;
  country?: string | null;
  checkinDate: string;
  checkoutDate: string;
  guestCount: number;
  hostDisplayName?: string | null;
  guestDisplayName?: string | null;
  bookingReference?: string | null;
  listingReference?: string | null;
}

export interface ReservationPresentation {
  listingTitle: string;
  listingId: string | null;
  coverMedia: SignedMedia | null;
  addressDisplay: string | null;
  city: string | null;
  country: string | null;
  checkinDate: string;
  checkoutDate: string;
  guestCount: number;
  bookingReference: string | null;
  bookingId: string | null;
}

export interface ConversationPresentation {
  title: string;
  subtitle: string;
  avatar: SignedMedia | null;
  bookingChip: string | null;
  statusChip: string | null;
  counterpart: {
    id: string;
    displayName: string;
    verified?: boolean;
    rating?: number | null;
  };
  listing: {
    title: string;
    city?: string | null;
  };
  reservation: ReservationPresentation;
}

export interface ConversationSyncMeta {
  conversationVersion: number;
  snapshotVersion: number;
  attachmentVersion: number;
  lastMessageId: string | null;
  unreadCount: number;
  lastReadPointer: {
    messageId: string | null;
    readAt: string | null;
  };
}

export interface ConversationDomain {
  id: string;
  type: string;
  bookingId: string | null;
  listingId: string | null;
  messagingState: string;
  visibility: string;
  postStayEndsAt?: string | null;
  autoArchiveDisabled?: boolean;
  archiveReason?: string | null;
}

export interface ConversationListResponse {
  conversation: ConversationDomain;
  presentation: ConversationPresentation;
  sync: ConversationSyncMeta;
  lastMessage: {
    preview: string | null;
    at: string | null;
  };
  permissions: ConversationPermissions;
}

export interface ConversationDetailResponse {
  conversation: ConversationDomain;
  presentation: ConversationPresentation;
  timeline: MessageDto[];
  permissions: ConversationPermissions;
  sync: ConversationSyncMeta;
  hasMore: boolean;
  bookingStatus: string | null;
}

/** @deprecated use ConversationListResponse */
export interface ConversationListItem {
  id: string;
  type: string;
  messagingState: string;
  visibility: string;
  conversationVersion: number;
  lastMessageSequence: number;
  unreadCount: number;
  counterpart: {
    name: string;
    avatarUrl?: string | null;
    isSuperhost: boolean;
  };
  listing: {
    title: string;
    city?: string | null;
  };
  lastMessage: {
    preview: string | null;
    at: string | null;
    deliveryStatus?: string;
  };
  reservationSnapshot: ReservationSnapshot;
  permissions: ConversationPermissions;
}

export interface TimelineCardMetadata {
  schemaVersion: number;
  cardVersion: number;
  presentationVersion?: number;
  kind: string;
  title: string;
  body?: string;
  icon?: string;
  source?: 'USER' | 'SYSTEM' | 'AI' | 'HOST_AUTOMATION';
  actions?: Array<{
    id: string;
    label: string;
    type: string;
    value?: string;
    url?: string;
  }>;
  snapshot?: Record<string, unknown>;
  coverMediaId?: string | null;
  listingId?: string | null;
  bookingId?: string | null;
}

export type DeliveryState = 'PENDING' | 'PERSISTED' | 'SENT' | 'DELIVERED' | 'READ';

export type ProcessingStatus = 'UPLOADING' | 'PROCESSING' | 'READY' | 'FAILED';
export type VirusScanStatus = 'PENDING' | 'SAFE' | 'FAILED';

export interface AttachmentDto {
  id: string;
  sessionId: string | null;
  mediaAssetId: string | null;
  /** Processing pipeline status */
  processingStatus: ProcessingStatus;
  /** @deprecated use processingStatus */
  status: ProcessingStatus;
  virusScanStatus: VirusScanStatus;
  mime: string | null;
  sizeBytes: number | null;
  width: number | null;
  height: number | null;
  orientation: number | null;
  durationMs: number | null;
  checksum: string | null;
  blurhash: string | null;
  originalFilename: string | null;
  thumbnail: SignedMedia | null;
  full: SignedMedia | null;
  /** Alias for full — structured signed URL contract */
  original: SignedMedia | null;
}

export interface AttachmentSessionDto {
  id: string;
  conversationId: string;
  status: 'CREATED' | 'UPLOADING' | 'READY' | 'COMPLETED' | 'ABANDONED';
  expiresAt: string;
  attachments: AttachmentDto[];
}

export interface TextPayload {
  text: string;
}

export interface MediaPayload {
  attachmentIds: string[];
  caption?: string;
  attachments?: AttachmentDto[];
}

export interface TimelineCardPayload {
  kind: string;
  title: string;
  body?: string;
  icon?: string;
  actions?: Array<{
    id: string;
    label: string;
    type: string;
    value?: string;
    url?: string;
  }>;
  coverMediaId?: string | null;
  listingId?: string | null;
  bookingId?: string | null;
  snapshot?: Record<string, unknown>;
}

export type MessagePayload = TextPayload | MediaPayload | TimelineCardPayload;

export interface MessageDto {
  id: string;
  conversationId: string;
  conversationSequence: number;
  senderId: string | null;
  type: string;
  body: string | null;
  metadata: Record<string, unknown>;
  payload: MessagePayload;
  status: string;
  deliveryState: DeliveryState;
  sentAt: string | null;
  deliveredAt: string | null;
  readAt: string | null;
  isSystem: boolean;
  clientMessageId: string | null;
  createdAt: string;
  isOwn: boolean;
  presentationVersion: number;
  attachments: AttachmentDto[];
}

/** @deprecated use ConversationDetailResponse */
export interface ConversationDetail extends ConversationListItem {
  bookingId: string | null;
  bookingStatus?: string | null;
  messages: MessageDto[];
  hasMore: boolean;
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { StaysMessagingOutbox } from './entities/stays-messaging-outbox.entity';

@Injectable()
export class MessagingOutboxService {
  constructor(
    @InjectRepository(StaysMessagingOutbox)
    private readonly outboxRepo: Repository<StaysMessagingOutbox>,
  ) {}

  async enqueue(
    manager: EntityManager,
    eventType: string,
    payload: Record<string, unknown>,
  ): Promise<void> {
    const repo = manager.getRepository(StaysMessagingOutbox);
    await repo.save(
      repo.create({
        event_type: eventType,
        payload,
        status: 'PENDING',
        attempts: 0,
        next_retry_at: new Date(),
      }),
    );
  }

  async enqueueDirect(eventType: string, payload: Record<string, unknown>): Promise<void> {
    await this.outboxRepo.save(
      this.outboxRepo.create({
        event_type: eventType,
        payload,
        status: 'PENDING',
        attempts: 0,
        next_retry_at: new Date(),
      }),
    );
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysMessagingOutbox } from './entities/stays-messaging-outbox.entity';
import { DomainEventsService } from '../../common/events/domain-events.service';
import { isMessagingInternalEvent, MESSAGING_INTERNAL_EVENTS } from './messaging-internal.events';
import { SnapshotRepairService } from './snapshot-repair.service';
import { EVENTS, EventValidationError } from '@nexa/event-bus';

const MAX_OUTBOX_ATTEMPTS = 5;

function resolveProviderIntentId(
  bookingId: string,
  providerIntentId?: string | null,
  paymentIntentId?: string | null,
): string {
  const candidate = (providerIntentId ?? paymentIntentId ?? '').trim();
  return candidate || `booking-${bookingId}`;
}

@Injectable()
export class MessagingOutboxWorker {
  private readonly logger = new Logger(MessagingOutboxWorker.name);
  private processing = false;

  constructor(
    @InjectRepository(StaysMessagingOutbox)
    private readonly outboxRepo: Repository<StaysMessagingOutbox>,
    private readonly domainEvents: DomainEventsService,
    private readonly snapshotRepair: SnapshotRepairService,
  ) {}

  @Cron(CronExpression.EVERY_5_SECONDS)
  async processOutbox(): Promise<void> {
    if (this.processing) return;
    this.processing = true;
    try {
      await this.recoverStaleProcessingRows();
      const rows = await this.claimPendingRows(20);
      for (const row of rows) {
        if (!row?.id || !row.event_type) {
          this.logger.warn('Skipping outbox row with missing id or event_type');
          continue;
        }
        try {
          const payload = this.normalizePayload(row.event_type, row.payload as Record<string, unknown>);
          if (isMessagingInternalEvent(row.event_type)) {
            await this.handleInternalEvent(row.event_type, payload);
          } else {
            await this.domainEvents.publish(
              row.event_type as Parameters<DomainEventsService['publish']>[0],
              'stays',
              payload,
            );
          }
          await this.outboxRepo.update(row.id, {
            status: 'DONE',
            processed_at: new Date(),
          });
        } catch (err) {
          const attempts = (row.attempts ?? 0) + 1;
          const isValidationError = err instanceof EventValidationError;
          const isPermanentFailure = isValidationError || attempts >= MAX_OUTBOX_ATTEMPTS;
          const delayMs = Math.min(60_000, 1000 * 2 ** attempts);
          this.logger.warn(`Outbox ${row.id} failed attempt ${attempts}: ${err}`);
          await this.outboxRepo.update(row.id, {
            status: isPermanentFailure ? 'FAILED' : 'PENDING',
            attempts,
            next_retry_at: isPermanentFailure ? row.next_retry_at : new Date(Date.now() + delayMs),
          });
        }
      }
    } finally {
      this.processing = false;
    }
  }

  private async handleInternalEvent(
    eventType: string,
    payload: Record<string, unknown>,
  ): Promise<void> {
    if (eventType === MESSAGING_INTERNAL_EVENTS.SNAPSHOT_REPAIR_REQUESTED) {
      const conversationId = payload.conversationId;
      if (typeof conversationId !== 'string' || !conversationId) {
        throw new Error('snapshot repair missing conversationId');
      }
      await this.snapshotRepair.repairConversation(conversationId);
      return;
    }
    throw new Error(`Unknown internal messaging event: ${eventType}`);
  }

  /** Atomically claim rows with SKIP LOCKED for multi-instance safety. */
  async claimPendingRows(limit: number): Promise<StaysMessagingOutbox[]> {
    const raw = await this.outboxRepo.manager.query(
      `UPDATE stays_messaging_outbox
       SET status = 'PROCESSING'
       WHERE id IN (
         SELECT id FROM stays_messaging_outbox
         WHERE status = 'PENDING'
           AND next_retry_at <= NOW()
         ORDER BY created_at ASC
         LIMIT $1
         FOR UPDATE SKIP LOCKED
       )
       RETURNING *`,
      [limit],
    );
    return this.unwrapQueryRows(raw);
  }

  /** TypeORM 0.3 pg driver returns [rows, rowCount] for UPDATE…RETURNING. */
  private unwrapQueryRows(raw: unknown): StaysMessagingOutbox[] {
    if (Array.isArray(raw) && raw.length === 2 && Array.isArray(raw[0])) {
      return raw[0] as StaysMessagingOutbox[];
    }
    if (Array.isArray(raw)) {
      return raw as StaysMessagingOutbox[];
    }
    return [];
  }

  /** Repair legacy rows enqueued before providerIntentId validation was enforced. */
  private normalizePayload(
    eventType: string,
    payload: Record<string, unknown>,
  ): Record<string, unknown> {
    if (
      eventType === EVENTS.PAYMENT_SUCCEEDED &&
      typeof payload.bookingId === 'string' &&
      payload.bookingId
    ) {
      const providerIntentId =
        typeof payload.providerIntentId === 'string' ? payload.providerIntentId : undefined;
      return {
        ...payload,
        providerIntentId: resolveProviderIntentId(
          payload.bookingId,
          providerIntentId,
          typeof payload.paymentIntentId === 'string' ? payload.paymentIntentId : undefined,
        ),
      };
    }
    return payload;
  }

  /** Re-queue rows left in PROCESSING after a crash or failed retry update. */
  private async recoverStaleProcessingRows(): Promise<void> {
    await this.outboxRepo.manager.query(
      `UPDATE stays_messaging_outbox
       SET status = 'PENDING', next_retry_at = NOW()
       WHERE status = 'PROCESSING'
         AND processed_at IS NULL
         AND created_at < NOW() - INTERVAL '1 minute'`,
    );
  }
}

import { Injectable } from '@nestjs/common';
import { StaysConversation } from './entities/stays-conversation.entity';
import type { ConversationPermissions } from './messaging.types';

export type MessagingAccessOptions = {
  /** ADMIN JWT may read/send SUPPORT conversations only — never occupies guest/host ids. */
  isAdmin?: boolean;
  /** SUPPORT ticket CLOSED — force read-only even if archive lagged. */
  ticketClosed?: boolean;
};

@Injectable()
export class MessagingPermissionsService {
  resolve(
    conversation: StaysConversation,
    userId: string,
    options: MessagingAccessOptions = {},
  ): ConversationPermissions {
    const isGuest = conversation.guest_user_id === userId;
    const isHost = conversation.host_user_id === userId;
    const isSupportAdmin =
      Boolean(options.isAdmin) && conversation.type === 'SUPPORT';

    if (!isGuest && !isHost && !isSupportAdmin) {
      return this.denied();
    }

    if (isSupportAdmin && !isGuest && !isHost) {
      const readOnlyState =
        conversation.messaging_state === 'READ_ONLY' ||
        conversation.messaging_state === 'ARCHIVED' ||
        conversation.messaging_state === 'LOCKED' ||
        Boolean(options.ticketClosed);
      return {
        canSend: !readOnlyState,
        canUpload: !readOnlyState,
        canCall: false,
        canReport: false,
        canBlock: false,
        canReview: false,
        viewerRole: 'host',
        isReadOnly: readOnlyState,
        canArchive: false,
        canDelete: false,
        notificationLevel: 'ALL',
      };
    }

    const blocked =
      (isGuest && conversation.blocked_by_host) ||
      (isHost && conversation.blocked_by_guest);
    const readOnlyState =
      conversation.messaging_state === 'READ_ONLY' ||
      conversation.messaging_state === 'ARCHIVED' ||
      conversation.messaging_state === 'LOCKED' ||
      Boolean(options.ticketClosed);
    const isReadOnly = readOnlyState || blocked;

    const notificationLevel = isGuest
      ? conversation.notification_level_guest
      : conversation.notification_level_host;

    return {
      canSend: !isReadOnly && !blocked,
      canUpload: !isReadOnly && !blocked,
      canCall: isGuest && !blocked && conversation.messaging_state === 'ACTIVE',
      canReport: !blocked && conversation.type !== 'SUPPORT',
      canBlock: !blocked,
      canReview: isGuest && conversation.messaging_state !== 'LOCKED',
      viewerRole: isGuest ? 'guest' : 'host',
      isReadOnly,
      canArchive: true,
      canDelete: true,
      notificationLevel,
    };
  }

  private denied(): ConversationPermissions {
    return {
      canSend: false,
      canUpload: false,
      canCall: false,
      canReport: false,
      canBlock: false,
      canReview: false,
      viewerRole: 'guest',
      isReadOnly: true,
      canArchive: false,
      canDelete: false,
      notificationLevel: 'ALL',
    };
  }

  isParticipant(
    conversation: StaysConversation,
    userId: string,
    options: MessagingAccessOptions = {},
  ): boolean {
    if (
      conversation.guest_user_id === userId ||
      conversation.host_user_id === userId
    ) {
      return true;
    }
    return Boolean(options.isAdmin) && conversation.type === 'SUPPORT';
  }

  visibilityFor(conversation: StaysConversation, userId: string): string {
    if (conversation.guest_user_id === userId) return conversation.guest_visibility;
    if (conversation.host_user_id === userId) return conversation.host_visibility;
    return 'DELETED';
  }
}

import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysMessage } from './entities/stays-message.entity';

interface RateBucket {
  timestamps: number[];
  bodies: Map<string, number[]>;
}

@Injectable()
export class MessagingRateLimitService {
  private readonly buckets = new Map<string, RateBucket>();
  private readonly perMinute = 10;
  private readonly perDay = 500;
  private readonly identicalPerMinute = 5;

  constructor(
    @InjectRepository(StaysMessage)
    private readonly messageRepo: Repository<StaysMessage>,
  ) {}

  async assertCanSend(
    userId: string,
    conversationId: string,
    body: string,
  ): Promise<void> {
    const key = `${userId}:${conversationId}`;
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { timestamps: [], bodies: new Map() };
      this.buckets.set(key, bucket);
    }

    bucket.timestamps = bucket.timestamps.filter((t) => now - t < 86_400_000);
    const lastMinute = bucket.timestamps.filter((t) => now - t < 60_000);
    if (lastMinute.length >= this.perMinute) {
      throw new HttpException('Rate limit exceeded', HttpStatus.TOO_MANY_REQUESTS);
    }
    if (bucket.timestamps.length >= this.perDay) {
      throw new HttpException('Daily message limit exceeded', HttpStatus.TOO_MANY_REQUESTS);
    }

    const normalized = body.trim().toLowerCase();
    const bodyTimes = bucket.bodies.get(normalized) ?? [];
    const recentBodies = bodyTimes.filter((t) => now - t < 60_000);
    if (recentBodies.length >= this.identicalPerMinute) {
      throw new HttpException('Duplicate message limit exceeded', HttpStatus.TOO_MANY_REQUESTS);
    }
    recentBodies.push(now);
    bucket.bodies.set(normalized, recentBodies);
    bucket.timestamps.push(now);
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysConversation } from './entities/stays-conversation.entity';
import { StaysBooking } from '../stays/entities/stays-booking.entity';
import { StaysListing } from '../stays/entities/stays-listing.entity';
import { TimelineSeederService } from './timeline-seeder.service';
import type { ReservationSnapshot } from './messaging.types';

@Injectable()
export class SnapshotRepairService {
  private readonly logger = new Logger(SnapshotRepairService.name);

  constructor(
    @InjectRepository(StaysConversation)
    private readonly convRepo: Repository<StaysConversation>,
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    private readonly timelineSeeder: TimelineSeederService,
  ) {}

  /** Booking facts only — identity is always live via PresentationService. */
  isSnapshotIncomplete(snapshot: ReservationSnapshot | null | undefined): boolean {
    if (!snapshot?.listingTitle) return true;
    if (!snapshot.listingId) return true;
    if (!snapshot.checkinDate || !snapshot.checkoutDate) return true;
    if (!snapshot.coverMediaId && !snapshot.primaryPhotoUrl) return true;
    return false;
  }

  async repairConversation(conversationId: string): Promise<boolean> {
    const conv = await this.convRepo.findOne({ where: { id: conversationId } });
    if (!conv) return false;

    const current = conv.reservation_snapshot as unknown as ReservationSnapshot;
    if (!this.isSnapshotIncomplete(current)) {
      return false;
    }

    if (!conv.booking_id || !conv.listing_id) {
      this.logger.warn(`Cannot repair conversation ${conversationId}: missing booking/listing`);
      return false;
    }

    const [booking, listing] = await Promise.all([
      this.bookingRepo.findOne({ where: { id: conv.booking_id } }),
      this.listingRepo.findOne({
        where: { id: conv.listing_id },
        relations: ['media'],
      }),
    ]);

    if (!booking || !listing) return false;

    const snapshot = this.timelineSeeder.buildSnapshot(booking, listing);

    conv.reservation_snapshot = snapshot as unknown as StaysConversation['reservation_snapshot'];
    conv.snapshot_version = (conv.snapshot_version ?? 1) + 1;
    await this.convRepo.save(conv);

    this.logger.log(`Repaired booking snapshot for conversation ${conversationId}`);
    return true;
  }
}

