import { Injectable } from '@nestjs/common';
import { DataSource, EntityManager } from 'typeorm';
import { StaysBooking } from '../stays/entities/stays-booking.entity';
import { StaysListing } from '../stays/entities/stays-listing.entity';
import { StaysConversation } from './entities/stays-conversation.entity';
import { StaysMessage, MessageType } from './entities/stays-message.entity';
import type { ReservationSnapshot, TimelineCardMetadata } from './messaging.types';
import { formatInboxPreview } from './message-preview.util';

export interface BuildSnapshotOptions {
  hostDisplayName?: string | null;
  guestDisplayName?: string | null;
}

@Injectable()
export class TimelineSeederService {
  constructor(private readonly dataSource: DataSource) {}

  buildSnapshot(
    booking: StaysBooking,
    listing: StaysListing,
    options?: BuildSnapshotOptions | string | null,
    guestDisplayNameLegacy?: string | null,
  ): ReservationSnapshot {
    const opts: BuildSnapshotOptions =
      typeof options === 'object' && options !== null && !Array.isArray(options)
        ? options
        : {
            hostDisplayName: typeof options === 'string' ? options : null,
            guestDisplayName: guestDisplayNameLegacy ?? null,
          };

    const cover =
      listing.media?.find((m) => m.is_cover && m.kind === 'PHOTO') ??
      listing.media?.find((m) => m.kind === 'PHOTO');

    const addressParts = [
      listing.building_name,
      listing.neighborhood,
      listing.city,
    ].filter(Boolean);

    return {
      listingTitle: listing.title,
      listingId: listing.id,
      coverMediaId: cover?.asset_id ?? null,
      primaryPhotoUrl: cover
        ? `/api/v1/stays/listings/${listing.id}/media/${cover.asset_id}`
        : null,
      addressDisplay: addressParts.join(', ') || listing.city,
      city: listing.city ?? null,
      country: listing.country ?? null,
      checkinDate: String(booking.checkin_date).slice(0, 10),
      checkoutDate: String(booking.checkout_date).slice(0, 10),
      guestCount: booking.guest_count,
      hostDisplayName: opts.hostDisplayName ?? null,
      guestDisplayName: opts.guestDisplayName ?? null,
      bookingReference: booking.booking_reference ?? null,
      listingReference: listing.id,
    };
  }

  async seedBookingConfirmed(
    manager: EntityManager,
    conversation: StaysConversation,
    snapshot: ReservationSnapshot,
    listing: StaysListing,
  ): Promise<StaysMessage[]> {
    const seeds: Array<{ type: MessageType; body: string | null; metadata: Record<string, unknown> }> = [
      {
        type: 'SYSTEM_EVENT',
        body: 'Booking confirmed',
        metadata: {
          source: 'SYSTEM',
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          kind: 'system',
        },
      },
      {
        type: 'BOOKING_CARD',
        body: null,
        metadata: this.bookingCard(snapshot, conversation.booking_id) as unknown as Record<string, unknown>,
      },
      {
        type: 'PROPERTY_CARD',
        body: null,
        metadata: this.propertyCard(snapshot, listing, conversation.booking_id) as unknown as Record<string, unknown>,
      },
    ];

    const contact = listing.check_in_contact;
    if (contact?.access_instructions) {
      seeds.push({
        type: 'CHECKIN_CARD',
        body: null,
        metadata: this.checkinCard(snapshot, contact.access_instructions, conversation.booking_id) as unknown as Record<string, unknown>,
      });
    }
    if (contact?.wifi_ssid) {
      seeds.push({
        type: 'WIFI_CARD',
        body: null,
        metadata: this.wifiCard(contact.wifi_ssid, contact.wifi_password) as unknown as Record<string, unknown>,
      });
    }

    const saved: StaysMessage[] = [];
    for (const seed of seeds) {
      saved.push(await this.insertMessage(manager, conversation, seed));
    }
    return saved;
  }

  /** Post-checkout timeline: archive cue + review prompt in the booking thread. */
  async seedCheckoutComplete(
    manager: EntityManager,
    conversation: StaysConversation,
    booking: StaysBooking,
  ): Promise<StaysMessage[]> {
    const snapshot = conversation.reservation_snapshot as unknown as ReservationSnapshot;
    const listingTitle = snapshot.listingTitle?.trim();
    const reviewBody = listingTitle
      ? `How was your stay at ${listingTitle}?`
      : 'How was your stay?';

    const seeds: Array<{ type: MessageType; body: string | null; metadata: Record<string, unknown> }> = [
      {
        type: 'SYSTEM_EVENT',
        body: 'Checkout complete',
        metadata: {
          source: 'SYSTEM',
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          kind: 'system',
        },
      },
      {
        type: 'REVIEW_CARD',
        body: null,
        metadata: {
          schemaVersion: 1,
          cardVersion: 1,
          presentationVersion: 1,
          kind: 'review',
          title: 'Review your stay',
          body: reviewBody,
          source: 'SYSTEM',
          bookingId: booking.id,
          listingId: snapshot.listingId ?? conversation.listing_id ?? undefined,
          actions: [
            {
              id: 'leave_review',
              label: 'Leave a review',
              type: 'deep_link',
              url: `/bookings/${booking.id}/review`,
            },
          ],
          guestView: {
            title: 'Review your stay',
            body: reviewBody,
            actions: [
              {
                id: 'leave_review',
                label: 'Leave a review',
                type: 'deep_link',
                url: `/bookings/${booking.id}/review`,
              },
            ],
          },
          hostView: {
            title: 'Review request sent',
            body: 'Your guest can leave a review for this stay.',
            actions: [],
          },
        },
      },
    ];

    const saved: StaysMessage[] = [];
    for (const seed of seeds) {
      saved.push(await this.insertMessage(manager, conversation, seed));
    }
    return saved;
  }

  /** Read-only archive notice with support escape hatch. */
  async seedConversationArchived(
    manager: EntityManager,
    conversation: StaysConversation,
    bookingId: string | null,
  ): Promise<StaysMessage> {
    return this.insertMessage(manager, conversation, {
      type: 'SYSTEM_NOTICE',
      body: 'This conversation has been archived.',
      metadata: {
        schemaVersion: 1,
        cardVersion: 1,
        presentationVersion: 1,
        kind: 'archive',
        title: 'Stay completed',
        body: 'This conversation has been archived. Need help with this reservation?',
        source: 'SYSTEM',
        bookingId: bookingId ?? undefined,
        actions: [
          {
            id: 'contact_support',
            label: 'Contact Support',
            type: 'deep_link',
            url: '/contact?safety=1',
          },
          ...(bookingId
            ? [
                {
                  id: 'view_booking',
                  label: 'View reservation',
                  type: 'deep_link',
                  url: `/bookings/${bookingId}`,
                },
              ]
            : []),
        ],
      },
    });
  }

  /** Update review card to thank-you state after guest submits a review. */
  async markReviewCardSubmitted(bookingId: string): Promise<void> {
    const convRepo = this.dataSource.getRepository(StaysConversation);
    const messageRepo = this.dataSource.getRepository(StaysMessage);
    const conv = await convRepo.findOne({ where: { booking_id: bookingId } });
    if (!conv) return;

    const reviewCard = await messageRepo.findOne({
      where: { conversation_id: conv.id, type: 'REVIEW_CARD' },
      order: { conversation_sequence: 'DESC' },
    });
    if (!reviewCard) return;

    const meta = (reviewCard.metadata ?? {}) as Record<string, unknown>;
    if (meta.reviewed === true) return;

    const snapshot = conv.reservation_snapshot as unknown as ReservationSnapshot | null;
    const listingId =
      (meta.listingId as string | undefined) ??
      snapshot?.listingId ??
      conv.listing_id ??
      undefined;
    const viewReviewUrl = listingId
      ? `/listings/${listingId}#reviews`
      : conv.booking_id
        ? `/bookings/${conv.booking_id}`
        : undefined;

    await messageRepo.update(reviewCard.id, {
      metadata: {
        ...meta,
        reviewed: true,
        title: 'Thanks for reviewing!',
        body: 'Your feedback helps future travelers.',
        actions: [],
        guestView: {
          title: 'Thanks for reviewing!',
          body: 'Your feedback helps future travelers.',
          actions: [],
        },
        hostView: {
          title: 'Guest reviewed successfully',
          body: 'Your guest shared feedback about their stay.',
          actions: viewReviewUrl
            ? [
                {
                  id: 'view_review',
                  label: 'View review',
                  type: 'deep_link',
                  url: viewReviewUrl,
                },
              ]
            : [],
        },
      },
    });
    await convRepo.update(conv.id, {
      conversation_version: conv.conversation_version + 1,
    });
  }

  private bookingCard(
    snapshot: ReservationSnapshot,
    bookingId: string | null,
  ): TimelineCardMetadata {
    return {
      schemaVersion: 1,
      cardVersion: 1,
      presentationVersion: 1,
      kind: 'booking',
      title: snapshot.listingTitle,
      body: `${snapshot.checkinDate} – ${snapshot.checkoutDate} · ${snapshot.guestCount} guests`,
      source: 'SYSTEM',
      bookingId: bookingId ?? undefined,
      actions: bookingId
        ? [
            {
              id: 'view_booking',
              label: 'View booking',
              type: 'deep_link',
              url: `/bookings/${bookingId}`,
            },
          ]
        : [],
    };
  }

  private propertyCard(
    snapshot: ReservationSnapshot,
    listing: StaysListing,
    bookingId: string | null,
  ): TimelineCardMetadata {
    const mapsUrl =
      listing.geo_lat != null && listing.geo_lng != null
        ? `https://maps.google.com/?q=${listing.geo_lat},${listing.geo_lng}`
        : undefined;
    return {
      schemaVersion: 1,
      cardVersion: 1,
      presentationVersion: 1,
      kind: 'property',
      title: snapshot.listingTitle,
      body: snapshot.addressDisplay ?? undefined,
      source: 'SYSTEM',
      coverMediaId: snapshot.coverMediaId ?? null,
      listingId: snapshot.listingId ?? listing.id,
      bookingId: bookingId ?? undefined,
      actions: [
        ...(bookingId
          ? [
              {
                id: 'view_booking',
                label: 'View booking',
                type: 'deep_link',
                url: `/bookings/${bookingId}`,
              },
            ]
          : []),
        ...(mapsUrl
          ? [{ id: 'open_maps', label: 'Open in Maps', type: 'external_maps', url: mapsUrl }]
          : []),
      ],
    };
  }

  private checkinCard(
    snapshot: ReservationSnapshot,
    instructions: string,
    bookingId: string | null,
  ): TimelineCardMetadata {
    return {
      schemaVersion: 1,
      cardVersion: 1,
      presentationVersion: 1,
      kind: 'checkin',
      title: 'Check-in details',
      body: instructions,
      source: 'SYSTEM',
      bookingId: bookingId ?? undefined,
      snapshot: { checkInTime: snapshot.checkinDate },
      actions: bookingId
        ? [{ id: 'view_booking', label: 'Directions', type: 'OPEN_BOOKING', url: `/bookings/${bookingId}` }]
        : [],
    };
  }

  private wifiCard(ssid: string, password: string | null): TimelineCardMetadata {
    return {
      schemaVersion: 1,
      cardVersion: 1,
      presentationVersion: 1,
      kind: 'wifi',
      title: 'WiFi',
      body: ssid,
      source: 'SYSTEM',
      snapshot: { ssid, password: password ?? '' },
      actions: password
        ? [{ id: 'copy_wifi', label: 'Copy password', type: 'COPY', value: password }]
        : [],
    };
  }

  async insertMessage(
    manager: EntityManager,
    conversation: StaysConversation,
    input: {
      type: MessageType;
      body: string | null;
      metadata: Record<string, unknown>;
      senderId?: string | null;
      clientMessageId?: string | null;
      senderDisplayName?: string | null;
    },
  ): Promise<StaysMessage> {
    const convRepo = manager.getRepository(StaysConversation);
    const messageRepo = manager.getRepository(StaysMessage);

    const locked = await convRepo
      .createQueryBuilder('c')
      .setLock('pessimistic_write')
      .where('c.id = :id', { id: conversation.id })
      .getOne();
    if (!locked) throw new Error('Conversation not found');

    // The conversation counter is the fast path, but older/partially repaired
    // threads can contain a newer message than the denormalized pointer. Read
    // the actual maximum while holding the conversation write lock so a stale
    // counter self-heals instead of repeatedly violating the sequence unique
    // constraint.
    const maxSequenceRow = await messageRepo
      .createQueryBuilder('m')
      .select('COALESCE(MAX(m.conversation_sequence), 0)', 'maxSequence')
      .where('m.conversation_id = :conversationId', {
        conversationId: locked.id,
      })
      .getRawOne<{ maxSequence: string }>();
    const storedSequence = BigInt(locked.last_message_sequence || 0);
    const actualSequence = BigInt(maxSequenceRow?.maxSequence || 0);
    const nextSeq =
      (storedSequence > actualSequence ? storedSequence : actualSequence) + 1n;
    const now = new Date();
    const isSystem = !input.senderId;

    const message = messageRepo.create({
      conversation_id: locked.id,
      conversation_sequence: String(nextSeq),
      sender_id: input.senderId ?? null,
      type: input.type,
      body: input.body,
      metadata: input.metadata,
      status: 'PERSISTED',
      sent_at: now,
      is_system: isSystem,
      client_message_id: input.clientMessageId ?? null,
    });
    const saved = await messageRepo.save(message);

    const preview = formatInboxPreview({
      type: input.type,
      body: input.body,
      metadata: input.metadata,
      senderLabel: input.senderDisplayName ?? null,
    });
    await convRepo.update(locked.id, {
      last_message_id: saved.id,
      last_message_sequence: String(nextSeq),
      last_message_preview: preview.slice(0, 200),
      last_message_at: now,
      conversation_version: locked.conversation_version + 1,
      updated_at: now,
      ...(input.senderId === locked.guest_user_id
        ? { unread_host: locked.unread_host + 1 }
        : input.senderId === locked.host_user_id
          ? { unread_guest: locked.unread_guest + 1 }
          : {}),
    });

    return saved;
  }
}

import { Injectable, OnModuleInit } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysPlatformSettings } from './stays-platform-settings.entity';

export type FeeRates = {
  guest_fee_pct: number;
  host_fee_pct: number;
  guest_fee_percent: number;
  host_fee_percent: number;
  total_commission_percent: number;
};

export type FeeBreakdown = {
  guestFee: number;
  hostFee: number;
  totalPaid: number;
  payoutAmount: number;
};

function envPct(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw == null || raw === '') return fallback;
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function envTtlMs(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw == null || raw === '') return fallback;
  const n = Number(raw);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

const DEFAULT_GUEST = envPct('STAYS_GUEST_FEE_PCT', 0.05);
const DEFAULT_HOST = envPct('STAYS_HOST_FEE_PCT', 0.05);
/** Display/API cache TTL. Booking money snapshots always read the DB. */
const FEE_CACHE_TTL_MS = envTtlMs('STAYS_FEE_CACHE_TTL_MS', 30_000);

@Injectable()
export class PlatformSettingsService implements OnModuleInit {
  private cached: FeeRates | null = null;
  private cachedAtMs = 0;

  constructor(
    @InjectRepository(StaysPlatformSettings)
    private readonly settingsRepo: Repository<StaysPlatformSettings>,
  ) {}

  async onModuleInit(): Promise<void> {
    await this.ensureRow();
    await this.refreshCache();
  }

  private toRates(guest: number, host: number): FeeRates {
    const guestPct = Number(guest);
    const hostPct = Number(host);
    return {
      guest_fee_pct: guestPct,
      host_fee_pct: hostPct,
      guest_fee_percent: Math.round(guestPct * 1000) / 10,
      host_fee_percent: Math.round(hostPct * 1000) / 10,
      total_commission_percent:
        Math.round((guestPct + hostPct) * 1000) / 10,
    };
  }

  private feesFromRates(
    subtotal: number,
    guest_fee_pct: number,
    host_fee_pct: number,
  ): FeeBreakdown {
    const guestFee = Math.round(subtotal * guest_fee_pct * 100) / 100;
    const hostFee = Math.round(subtotal * host_fee_pct * 100) / 100;
    return {
      guestFee,
      hostFee,
      totalPaid: subtotal + guestFee,
      payoutAmount: subtotal - hostFee,
    };
  }

  private isCacheFresh(): boolean {
    return (
      this.cached != null && Date.now() - this.cachedAtMs < FEE_CACHE_TTL_MS
    );
  }

  private async ensureRow(): Promise<void> {
    const existing = await this.settingsRepo.findOne({ where: { id: 1 } });
    if (existing) return;
    await this.settingsRepo.save(
      this.settingsRepo.create({
        id: 1,
        guest_fee_pct: DEFAULT_GUEST,
        host_fee_pct: DEFAULT_HOST,
      }),
    );
  }

  async refreshCache(): Promise<FeeRates> {
    await this.ensureRow();
    const row = await this.settingsRepo.findOneOrFail({ where: { id: 1 } });
    this.cached = this.toRates(row.guest_fee_pct, row.host_fee_pct);
    this.cachedAtMs = Date.now();
    return this.cached;
  }

  /**
   * Sync convenience for display / unit math.
   * May return briefly stale rates across pods until TTL elapses; never use for
   * booking money snapshots (use calculateFeesAuthoritative).
   */
  getFeeRates(): FeeRates {
    if (this.isCacheFresh()) return this.cached!;
    if (this.cached) return this.cached;
    return this.toRates(DEFAULT_GUEST, DEFAULT_HOST);
  }

  /** Display endpoints: refresh from DB when TTL expired. */
  async getFeeRatesAsync(): Promise<FeeRates> {
    if (this.isCacheFresh()) return this.cached!;
    return this.refreshCache();
  }

  /**
   * Authoritative rates for booking creation — always load from DB so every
   * pod/instance sees admin updates immediately. Snapshot freezes on the booking.
   */
  async getAuthoritativeFeeRates(): Promise<FeeRates> {
    return this.refreshCache();
  }

  calculateFees(subtotal: number): FeeBreakdown {
    const { guest_fee_pct, host_fee_pct } = this.getFeeRates();
    return this.feesFromRates(subtotal, guest_fee_pct, host_fee_pct);
  }

  async calculateFeesAuthoritative(subtotal: number): Promise<FeeBreakdown> {
    const { guest_fee_pct, host_fee_pct } =
      await this.getAuthoritativeFeeRates();
    return this.feesFromRates(subtotal, guest_fee_pct, host_fee_pct);
  }

  async updateFeeRates(
    guestFeePct: number,
    hostFeePct: number,
    updatedBy?: string,
  ): Promise<FeeRates> {
    await this.ensureRow();
    await this.settingsRepo.update(
      { id: 1 },
      {
        guest_fee_pct: guestFeePct,
        host_fee_pct: hostFeePct,
        updated_by: updatedBy ?? null,
      },
    );
    return this.refreshCache();
  }
}

