export interface SeoExploreFilters {
  city?: string;
  listing_type?: string;
  amenity?: string;
  neighborhood?: string;
  pets_allowed?: boolean;
  luxury_only?: boolean;
  family_friendly?: boolean;
  near_lat?: number;
  near_lng?: number;
  near_radius_km?: number;
}

export function propertyTypeBySlug(slug: string): SeoPropertyTypeConfig | null {
  return SEO_PROPERTY_TYPES.find((p) => p.slug === slug) ?? null;
}

export function amenityBySlug(slug: string): SeoAmenityConfig | null {
  return SEO_AMENITIES.find((a) => a.slug === slug) ?? null;
}

export function neighborhoodBySlugs(
  citySlug: string,
  neighborhoodSlug: string,
): SeoNeighborhoodConfig | null {
  return SEO_NEIGHBORHOODS_BY_CITY[citySlug]?.find((n) => n.slug === neighborhoodSlug) ?? null;
}

export function landmarkByUrlSlug(urlSlug: string): SeoLandmarkConfig | null {
  return SEO_LANDMARKS.find((l) => l.urlSlug === urlSlug) ?? null;
}

export function amenityToExploreFilters(amenity: SeoAmenityConfig): SeoExploreFilters {
  switch (amenity.filterKind) {
    case 'amenity':
      return { amenity: amenity.amenityTag ?? amenity.slug };
    case 'pets':
      return { pets_allowed: true };
    case 'family':
      return { family_friendly: true };
    case 'luxury':
      return { luxury_only: true };
    default:
      return {};
  }
}

export function neighborhoodToExploreFilters(
  citySearch: string,
  neighborhood: SeoNeighborhoodConfig,
): SeoExploreFilters {
  return { city: citySearch, neighborhood: neighborhood.searchTerm };
}

export function landmarkToExploreFilters(landmark: SeoLandmarkConfig): SeoExploreFilters {
  return {
    city: landmark.searchCity,
    near_lat: landmark.latitude,
    near_lng: landmark.longitude,
    near_radius_km: landmark.radiusKm,
  };
}

export type ResolvedSeoPage =
  | { kind: 'city'; citySlug: string }
  | { kind: 'property_type'; typeSlug: string }
  | { kind: 'amenity'; amenitySlug: string }
  | { kind: 'city_property_type'; citySlug: string; typeSlug: string }
  | { kind: 'city_amenity'; citySlug: string; amenitySlug: string }
  | { kind: 'city_neighborhood'; citySlug: string; neighborhoodSlug: string }
  | { kind: 'landmark'; landmarkUrlSlug: string };

export function resolveSeoSegments(segments: string[]): ResolvedSeoPage | null {
  const [a, b] = segments.filter(Boolean);
  if (!a) return null;

  if (!b) {
    const lm = landmarkByUrlSlug(a);
    if (lm) return { kind: 'landmark', landmarkUrlSlug: lm.urlSlug };
    const pt = propertyTypeBySlug(a);
    if (pt) return { kind: 'property_type', typeSlug: pt.slug };
    const am = amenityBySlug(a);
    if (am) return { kind: 'amenity', amenitySlug: am.slug };
    return { kind: 'city', citySlug: a };
  }

  const pt = propertyTypeBySlug(b);
  if (pt) return { kind: 'city_property_type', citySlug: a, typeSlug: pt.slug };
  const am = amenityBySlug(b);
  if (am) return { kind: 'city_amenity', citySlug: a, amenitySlug: am.slug };
  const nb = neighborhoodBySlugs(a, b);
  if (nb) return { kind: 'city_neighborhood', citySlug: a, neighborhoodSlug: nb.slug };
  return null;
}

import { Injectable, NotFoundException, BadRequestException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { SeoContentVersion } from './entities/seo-content-version.entity';
import { SeoGuide } from './entities/seo-guide.entity';
import { SeoLandingContent } from './entities/seo-landing-content.entity';
import { SeoPageRegistryService } from './seo-page-registry.service';
import type { SeoContentVersionDto } from './seo.types';

@Injectable()
export class SeoContentCmsService {
  constructor(
    @InjectRepository(SeoContentVersion)
    private readonly versionRepo: Repository<SeoContentVersion>,
    @InjectRepository(SeoGuide)
    private readonly guideRepo: Repository<SeoGuide>,
    @InjectRepository(SeoLandingContent)
    private readonly landingContentRepo: Repository<SeoLandingContent>,
    private readonly registry: SeoPageRegistryService,
  ) {}

  async listDrafts(limit = 50): Promise<SeoContentVersionDto[]> {
    const rows = await this.versionRepo.find({
      where: [{ status: 'draft' }, { status: 'review' }],
      order: { created_at: 'DESC' },
      take: Math.min(limit, 200),
    });
    return rows.map((r) => this.toDto(r));
  }

  async submitForReview(versionId: string): Promise<SeoContentVersionDto> {
    const row = await this.versionRepo.findOne({ where: { id: versionId } });
    if (!row) throw new NotFoundException('Content version not found');
    if (row.status !== 'draft') {
      throw new BadRequestException('Only draft versions can be submitted for review');
    }
    row.status = 'review';
    await this.versionRepo.save(row);
    return this.toDto(row);
  }

  async publish(versionId: string, adminUserId: string): Promise<SeoContentVersionDto> {
    const row = await this.versionRepo.findOne({ where: { id: versionId } });
    if (!row) throw new NotFoundException('Content version not found');
    if (row.status !== 'review' && row.status !== 'draft') {
      throw new BadRequestException('Version must be draft or in review to publish');
    }

    const now = new Date();
    row.status = 'published';
    row.approved_by = adminUserId;
    row.published_at = now;
    await this.versionRepo.save(row);

    if (row.entity_type === 'guide' && row.field_name === 'body_html') {
      const guide = await this.guideRepo.findOne({ where: { id: row.entity_id } });
      if (guide) {
        guide.body_html = row.content_html;
        guide.content_status = 'published';
        guide.published_at = now;
        guide.indexable = (guide.seo_score ?? 0) >= 75;
        await this.guideRepo.save(guide);
        await this.registry.syncPageEntry({
          pageType: 'guide',
          slug: guide.slug,
          locale: guide.locale,
          indexable: guide.indexable,
          seoScore: guide.seo_score,
          lastmod: now,
        });
      }
    }

    if (row.entity_type === 'neighborhood' && row.field_name === 'content_blocks_json') {
      let parsed: Record<string, unknown> = {};
      try {
        parsed = JSON.parse(row.content_html ?? '{}') as Record<string, unknown>;
      } catch {
        throw new BadRequestException('Invalid content_blocks_json payload');
      }
      const existing = await this.landingContentRepo.findOne({
        where: {
          entity_type: 'neighborhood',
          entity_id: row.entity_id,
          locale: row.locale,
        },
      });
      if (existing) {
        existing.content_blocks_json = parsed;
        existing.content_status = 'published';
        existing.updated_at = now;
        await this.landingContentRepo.save(existing);
      } else {
        await this.landingContentRepo.save(
          this.landingContentRepo.create({
            entity_type: 'neighborhood',
            entity_id: row.entity_id,
            locale: row.locale,
            content_blocks_json: parsed,
            content_status: 'published',
          }),
        );
      }
    }

    return this.toDto(row);
  }

  async saveDraft(args: {
    entityType: string;
    entityId: string;
    locale: string;
    fieldName: string;
    contentHtml: string;
    createdBy?: string;
  }): Promise<SeoContentVersionDto> {
    const latest = await this.versionRepo.findOne({
      where: {
        entity_type: args.entityType,
        entity_id: args.entityId,
        locale: args.locale,
        field_name: args.fieldName,
      },
      order: { version: 'DESC' },
    });
    const nextVersion = (latest?.version ?? 0) + 1;
    const row = await this.versionRepo.save(
      this.versionRepo.create({
        entity_type: args.entityType,
        entity_id: args.entityId,
        locale: args.locale,
        version: nextVersion,
        field_name: args.fieldName,
        content_html: args.contentHtml,
        status: 'draft',
        created_by: args.createdBy ?? null,
      }),
    );
    return this.toDto(row);
  }

  private toDto(row: SeoContentVersion): SeoContentVersionDto {
    return {
      id: row.id,
      entityType: row.entity_type,
      entityId: row.entity_id,
      locale: row.locale,
      version: row.version,
      fieldName: row.field_name,
      status: row.status,
      createdAt: row.created_at.toISOString(),
      publishedAt: row.published_at?.toISOString() ?? null,
    };
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { SeoGuide } from './entities/seo-guide.entity';
import { SeoDestination } from './entities/seo-destination.entity';
import { DestinationIntelligenceService } from './destination-intelligence.service';
import { SeoContentCmsService } from './seo-content-cms.service';
import type { GeoBlockDto } from './seo.types';
import type { DestinationIntelligence } from './seo.types';

@Injectable()
export class SeoContentPipelineService {
  constructor(
    @InjectRepository(SeoGuide)
    private readonly guideRepo: Repository<SeoGuide>,
    @InjectRepository(SeoDestination)
    private readonly destinationRepo: Repository<SeoDestination>,
    private readonly intelligence: DestinationIntelligenceService,
    private readonly cms: SeoContentCmsService,
  ) {}

  /** Generate an AI-style draft from live marketplace data + templates. */
  async generateGuideDraft(guideId: string, adminUserId?: string): Promise<{ draftId: string }> {
    const guide = await this.guideRepo.findOne({
      where: { id: guideId },
      relations: ['destination'],
    });
    if (!guide) throw new NotFoundException('Guide not found');

    const dest = guide.destination_id
      ? await this.destinationRepo.findOne({ where: { id: guide.destination_id } })
      : null;

    let intel: DestinationIntelligence | null = null;
    if (dest) {
      intel = await this.intelligence.compute({ city: dest.search_city });
    }

    const blocks: GeoBlockDto[] = [];
    if (intel && intel.listingCount > 0) {
      blocks.push({
        question: `How many verified stays in ${dest?.name ?? 'Morocco'}?`,
        answer: `${intel.listingCount} live listings on Nexa Stays (${intel.verifiedCount} with verified walkthrough).`,
        statKey: 'listingCount',
      });
      if (intel.avgNightlyPrice != null) {
        blocks.push({
          question: 'Average nightly price?',
          answer: `Around ${intel.avgNightlyPrice} ${intel.currency}/night based on live listings.`,
          statKey: 'avgNightlyPrice',
        });
      }
    }

    const title = dest?.name ?? 'Morocco';
    const html = this.buildDraftHtml(guide.guide_type, title, dest, intel, blocks);

    const draft = await this.cms.saveDraft({
      entityType: 'guide',
      entityId: guide.id,
      locale: guide.locale,
      fieldName: 'body_html',
      contentHtml: html,
      createdBy: adminUserId,
    });

    return { draftId: draft.id };
  }

  private buildDraftHtml(
    guideType: string,
    title: string,
    dest: SeoDestination | null,
    intel: Awaited<ReturnType<DestinationIntelligenceService['compute']>> | null,
    blocks: GeoBlockDto[],
  ): string {
    const intro =
      guideType === 'seasonal'
        ? `<p>Planning when to visit ${title}? This draft was generated from Nexa Stays marketplace data.</p>`
        : guideType === 'experience'
          ? `<p>Discover top experiences in ${title}. Use verified stays as your base while exploring.</p>`
          : guideType === 'event'
            ? `<p>Travel tips for special periods in Morocco. Confirm dining and check-in details with your host.</p>`
            : `<p>Your complete travel guide to ${title} — neighborhoods, pricing, and verified stays on Nexa Stays.</p>`;

    const stats =
      intel && intel.listingCount > 0
        ? `<p><strong>Live marketplace snapshot:</strong> ${intel.listingCount} listings` +
          (intel.avgNightlyPrice != null
            ? `, average ${intel.avgNightlyPrice} ${intel.currency}/night`
            : '') +
          '.</p>'
        : '';

    const faq =
      blocks.length > 0
        ? `<h2>Common questions</h2><ul>${blocks.map((b) => `<li><strong>${b.question}</strong> ${b.answer}</li>`).join('')}</ul>`
        : '';

    const bestTime = dest?.best_time_to_visit
      ? `<p><strong>Best time to visit:</strong> ${dest.best_time_to_visit}</p>`
      : '';

    return `${intro}${stats}${bestTime}${faq}<p><em>Draft — review before publishing.</em></p>`;
  }
}

