import { computeSeoQualityScore, isPageIndexable } from './seo-quality-scoring.service';
import { SeoKnowledgeGraphService } from './seo-knowledge-graph.service';
import { SeoLandingContentService } from './seo-landing-content.service';
import { SeoGuideService } from './seo-guide.service';
import type { SeoLandingContentBlocks } from './seo-landing-content.types';
import type {
  AiContextPayload,
  AiSnippet,
  GeoBlockDto,
  RelatedDestinationDto,
  SeoDestinationDto,
  SeoExploreFiltersDto,
  SeoLandmarkDto,
  SeoLocale,
  SeoNeighborhoodDto,
  SeoGuideSummaryDto,
  SeoPagePayload,
  SeoPageType,
} from './seo.types';

const LOCALES: SeoLocale[] = ['en', 'fr', 'ar'];

@Injectable()
export class SeoEngineService {
  constructor(
    @InjectRepository(SeoDestination)
    private readonly destinationRepo: Repository<SeoDestination>,
    @InjectRepository(SeoPageRegistry)
    private readonly registryRepo: Repository<SeoPageRegistry>,
    private readonly intelligence: DestinationIntelligenceService,
    private readonly knowledgeGraph: SeoKnowledgeGraphService,
    private readonly landingContent: SeoLandingContentService,
    private readonly guideService: SeoGuideService,
  ) {}

  async listDestinations(): Promise<SeoDestinationDto[]> {
    const rows = await this.destinationRepo.find({
      where: { content_status: 'published' },
      order: { name: 'ASC' },
    });
    return rows.map((d) => this.toDestinationDto(d));
  }

  async getDestinationBySlug(slug: string): Promise<SeoDestination> {
    const dest = await this.destinationRepo.findOne({ where: { slug } });
    if (!dest || dest.content_status !== 'published') {
      throw new NotFoundException('Destination not found');
    }
    return dest;
  }

  async getRelatedDestinations(citySlug: string) {
    return this.knowledgeGraph.getRelatedBySlug(citySlug);
  }

  async generateCityPage(slug: string, locale: SeoLocale): Promise<SeoPagePayload> {
    return this.resolveAndGenerate([slug], locale);
  }

  async resolveAndGenerate(
    segments: string[],
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const resolved = resolveSeoSegments(segments);
    if (!resolved) throw new NotFoundException('Page not found');
    return this.generateResolved(resolved, locale);
  }

  async generateResolved(
    resolved: ResolvedSeoPage,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    switch (resolved.kind) {
      case 'city':
        return this.buildCityPage(resolved.citySlug, locale);
      case 'property_type':
        return this.buildGlobalPropertyType(resolved.typeSlug, locale);
      case 'amenity':
        return this.buildGlobalAmenity(resolved.amenitySlug, locale);
      case 'city_property_type':
        return this.buildCityPropertyType(
          resolved.citySlug,
          resolved.typeSlug,
          locale,
        );
      case 'city_amenity':
        return this.buildCityAmenity(
          resolved.citySlug,
          resolved.amenitySlug,
          locale,
        );
      case 'city_neighborhood':
        return this.buildCityNeighborhood(
          resolved.citySlug,
          resolved.neighborhoodSlug,
          locale,
        );
      case 'landmark':
        return this.buildLandmark(resolved.landmarkUrlSlug, locale);
      default:
        throw new NotFoundException('Page not found');
    }
  }

  async buildAiContextForPath(
    segments: string[],
    locale: SeoLocale,
    siteUrl: string,
  ): Promise<AiContextPayload> {
    const page = await this.resolveAndGenerate(segments, locale);
    const geoBlocks = page.geoBlocks;
    const summary =
      page.intelligence.listingCount > 0
        ? `${page.h1}: ${page.intelligence.listingCount} verified stays on Nexa Stays` +
          (page.intelligence.avgNightlyPrice != null
            ? `, average ${page.intelligence.avgNightlyPrice} ${page.intelligence.currency}/night.`
            : '.')
        : `${page.h1} on Nexa Stays — verified stays in Morocco.`;

    return {
      pageType: page.pageType,
      destination: page.destination?.name ?? null,
      country: 'Morocco',
      summary,
      listingCount: page.intelligence.listingCount,
      verifiedCount: page.intelligence.verifiedCount,
      averagePrice: page.intelligence.avgNightlyPrice,
      minPrice: page.intelligence.minPrice,
      currency: page.intelligence.currency,
      averageRating: page.intelligence.avgRating,
      bestArea: page.intelligence.topNeighborhood,
      familyArea: page.destination
        ? this.areaHint(page.destination.slug, 'family')
        : null,
      nightlifeArea: page.destination
        ? this.areaHint(page.destination.slug, 'nightlife')
        : null,
      couplesArea: page.destination
        ? this.areaHint(page.destination.slug, 'couples')
        : null,
      nomadArea: page.destination
        ? this.areaHint(page.destination.slug, 'nomads')
        : null,
      topAmenities: page.intelligence.topAmenities,
      bestMonth: page.destination?.bestTimeToVisit?.split(';')[0]?.trim() ?? null,
      safety: geoBlocks.find((b) => b.question.toLowerCase().includes('safe'))?.answer ?? null,
      transport: null,
      snippets: page.aiSnippets,
      canonicalUrl: `${siteUrl.replace(/\/$/, '')}${page.canonical}`,
      lastUpdated: page.lastmod,
    };
  }

  /** @deprecated use buildAiContextForPath */
  async buildAiContext(
    slug: string,
    locale: SeoLocale,
    siteUrl: string,
  ): Promise<AiContextPayload> {
    return this.buildAiContextForPath([slug], locale, siteUrl);
  }

  private async buildCityPage(
    citySlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const dest = await this.getDestinationBySlug(citySlug);
    const exploreFilters: SeoExploreFilters = { city: dest.search_city };
    return this.assemblePage({
      pageType: 'city',
      locale,
      registrySlug: dest.slug,
      pathSuffix: dest.slug,
      dest,
      neighborhood: null,
      landmark: null,
      filterLabel: null,
      exploreFilters,
      title: `Stays in ${dest.name} | Hotels, Riads & Apartments | Nexa Stays`,
      description: `Discover hotels, riads, apartments and villas in ${dest.name}. Compare verified listings and book securely with Nexa Stays.`,
      h1: `Stays in ${dest.name}`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Stays', path: `/${locale}/stays` },
        { name: dest.name, path: p },
      ],
    });
  }

  private async buildGlobalPropertyType(
    typeSlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const pt = propertyTypeBySlug(typeSlug);
    if (!pt) throw new NotFoundException('Property type not found');
    const exploreFilters: SeoExploreFilters = {
      listing_type: pt.listingType,
    };
    return this.assemblePage({
      pageType: 'property_type',
      locale,
      registrySlug: pt.slug,
      pathSuffix: pt.slug,
      dest: null,
      neighborhood: null,
      landmark: null,
      filterLabel: pt.pluralLabel,
      exploreFilters,
      title: `${pt.pluralLabel} in Morocco | Nexa Stays`,
      description: `Browse verified ${pt.pluralLabel.toLowerCase()} across Morocco. Transparent fees and identity-checked hosts on Nexa Stays.`,
      h1: `${pt.pluralLabel} in Morocco`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Stays', path: `/${locale}/stays` },
        { name: pt.pluralLabel, path: p },
      ],
    });
  }

  private async buildGlobalAmenity(
    amenitySlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const am = amenityBySlug(amenitySlug);
    if (!am) throw new NotFoundException('Amenity not found');
    const exploreFilters: SeoExploreFilters = amenityToExploreFilters(am);
    return this.assemblePage({
      pageType: 'amenity',
      locale,
      registrySlug: am.slug,
      pathSuffix: am.slug,
      dest: null,
      neighborhood: null,
      landmark: null,
      filterLabel: am.label,
      exploreFilters,
      title: `${am.label} Stays in Morocco | Nexa Stays`,
      description: `Find ${am.label.toLowerCase()} stays across Morocco on Nexa Stays. Verified listings with clear pricing.`,
      h1: `${am.label} stays in Morocco`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Stays', path: `/${locale}/stays` },
        { name: am.label, path: p },
      ],
    });
  }

  private async buildCityPropertyType(
    citySlug: string,
    typeSlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const dest = await this.getDestinationBySlug(citySlug);
    const pt = propertyTypeBySlug(typeSlug);
    if (!pt) throw new NotFoundException('Property type not found');
    const exploreFilters: SeoExploreFilters = {
      city: dest.search_city,
      listing_type: pt.listingType,
    };
    return this.assemblePage({
      pageType: 'city_property_type',
      locale,
      registrySlug: `${dest.slug}/${pt.slug}`,
      pathSuffix: `${dest.slug}/${pt.slug}`,
      dest,
      neighborhood: null,
      landmark: null,
      filterLabel: pt.pluralLabel,
      exploreFilters,
      title: `${pt.pluralLabel} in ${dest.name} | Nexa Stays`,
      description: `Browse ${pt.pluralLabel.toLowerCase()} in ${dest.name}. Verified listings on Nexa Stays.`,
      h1: `${pt.pluralLabel} in ${dest.name}`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Stays', path: `/${locale}/stays` },
        { name: dest.name, path: `/${locale}/stays/${dest.slug}` },
        { name: pt.pluralLabel, path: p },
      ],
    });
  }

  private async buildCityAmenity(
    citySlug: string,
    amenitySlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const dest = await this.getDestinationBySlug(citySlug);
    const am = amenityBySlug(amenitySlug);
    if (!am) throw new NotFoundException('Amenity not found');
    const exploreFilters: SeoExploreFilters = {
      city: dest.search_city,
      ...amenityToExploreFilters(am),
    };
    return this.assemblePage({
      pageType: 'city_amenity',
      locale,
      registrySlug: `${dest.slug}/${am.slug}`,
      pathSuffix: `${dest.slug}/${am.slug}`,
      dest,
      neighborhood: null,
      landmark: null,
      filterLabel: am.label,
      exploreFilters,
      title: `${am.label} Stays in ${dest.name} | Nexa Stays`,
      description: `Find ${am.label.toLowerCase()} stays in ${dest.name} on Nexa Stays.`,
      h1: `${am.label} stays in ${dest.name}`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Stays', path: `/${locale}/stays` },
        { name: dest.name, path: `/${locale}/stays/${dest.slug}` },
        { name: am.label, path: p },
      ],
    });
  }

  private async buildCityNeighborhood(
    citySlug: string,
    neighborhoodSlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const dest = await this.getDestinationBySlug(citySlug);
    const nb = neighborhoodBySlugs(citySlug, neighborhoodSlug);
    if (!nb) throw new NotFoundException('Neighborhood not found');
    const exploreFilters = neighborhoodToExploreFilters(dest.search_city, nb);
    const neighborhoodDto: SeoNeighborhoodDto = {
      slug: nb.slug,
      name: nb.name,
      searchTerm: nb.searchTerm,
    };
    const nbRow = await this.landingContent.findNeighborhoodId(citySlug, neighborhoodSlug);
    let contentBlocks: SeoLandingContentBlocks | null = null;
    if (nbRow) {
      contentBlocks = await this.landingContent.loadPublishedBlocks(
        'neighborhood',
        nbRow.id,
        locale,
      );
    }
    const relatedGuides = await this.guideService.listGuides(locale);
    const cityGuideLink = {
      slug: `${dest.slug}-travel-guide`,
      href: `/${locale}/guides/${dest.slug}-travel-guide`,
      label: `${dest.name} travel guide`,
    };
    return this.assemblePage({
      pageType: 'city_neighborhood',
      locale,
      registrySlug: `${dest.slug}/${nb.slug}`,
      pathSuffix: `${dest.slug}/${nb.slug}`,
      dest,
      neighborhood: neighborhoodDto,
      landmark: null,
      filterLabel: nb.name,
      exploreFilters,
      contentBlocks,
      cityGuideLink,
      relatedGuides: relatedGuides.filter((g) => g.destinationSlug === dest.slug).slice(0, 6),
      title: `Stays in ${nb.name}, ${dest.name} | Nexa Stays`,
      description: `Browse verified stays in ${nb.name}, ${dest.name}. Compare prices and book securely on Nexa Stays.`,
      h1: `Stays in ${nb.name}, ${dest.name}`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Morocco Stays', path: `/${locale}/stays` },
        { name: dest.name, path: `/${locale}/stays/${dest.slug}` },
        { name: nb.name, path: p },
      ],
    });
  }

  private async buildLandmark(
    landmarkUrlSlug: string,
    locale: SeoLocale,
  ): Promise<SeoPagePayload> {
    const lm = landmarkByUrlSlug(landmarkUrlSlug);
    if (!lm) throw new NotFoundException('Landmark not found');
    const dest = lm.citySlug
      ? await this.destinationRepo.findOne({
          where: { slug: lm.citySlug, content_status: 'published' },
        })
      : null;
    const exploreFilters = landmarkToExploreFilters(lm);
    const landmarkDto: SeoLandmarkDto = {
      slug: lm.slug,
      urlSlug: lm.urlSlug,
      name: lm.name,
      citySlug: lm.citySlug,
      searchCity: lm.searchCity,
      latitude: lm.latitude,
      longitude: lm.longitude,
      radiusKm: lm.radiusKm,
    };
    return this.assemblePage({
      pageType: 'landmark',
      locale,
      registrySlug: lm.urlSlug,
      pathSuffix: lm.urlSlug,
      dest,
      neighborhood: null,
      landmark: landmarkDto,
      filterLabel: lm.name,
      exploreFilters,
      title: `Stays near ${lm.name} | Nexa Stays`,
      description: `Find verified stays near ${lm.name} in ${lm.searchCity}. Book with transparent pricing on Nexa Stays.`,
      h1: `Stays near ${lm.name}`,
      breadcrumbs: (p) => [
        { name: 'Home', path: `/${locale}` },
        { name: 'Stays', path: `/${locale}/stays` },
        ...(dest
          ? [{ name: dest.name, path: `/${locale}/stays/${dest.slug}` }]
          : []),
        { name: lm.name, path: p },
      ],
    });
  }

  private async assemblePage(args: {
    pageType: SeoPageType;
    locale: SeoLocale;
    registrySlug: string;
    pathSuffix: string;
    dest: SeoDestination | null;
    neighborhood: SeoNeighborhoodDto | null;
    landmark: SeoLandmarkDto | null;
    filterLabel: string | null;
    exploreFilters: SeoExploreFilters;
    contentBlocks?: SeoLandingContentBlocks | null;
    cityGuideLink?: { slug: string; href: string; label: string } | null;
    relatedGuides?: SeoGuideSummaryDto[];
    title: string;
    description: string;
    h1: string;
    breadcrumbs: (path: string) => { name: string; path: string }[];
  }): Promise<SeoPagePayload> {
    const path = `/${args.locale}/stays/${args.pathSuffix}`;
    const intel = await this.intelligence.compute(args.exploreFilters);
    const seoScore = computeSeoQualityScore({
      intelligence: intel,
      destination: args.dest,
    });
    const registryRow = await this.registryRepo.findOne({
      where: {
        page_type: args.pageType,
        slug: args.registrySlug,
        locale: args.locale,
      },
    });
    const indexable =
      registryRow?.indexable ??
      isPageIndexable({ seoScore, listingCount: intel.listingCount });

    const destDto = args.dest ? this.toDestinationDto(args.dest) : null;
    const nearby = args.dest
      ? await this.knowledgeGraph.getRelatedWithFallback(args.dest, (d) =>
          this.toDestinationDto(d),
        )
      : [];
    const relatedDestinations: RelatedDestinationDto[] = args.dest
      ? (await this.knowledgeGraph.getRelatedDestinations(args.dest.id, 6)).map(
          (r) => ({ ...r, href: `/${args.locale}${r.href}` }),
        )
      : [];

    const dynamicGeoBlocks = this.buildGeoBlocks(args.h1, args.dest, intel, args.landmark);
    const editorialFaq = (args.contentBlocks?.faq ?? []).map((item) => ({
      question: item.question,
      answer: item.answer,
    }));
    const faq = [...editorialFaq, ...dynamicGeoBlocks];
    const aiSnippets = this.buildAiSnippets(args.h1, intel, args.contentBlocks);

    const priceSuffix =
      intel.avgNightlyPrice != null
        ? ` From ${intel.avgNightlyPrice} ${intel.currency}/night.`
        : '';
    const description = `${args.description}${priceSuffix}`;

    return {
      pageType: args.pageType,
      locale: args.locale,
      path,
      title: args.title,
      description,
      h1: args.h1,
      canonical: path,
      hreflang: Object.fromEntries(
        LOCALES.map((loc) => [loc, `/${loc}/stays/${args.pathSuffix}`]),
      ),
      robots: indexable ? 'index,follow' : 'noindex,follow',
      destination: destDto,
      neighborhood: args.neighborhood,
      landmark: args.landmark,
      filterLabel: args.filterLabel,
      exploreFilters: args.exploreFilters as SeoExploreFiltersDto,
      intelligence: intel,
      geoBlocks: dynamicGeoBlocks,
      faq,
      aiSnippets,
      nearbyDestinations: nearby,
      relatedDestinations,
      contentBlocks: args.contentBlocks ?? undefined,
      cityGuideLink: args.cityGuideLink ?? null,
      relatedGuides: args.relatedGuides ?? [],
      propertyTypeLinks: destDto
        ? SEO_PROPERTY_TYPES.map((pt) => ({
            slug: pt.slug,
            label: `${pt.pluralLabel} in ${destDto.name}`,
            href: `/${args.locale}/stays/${destDto.slug}/${pt.slug}`,
          }))
        : [],
      amenityLinks: destDto
        ? SEO_AMENITIES.map((am) => ({
            slug: am.slug,
            label: `${am.label} in ${destDto.name}`,
            href: `/${args.locale}/stays/${destDto.slug}/${am.slug}`,
          }))
        : [],
      neighborhoodLinks: destDto
        ? (SEO_NEIGHBORHOODS_BY_CITY[destDto.slug] ?? []).map((nb) => ({
            slug: nb.slug,
            label: `${nb.name}, ${destDto.name}`,
            href: `/${args.locale}/stays/${destDto.slug}/${nb.slug}`,
          }))
        : [],
      breadcrumbs: args.breadcrumbs(path),
      indexable,
      seoScore: registryRow?.seo_score ?? seoScore,
      lastmod: registryRow?.lastmod?.toISOString() ?? new Date().toISOString(),
      registrySlug: args.registrySlug,
    };
  }

  private buildGeoBlocks(
    h1: string,
    dest: SeoDestination | null,
    intel: SeoPagePayload['intelligence'],
    landmark: SeoLandmarkDto | null = null,
  ): GeoBlockDto[] {
    const blocks: GeoBlockDto[] = [];
    if (intel.avgNightlyPrice != null) {
      blocks.push({
        question: `Average price for ${h1}?`,
        answer: `Around ${intel.avgNightlyPrice} ${intel.currency}/night based on live Nexa Stays listings.`,
        statKey: 'avgNightlyPrice',
      });
    }
    if (intel.listingCount > 0) {
      blocks.push({
        question: `How many listings match ${h1}?`,
        answer: `${intel.listingCount} live listings (${intel.verifiedCount} with verified walkthrough).`,
        statKey: 'listingCount',
      });
    }
    if (dest) {
      blocks.push({
        question: `Is ${dest.name} safe for tourists?`,
        answer: `Yes. Popular tourist districts in ${dest.name} are generally safe when using verified stays.`,
      });
      if (dest.best_time_to_visit) {
        blocks.push({
          question: `Best time to visit ${dest.name}?`,
          answer: dest.best_time_to_visit,
        });
      }
    }
    if (landmark) {
      blocks.push({
        question: `How close are stays to ${landmark.name}?`,
        answer: `Listings shown are within about ${landmark.radiusKm} km of ${landmark.name} in ${landmark.searchCity}.`,
      });
    }
    return blocks;
  }

  private buildAiSnippets(
    label: string,
    intel: SeoPagePayload['intelligence'],
    contentBlocks?: SeoLandingContentBlocks | null,
  ): AiSnippet[] {
    const snippets: AiSnippet[] = [];
    const intro = contentBlocks?.hero_intro ?? contentBlocks?.why_stay_here;
    if (intro) {
      snippets.push({
        type: 'summary',
        content: intro.slice(0, 320),
        confidence: 0.95,
        source: 'editorial',
      });
    } else if (intel.listingCount > 0) {
      snippets.push({
        type: 'summary',
        content: `${label}: ${intel.listingCount} verified stays on Nexa Stays.`,
        confidence: 1,
        source: 'marketplace',
      });
    }
    if (contentBlocks?.quick_facts?.atmosphere) {
      snippets.push({
        type: 'summary',
        content: `Atmosphere: ${contentBlocks.quick_facts.atmosphere}. Budget: ${contentBlocks.quick_facts.budget ?? 'Varies'}.`,
        confidence: 0.9,
        source: 'editorial',
      });
    }
    if (intel.avgNightlyPrice != null) {
      snippets.push({
        type: 'price',
        content: `Average nightly price is about ${intel.avgNightlyPrice} ${intel.currency}.`,
        confidence: 1,
        source: 'marketplace',
      });
    }
    return snippets;
  }

  private areaHint(
    slug: string,
    kind: 'family' | 'nightlife' | 'couples' | 'nomads',
  ): string | null {
    const hints: Record<string, Partial<Record<typeof kind, string>>> = {
      marrakech: { family: 'Palmeraie', nightlife: 'Gueliz', couples: 'Hivernage', nomads: 'Gueliz' },
      casablanca: { family: 'Anfa', nightlife: 'Maarif', couples: 'Ain Diab', nomads: 'Maarif' },
      agadir: { family: 'Founty', nightlife: 'Marina', couples: 'Talborjt', nomads: 'Marina' },
      rabat: { family: 'Agdal', nightlife: 'Agdal', couples: 'Hassan', nomads: 'Agdal' },
      fes: { family: 'Zouagha', nightlife: 'Ville Nouvelle', couples: 'Medina', nomads: 'Ville Nouvelle' },
      tangier: { family: 'Malabata', nightlife: 'City Center', couples: 'Kasbah', nomads: 'City Center' },
    };
    return hints[slug]?.[kind] ?? null;
  }

  private async loadNearby(slugs: string[]): Promise<SeoDestinationDto[]> {
    if (!slugs.length) return [];
    const rows = await this.destinationRepo.find({
      where: { slug: In(slugs), content_status: 'published' },
    });
    const bySlug = new Map(rows.map((r) => [r.slug, r]));
    return slugs.map((s) => bySlug.get(s)).filter(Boolean).map((d) => this.toDestinationDto(d!));
  }

  private toDestinationDto(d: SeoDestination): SeoDestinationDto {
    return {
      id: d.id,
      slug: d.slug,
      name: d.name,
      countryCode: d.country_code,
      regionId: d.region_id,
      latitude: d.latitude != null ? Number(d.latitude) : null,
      longitude: d.longitude != null ? Number(d.longitude) : null,
      heroImageUrl: d.hero_image_url,
      bestTimeToVisit: this.normalizeBestTime(d.best_time_to_visit),
      nearbyCitySlugs: d.nearby_city_slugs ?? [],
      searchCity: d.search_city,
      indexable: d.indexable,
      seoScore: d.seo_score,
      listingCountCache: d.listing_count_cache,
    };
  }

  private normalizeBestTime(value: string | null | undefined): string | null {
    if (!value) return null;
    return value.replace(/\?/g, '–').replace(/;/g, ' · ');
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Cron, CronExpression } from '@nestjs/schedule';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { SeoDestination } from './entities/seo-destination.entity';
import { SeoPageRegistry } from './entities/seo-page-registry.entity';
import { DestinationIntelligenceService } from './destination-intelligence.service';
import { SeoPageRegistryService } from './seo-page-registry.service';
import {
  SEO_AMENITIES,
  SEO_LANDMARKS,
  SEO_NEIGHBORHOODS_BY_CITY,
  SEO_PROPERTY_TYPES,
  amenityToExploreFilters,
  landmarkToExploreFilters,
  neighborhoodToExploreFilters,
} from './seo-catalog';
import { computeSeoQualityScore, isPageIndexable } from './seo-quality-scoring.service';

@Injectable()
export class SeoFreshnessEngineService {
  private readonly logger = new Logger(SeoFreshnessEngineService.name);

  constructor(
    @InjectRepository(SeoDestination)
    private readonly destinationRepo: Repository<SeoDestination>,
    @InjectRepository(SeoPageRegistry)
    private readonly registryRepo: Repository<SeoPageRegistry>,
    private readonly intelligence: DestinationIntelligenceService,
    private readonly registry: SeoPageRegistryService,
  ) {}

  @Cron(CronExpression.EVERY_DAY_AT_3AM)
  async refreshAllDestinations(): Promise<void> {
    await this.runRefresh();
  }

  @Cron(CronExpression.EVERY_HOUR)
  async refreshHourlyLight(): Promise<void> {
    if (process.env.SEO_FRESHNESS_HOURLY !== 'true') return;
    await this.runRefresh();
  }

  async runOnStartup(): Promise<void> {
    if (process.env.SEO_FRESHNESS_SYNC_ON_STARTUP === 'true') {
      await this.runRefresh();
    }
  }

  /** Refresh stats for a city when listings change. */
  async refreshForSearchCity(searchCity: string): Promise<void> {
    const dest = await this.destinationRepo.findOne({
      where: { search_city: searchCity, content_status: 'published' },
    });
    if (!dest) return;
    await this.refreshDestinationBundle(dest);
  }

  async runRefresh(): Promise<void> {
    const destinations = await this.destinationRepo.find({
      where: { content_status: 'published' },
    });
    const now = new Date();

    for (const dest of destinations) {
      try {
        await this.refreshDestinationBundle(dest, now);
      } catch (err) {
        this.logger.warn(
          `SEO freshness failed for ${dest.slug}: ${err instanceof Error ? err.message : err}`,
        );
      }
    }

    for (const pt of SEO_PROPERTY_TYPES) {
      try {
        const intel = await this.intelligence.compute({
          listing_type: pt.listingType,
        });
        const score = computeSeoQualityScore({ intelligence: intel });
        const indexable = isPageIndexable({
          seoScore: score,
          listingCount: intel.listingCount,
        });
        await this.registry.syncPageAllLocales({
          pageType: 'property_type',
          slug: pt.slug,
          indexable,
          seoScore: score,
          lastmod: now,
        });
      } catch (err) {
        this.logger.warn(`SEO freshness property_type ${pt.slug}: ${err}`);
      }
    }

    for (const am of SEO_AMENITIES) {
      try {
        const intel = await this.intelligence.compute(amenityToExploreFilters(am));
        const score = computeSeoQualityScore({ intelligence: intel });
        const indexable = isPageIndexable({
          seoScore: score,
          listingCount: intel.listingCount,
        });
        await this.registry.syncPageAllLocales({
          pageType: 'amenity',
          slug: am.slug,
          indexable,
          seoScore: score,
          lastmod: now,
        });
      } catch (err) {
        this.logger.warn(`SEO freshness amenity ${am.slug}: ${err}`);
      }
    }

    for (const lm of SEO_LANDMARKS) {
      try {
        const intel = await this.intelligence.compute(landmarkToExploreFilters(lm));
        const score = computeSeoQualityScore({ intelligence: intel });
        const indexable = isPageIndexable({
          seoScore: score,
          listingCount: intel.listingCount,
        });
        await this.registry.syncPageAllLocales({
          pageType: 'landmark',
          slug: lm.urlSlug,
          indexable,
          seoScore: score,
          lastmod: now,
        });
      } catch (err) {
        this.logger.warn(`SEO freshness landmark ${lm.urlSlug}: ${err}`);
      }
    }

    this.logger.log(
      `SEO freshness refreshed ${destinations.length} destinations + combos + landmarks`,
    );
  }

  private async refreshDestinationBundle(
    dest: SeoDestination,
    now: Date = new Date(),
  ): Promise<void> {
    const cityIntel = await this.intelligence.compute({ city: dest.search_city });
    const cityScore = computeSeoQualityScore({
      intelligence: cityIntel,
      destination: dest,
    });
    const cityIndexable = isPageIndexable({
      seoScore: cityScore,
      listingCount: cityIntel.listingCount,
    });

    await this.destinationRepo.update(dest.id, {
      stats_cache_json: JSON.parse(JSON.stringify(cityIntel)),
      stats_refreshed_at: now,
      listing_count_cache: cityIntel.listingCount,
      seo_score: cityScore,
      indexable: cityIndexable,
    });

    await this.registry.syncPageAllLocales({
      pageType: 'city',
      slug: dest.slug,
      indexable: cityIndexable,
      seoScore: cityScore,
      lastmod: now,
    });

    for (const pt of SEO_PROPERTY_TYPES) {
      const intel = await this.intelligence.compute({
        city: dest.search_city,
        listing_type: pt.listingType,
      });
      const score = computeSeoQualityScore({
        intelligence: intel,
        destination: dest,
      });
      const indexable = isPageIndexable({
        seoScore: score,
        listingCount: intel.listingCount,
      });
      await this.registry.syncPageAllLocales({
        pageType: 'city_property_type',
        slug: `${dest.slug}/${pt.slug}`,
        indexable,
        seoScore: score,
        lastmod: now,
      });
    }

    for (const am of SEO_AMENITIES) {
      const intel = await this.intelligence.compute({
        city: dest.search_city,
        ...amenityToExploreFilters(am),
      });
      const score = computeSeoQualityScore({
        intelligence: intel,
        destination: dest,
      });
      const indexable = isPageIndexable({
        seoScore: score,
        listingCount: intel.listingCount,
      });
      await this.registry.syncPageAllLocales({
        pageType: 'city_amenity',
        slug: `${dest.slug}/${am.slug}`,
        indexable,
        seoScore: score,
        lastmod: now,
      });
    }

    const neighborhoods = SEO_NEIGHBORHOODS_BY_CITY[dest.slug] ?? [];
    for (const nb of neighborhoods) {
      const intel = await this.intelligence.compute(
        neighborhoodToExploreFilters(dest.search_city, nb),
      );
      const score = computeSeoQualityScore({
        intelligence: intel,
        destination: dest,
      });
      const indexable = isPageIndexable({
        seoScore: score,
        listingCount: intel.listingCount,
      });
      await this.registry.syncPageAllLocales({
        pageType: 'city_neighborhood',
        slug: `${dest.slug}/${nb.slug}`,
        indexable,
        seoScore: score,
        lastmod: now,
      });
    }
  }
}

