  family_friendly?: boolean;
  neighborhood?: string;
  near_lat?: number;
  near_lng?: number;
  near_radius_km?: number;
  limit?: number;
  cursor?: string;
  sort?: ExploreSort;
  north?: number;
  south?: number;
  east?: number;
  west?: number;
};

type MemoryCacheEntry = { expiresAt: number; value: unknown };

@Injectable()
export class ExploreService {
  private readonly logger = new Logger(ExploreService.name);
  /** Process-local short TTL cache (avoids Nest cache-manager peer conflicts). */
  private readonly memoryCache = new Map<string, MemoryCacheEntry>();

  constructor(
    @InjectRepository(StaysListing)
    private readonly listingRepo: Repository<StaysListing>,
    @InjectRepository(StaysListingMedia)
    private readonly mediaRepo: Repository<StaysListingMedia>,
    private readonly availabilityService: StaysAvailabilityService,
    private readonly metrics: MetricsService,
  ) {}

  async exploreListings(params: ExploreQueryParams): Promise<ExploreListEnvelope> {
    const started = Date.now();
    const sort = normalizeExploreSort(params.sort);
    const limit = Math.min(
      Math.max(params.limit ?? CARD_LIMIT_DEFAULT, 1),
      CARD_LIMIT_MAX,
    );

    let cursor: ExploreCursorPayload | null = null;
    try {
      cursor = decodeExploreCursor(params.cursor);
      if (cursor && cursor.s !== sort) {
        throw new BadRequestException({
          code: 'invalid_cursor',
          message: 'Cursor sort does not match request sort.',
        });
      }
    } catch (err) {
      this.metrics.incrementExploreCursorFailure();
      throw err;
    }

    if (params.north != null || params.south != null || params.east != null || params.west != null) {
      this.validateBounds(params.north!, params.south!, params.east!, params.west!, {
        allowTruncate: false,
      });
    }

    const cacheKey = this.buildCacheKey('list', { ...params, sort, limit });
    const dated = Boolean(params.checkin_date && params.checkout_date);
    const ttl = dated ? CACHE_TTL_DATED_MS : CACHE_TTL_MS;

    const cached = await this.safeCacheGet<ExploreListEnvelope>(cacheKey);
    if (cached) {
      this.metrics.incrementExploreCacheHit();
      return {
        ...cached,
        meta: {
          ...cached.meta,
          query_ms: Date.now() - started,
          cache: 'hit',
        },
      };
    }
    this.metrics.incrementExploreCacheMiss();

    const snapshot = cursor?.snapshot ?? nowSnapshotIso();
    const rows = await this.queryListings({
      ...params,
      sort,
      limit: limit + 1,
      snapshot,
      cursor,
      forMap: false,
    });

    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    const ids = page.map((r) => r.id);
    const { covers, walkthroughs } = await this.loadMediaHints(ids);

    const items: ExploreCard[] = page.map((l) => this.toCard(l, covers, walkthroughs));

    let nextCursor: string | null = null;
    if (hasMore && page.length > 0) {
      const last = page[page.length - 1];
      nextCursor = encodeExploreCursor(this.buildNextCursor(sort, snapshot, last));
    }

    const envelope: ExploreListEnvelope = {
      items,
      pagination: { next_cursor: nextCursor, has_more: hasMore },
      meta: {
        query_ms: Date.now() - started,
        sort,
        cache: 'miss',
        total_estimate: null,
      },
    };

    await this.safeCacheSet(cacheKey, envelope, ttl);
    this.metrics.recordExploreQueryMs(Date.now() - started);
    this.logger.debug(
      `explore list items=${items.length} has_more=${hasMore} ms=${envelope.meta.query_ms}`,
    );
    return envelope;
  }

  async exploreMap(params: ExploreQueryParams): Promise<ExploreMapEnvelope> {
    const started = Date.now();
    if (
      params.north == null ||
      params.south == null ||
      params.east == null ||
      params.west == null
    ) {
      throw new BadRequestException({
        code: 'invalid_bounds',
        message: 'Map explore requires north, south, east, and west.',
      });
    }

    const boundsCheck = this.validateBounds(
      params.north,
      params.south,
      params.east,
      params.west,
      { allowTruncate: true },
    );

    const bounds = {
      north: params.north,
      south: params.south,
      east: params.east,
      west: params.west,
    };

    const cacheKey = this.buildCacheKey('map', { ...params, sort: 'newest' });
    const dated = Boolean(params.checkin_date && params.checkout_date);
    const ttl = dated ? CACHE_TTL_DATED_MS : CACHE_TTL_MS;

    const cached = await this.safeCacheGet<ExploreMapEnvelope>(cacheKey);
    if (cached) {
      this.metrics.incrementExploreCacheHit();
      return {
        ...cached,
        meta: { ...cached.meta, query_ms: Date.now() - started, cache: 'hit' },
      };
    }
    this.metrics.incrementExploreCacheMiss();

    const rows = await this.queryListings({
      ...params,
      sort: 'newest',
      limit: MAP_PIN_MAX + 1,
      snapshot: nowSnapshotIso(),
      cursor: null,
      forMap: true,
    });

    const truncated =
      boundsCheck.forceTruncate || rows.length > MAP_PIN_MAX;
    const page = truncated ? rows.slice(0, MAP_PIN_MAX) : rows;
    const ids = page.map((r) => r.id);
    const { covers, walkthroughs } = await this.loadMediaHints(ids);

    const items: ExploreMapPin[] = page
      .filter((l) => l.geo_lat != null && l.geo_lng != null)
      .map((l) => this.toMapPin(l, covers, walkthroughs));

    const envelope: ExploreMapEnvelope = {
      items,
      bounds,
      truncated,
      meta: {
        query_ms: Date.now() - started,
        cache: 'miss',
      },
    };

    await this.safeCacheSet(cacheKey, envelope, ttl);
    this.metrics.recordExploreMapQueryMs(Date.now() - started);
    this.logger.debug(
      `explore map pins=${items.length} truncated=${truncated} ms=${envelope.meta.query_ms}`,
    );
    return envelope;
  }

  private validateBounds(
    north: number,
    south: number,
    east: number,
    west: number,
    opts: { allowTruncate: boolean },
  ): { forceTruncate: boolean } {
    if (
      ![north, south, east, west].every((n) => Number.isFinite(n)) ||
      north < -90 ||
      north > 90 ||
      south < -90 ||
      south > 90 ||
      east < -180 ||
      east > 180 ||
      west < -180 ||
      west > 180
    ) {
      throw new BadRequestException({
        code: 'invalid_bounds',
        message: 'Bounds must be finite latitudes/longitudes in range.',
      });
    }
    if (north <= south) {
      throw new BadRequestException({
        code: 'invalid_bounds',
        message: 'north must be greater than south.',
      });
    }
    if (east === west) {
      throw new BadRequestException({
        code: 'invalid_bounds',
        message: 'east and west must define a non-zero width.',
      });
    }

    const latSpan = north - south;
    const lngSpan = Math.abs(east - west);
    if (latSpan > MAX_BOUNDS_SPAN_DEG || lngSpan > MAX_BOUNDS_SPAN_DEG) {
      if (opts.allowTruncate) {
        return { forceTruncate: true };
      }
      throw new BadRequestException({
        code: 'invalid_bounds',
        message: `Map bounds span too large (max ${MAX_BOUNDS_SPAN_DEG}°). Zoom in and try again.`,
      });
    }
    return { forceTruncate: false };
  }

  private async queryListings(opts: {
    city?: string;
    checkin_date?: string;
    checkout_date?: string;
    guests?: number;
    verified_walkthrough_only?: boolean;
    instant_booking_only?: boolean;
    listing_type?: string;
    amenity?: string;
    pets_allowed?: boolean;
    luxury_only?: boolean;
    family_friendly?: boolean;
    neighborhood?: string;
    near_lat?: number;
    near_lng?: number;
    near_radius_km?: number;
    north?: number;
    south?: number;
    east?: number;
    west?: number;
    sort: ExploreSort;
    limit: number;
    snapshot: string;
    cursor: ExploreCursorPayload | null;
    forMap: boolean;
  }): Promise<StaysListing[]> {
    const qb = this.listingRepo
      .createQueryBuilder('l')
      .leftJoinAndSelect('l.rate_plan', 'rp')
      .leftJoinAndSelect('l.rules', 'rules')
      .where('l.status = :status', { status: 'LIVE' })
      .andWhere('l.created_at <= :snapshot', {
        snapshot: new Date(opts.snapshot),
      });

    if (opts.city?.trim()) {
      // Prefix match for index use (city picker / Explore).
      qb.andWhere('LOWER(l.city) LIKE LOWER(:city)', {
        city: `${opts.city.trim()}%`,
      });
    }

    if (opts.listing_type) {
      qb.andWhere('UPPER(l.listing_type) = UPPER(:listingType)', {
        listingType: opts.listing_type.trim(),
      });
    }

    if (opts.amenity?.trim()) {
      qb.andWhere('rules.amenities @> :amenityJson', {
        amenityJson: JSON.stringify([opts.amenity.trim()]),
      });
    }

    if (opts.pets_allowed) {
      qb.andWhere("rules.pets_policy IS NOT NULL AND rules.pets_policy <> 'NO'");
    }

    if (opts.family_friendly) {
      qb.andWhere('rules.max_guests >= :minGuests', { minGuests: 4 });
    }

    if (opts.luxury_only) {
      qb.andWhere(
        `(l.listing_type IN ('VILLA','RIAD') OR rp.base_price >= 1500)`,
      );
    }

    if (opts.neighborhood?.trim()) {
      qb.andWhere('LOWER(l.neighborhood) LIKE LOWER(:neighborhood)', {
        neighborhood: `%${opts.neighborhood.trim()}%`,
      });
    }

    if (
      opts.near_lat != null &&
      opts.near_lng != null &&
      opts.near_radius_km != null
    ) {
      const delta = opts.near_radius_km / 111;
      qb.andWhere('l.geo_lat IS NOT NULL AND l.geo_lng IS NOT NULL');
      qb.andWhere('l.geo_lat BETWEEN :minLat AND :maxLat', {
        minLat: opts.near_lat - delta,
        maxLat: opts.near_lat + delta,
      });
      qb.andWhere('l.geo_lng BETWEEN :minLng AND :maxLng', {
        minLng: opts.near_lng - delta,
        maxLng: opts.near_lng + delta,
      });
    }

    if (opts.instant_booking_only) {
      qb.andWhere('l.instant_booking = true');
    }

    if (opts.guests != null && opts.guests > 0) {
      qb.andWhere('rules.max_guests >= :guests', { guests: opts.guests });
    }

    if (opts.verified_walkthrough_only) {
      qb.andWhere(
        `EXISTS (
          SELECT 1 FROM stays_listing_media m
          WHERE m.listing_id = l.id AND m.kind = 'WALKTHROUGH'
        )`,
      );
    }

    if (
      opts.north != null &&
      opts.south != null &&
      opts.east != null &&
      opts.west != null
    ) {
      qb.andWhere('l.geo_lat IS NOT NULL AND l.geo_lng IS NOT NULL');
      qb.andWhere('l.geo_lat BETWEEN :south AND :north', {
        south: opts.south,
        north: opts.north,
      });
      if (opts.west <= opts.east) {
        qb.andWhere('l.geo_lng BETWEEN :west AND :east', {
          west: opts.west,
          east: opts.east,
        });
      } else {
        // Antimeridian wrap (rare for Morocco; still handle)
        qb.andWhere(
          '(l.geo_lng >= :west OR l.geo_lng <= :east)',
          { west: opts.west, east: opts.east },
        );
      }
    }

    if (opts.forMap) {
      qb.andWhere('l.geo_lat IS NOT NULL AND l.geo_lng IS NOT NULL');
    }

    /*
     * KNOWN SCALABILITY LIMIT (launch-acceptable, not long-term):
     * Date filtering uses getUnavailableListingIds() then NOT IN (...).
     * Replace with correlated NOT EXISTS against bookings/blocks, or an
     * indexed availability calendar, before large-scale booking volume.
     * Prefer scoping unavailable lookups to candidate/bounds sets when feasible.
     * Ticket: replace-explore-availability-notin
     */
    if (opts.checkin_date && opts.checkout_date) {
      const checkin = opts.checkin_date.trim();
      const checkout = opts.checkout_date.trim();
      if (
        /^\d{4}-\d{2}-\d{2}$/.test(checkin) &&
        /^\d{4}-\d{2}-\d{2}$/.test(checkout) &&
        checkout > checkin
      ) {
        const unavailable =
          await this.availabilityService.getUnavailableListingIds(
            checkin,
            checkout,
          );
        if (unavailable.length > 0) {
          qb.andWhere('l.id NOT IN (:...unavailable)', { unavailable });
        }
      }
    }

    // Keyset pagination.
    // Use an exclusive +1ms window for the "equal created_at" branch: JS Date / toISOString
    // only has millisecond precision, while Postgres timestamptz keeps microseconds.
    // Without this, batches that share one created_at (e.g. seed inserts) stall after page 1.
    if (opts.cursor?.c && opts.cursor?.i) {
      const cursorCreated = new Date(opts.cursor.c);
      const cursorCreatedEnd = new Date(cursorCreated.getTime() + 1);
      const createdTie = `(
        l.created_at < :cursorCreated
        OR (
          l.created_at >= :cursorCreated
          AND l.created_at < :cursorCreatedEnd
          AND l.id < :cursorId
        )
      )`;

      if (opts.sort === 'newest') {
        qb.andWhere(createdTie, {
          cursorCreated,
          cursorCreatedEnd,
          cursorId: opts.cursor.i,
        });
      } else if (opts.sort === 'price_asc' || opts.sort === 'price_desc') {
        const cursorPrice =
          opts.cursor.p != null && Number.isFinite(Number(opts.cursor.p))
            ? Number(opts.cursor.p)
            : null;
        const priceCmp =
          opts.sort === 'price_asc'
            ? `(
                (rp.base_price IS NULL AND :cursorPrice IS NOT NULL)
                OR (rp.base_price IS NOT NULL AND :cursorPrice IS NOT NULL AND rp.base_price > :cursorPrice)
                OR (
                  ((rp.base_price IS NULL AND :cursorPrice IS NULL) OR rp.base_price = :cursorPrice)
                  AND ${createdTie}
                )
              )`
            : `(
                (rp.base_price IS NULL AND :cursorPrice IS NOT NULL)
                OR (rp.base_price IS NOT NULL AND :cursorPrice IS NOT NULL AND rp.base_price < :cursorPrice)
                OR (
                  ((rp.base_price IS NULL AND :cursorPrice IS NULL) OR rp.base_price = :cursorPrice)
                  AND ${createdTie}
                )
              )`;
        qb.andWhere(priceCmp, {
          cursorPrice,
          cursorCreated,
          cursorCreatedEnd,
          cursorId: opts.cursor.i,
        });
      } else {
        const r = opts.cursor.r ?? null;
        const n = opts.cursor.n ?? 0;
        // Ranking keyset: (avg_rating DESC NULLS LAST, review_count DESC, created_at DESC, id DESC)
        qb.andWhere(
          `(
            (l.avg_rating IS NULL AND :cursorRating IS NOT NULL)
            OR (l.avg_rating IS NOT NULL AND :cursorRating IS NOT NULL AND l.avg_rating < :cursorRating)
            OR (
              ((l.avg_rating IS NULL AND :cursorRating IS NULL) OR l.avg_rating = :cursorRating)
              AND (
                l.review_count < :cursorReviews
                OR (
                  l.review_count = :cursorReviews
                  AND ${createdTie}
                )
              )
            )
          )`,
          {
            cursorRating: r,
            cursorReviews: n,
            cursorCreated,
            cursorCreatedEnd,
            cursorId: opts.cursor.i,
          },
        );
      }
    }

    if (opts.sort === 'rating') {
      qb.orderBy('l.avg_rating', 'DESC', 'NULLS LAST')
        .addOrderBy('l.review_count', 'DESC')
        .addOrderBy('l.created_at', 'DESC')
        .addOrderBy('l.id', 'DESC');
    } else if (opts.sort === 'price_asc') {
      qb.orderBy('rp.base_price', 'ASC', 'NULLS LAST')
        .addOrderBy('l.created_at', 'DESC')
        .addOrderBy('l.id', 'DESC');
    } else if (opts.sort === 'price_desc') {
      qb.orderBy('rp.base_price', 'DESC', 'NULLS LAST')
        .addOrderBy('l.created_at', 'DESC')
        .addOrderBy('l.id', 'DESC');
    } else {
      qb.orderBy('l.created_at', 'DESC').addOrderBy('l.id', 'DESC');
    }

    qb.take(opts.limit);
    return qb.getMany();
  }

  private buildNextCursor(
    sort: ExploreSort,
    snapshot: string,
    last: StaysListing,
  ): ExploreCursorPayload {
    const base: ExploreCursorPayload = {
      v: 1,
      s: sort,
      snapshot,
      c: new Date(last.created_at).toISOString(),
      i: last.id,
    };
    if (sort === 'rating') {
      base.r =
        last.avg_rating != null ? Number(last.avg_rating) : null;
      base.n = last.review_count ?? 0;
    }
    if (sort === 'price_asc' || sort === 'price_desc') {
      base.p =
        last.rate_plan?.base_price != null
          ? Number(last.rate_plan.base_price)
          : null;
    }
    return base;
  }

  private toMapPin(
    l: StaysListing,
    covers: Map<string, string>,
    walkthroughs: Set<string>,
  ): ExploreMapPin {
    const coverId = covers.get(l.id);
    const amenities = (l.rules?.amenities ?? []).map((a) =>
      String(a).toLowerCase(),
    );
    return {
      id: l.id,
      title: l.title,
      city: l.city,
      neighborhood: l.neighborhood,
      geo_lat: Number(l.geo_lat),
      geo_lng: Number(l.geo_lng),
      avg_rating: l.avg_rating != null ? Number(l.avg_rating) : null,
      review_count: l.review_count ?? 0,
      bedrooms: this.bedroomCount(l.property_details),
      max_guests: l.rules?.max_guests != null ? Number(l.rules.max_guests) : null,
      has_wifi: amenities.some(
        (a) => a === 'wifi' || a.includes('wifi') || a.includes('wi-fi'),
      ),
      has_walkthrough: walkthroughs.has(l.id),
      instant_booking: Boolean(l.instant_booking),
      price: l.rate_plan
        ? {
            base_price: Number(l.rate_plan.base_price),
            currency: l.rate_plan.currency || 'MAD',
          }
        : null,
      cover: coverId ? { asset_id: coverId, kind: 'PHOTO' } : null,
    };
  }

  private bedroomCount(
    details: Record<string, unknown> | null | undefined,
  ): number | null {
    if (!details || typeof details !== 'object') return null;
    const bedrooms = details.bedrooms;
    if (Array.isArray(bedrooms) && bedrooms.length > 0) return bedrooms.length;
    if (typeof bedrooms === 'number' && Number.isFinite(bedrooms)) {
      return bedrooms;
    }
    const count = details.bedroom_count ?? details.beds;
    if (typeof count === 'number' && Number.isFinite(count)) return count;
    return null;
  }

  private toCard(
    l: StaysListing,
    covers: Map<string, string>,
    walkthroughs: Set<string>,
  ): ExploreCard {
    const coverId = covers.get(l.id);
    return {
      id: l.id,
      title: l.title,
      city: l.city,
      neighborhood: l.neighborhood,
      listing_type: l.listing_type,
      geo_lat: l.geo_lat != null ? Number(l.geo_lat) : null,
      geo_lng: l.geo_lng != null ? Number(l.geo_lng) : null,
      avg_rating: l.avg_rating != null ? Number(l.avg_rating) : null,
      review_count: l.review_count ?? 0,
      instant_booking: Boolean(l.instant_booking),
      has_walkthrough: walkthroughs.has(l.id),
      placement: 'organic',
      price: l.rate_plan
        ? {
            base_price: Number(l.rate_plan.base_price),
            currency: l.rate_plan.currency || 'MAD',
          }
        : null,
      cover: coverId
        ? { asset_id: coverId, kind: 'PHOTO' }
        : null,
    };
  }

  private async loadMediaHints(listingIds: string[]): Promise<{
    covers: Map<string, string>;
    walkthroughs: Set<string>;
  }> {
    const covers = new Map<string, string>();
    const walkthroughs = new Set<string>();
    if (listingIds.length === 0) return { covers, walkthroughs };

    const photos = await this.mediaRepo
      .createQueryBuilder('m')
      .where('m.listing_id IN (:...ids)', { ids: listingIds })
      .andWhere('m.kind = :kind', { kind: 'PHOTO' })
      .orderBy('m.listing_id', 'ASC')
      .addOrderBy('m.sort_order', 'ASC')
      .getMany();

    for (const m of photos) {
      if (!covers.has(m.listing_id)) {
        covers.set(m.listing_id, m.asset_id);
      }
    }

    const walks = await this.mediaRepo
      .createQueryBuilder('m')
      .select('DISTINCT m.listing_id', 'listing_id')
      .where('m.listing_id IN (:...ids)', { ids: listingIds })
      .andWhere('m.kind = :kind', { kind: 'WALKTHROUGH' })
      .getRawMany<{ listing_id: string }>();

    for (const row of walks) {
      if (row.listing_id) walkthroughs.add(row.listing_id);
    }

    return { covers, walkthroughs };
  }

  private buildCacheKey(
    kind: 'list' | 'map',
    params: ExploreQueryParams & { sort?: ExploreSort; limit?: number },
  ): string {
    const normalized: Record<string, string> = { kind };
    const put = (k: string, v: string | number | boolean | undefined | null) => {
      if (v === undefined || v === null || v === '') return;
      if (typeof v === 'string' && v.trim() === '') return;
      // Drop defaults
      if (k === 'limit' && Number(v) === CARD_LIMIT_DEFAULT) return;
      if (k === 'sort' && v === 'newest') return;
      normalized[k] =
        typeof v === 'string' ? v.trim().toLowerCase() : String(v);
    };

    put('city', params.city);
    put('checkin_date', params.checkin_date);
    put('checkout_date', params.checkout_date);
    put('guests', params.guests);
    put('verified_walkthrough_only', params.verified_walkthrough_only);
    put('instant_booking_only', params.instant_booking_only);
    put('listing_type', params.listing_type);
    put('amenity', params.amenity);
    put('pets_allowed', params.pets_allowed);
    put('luxury_only', params.luxury_only);
    put('family_friendly', params.family_friendly);
    put('neighborhood', params.neighborhood);
    put('near_lat', params.near_lat);
    put('near_lng', params.near_lng);
    put('near_radius_km', params.near_radius_km);
    put('limit', params.limit);
    put('cursor', params.cursor);
    put('sort', params.sort);
    put('north', params.north);
    put('south', params.south);
    put('east', params.east);
    put('west', params.west);

    const stable = Object.keys(normalized)
      .sort()
      .map((k) => `${k}=${normalized[k]}`)
      .join('&');
    const hash = createHash('sha256').update(stable).digest('hex').slice(0, 32);
    return `explore:v1:${hash}`;
  }

  private async safeCacheGet<T>(key: string): Promise<T | null> {
    const entry = this.memoryCache.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.memoryCache.delete(key);
      return null;
    }
    return entry.value as T;
  }

  private async safeCacheSet(
    key: string,
    value: unknown,
    ttlMs: number,
  ): Promise<void> {
    try {
      const json = JSON.stringify(value);
      if (Buffer.byteLength(json, 'utf8') > CACHE_MAX_BYTES) {
        this.metrics.incrementExploreCacheBypass();
        this.logger.warn(`explore cache bypass: payload > ${CACHE_MAX_BYTES} bytes`);
        return;
      }
      // Bound memory: drop expired entries occasionally.
      if (this.memoryCache.size > 500) {
        const now = Date.now();
        for (const [k, v] of this.memoryCache) {
          if (now > v.expiresAt) this.memoryCache.delete(k);
        }
      }
      this.memoryCache.set(key, { expiresAt: Date.now() + ttlMs, value });
    } catch (err) {
      this.logger.warn(`explore cache set failed: ${String(err)}`);
    }
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { StaysHostProfile } from '../entities/stays-host-profile.entity';
import { HostOnboardingService } from './host-onboarding.service';
import type { SubmitHostOnboardingDto } from '../dto/submit-host-onboarding.dto';
import type { StaysUserContext } from './host-onboarding.types';
import { MediaStorageService } from '../../../common/media/media-storage.module';

const VERIFY_EXTS = ['.jpg', '.jpeg', '.png', '.webp'];
export type HostVerificationDocKind = 'front' | 'back' | 'selfie';

/**
 * Backward-compatible API aliases for host onboarding (stays_host_profiles only).
 */
@Injectable()
export class HostApplicationsService {
  constructor(
    private readonly hostOnboarding: HostOnboardingService,
    @InjectRepository(StaysHostProfile)
    private readonly hostProfileRepo: Repository<StaysHostProfile>,
    private readonly mediaStorage: MediaStorageService,
  ) {}

  async submit(
    user: StaysUserContext,
    data: {
      full_name?: string;
      email?: string;
      identity_reused?: boolean;
      hosting_policies_accepted?: boolean;
    },
  ): Promise<{ id: string; status: string }> {
    const dto: SubmitHostOnboardingDto = {
      full_name: data.full_name,
      email: data.email,
      identity_reused: data.identity_reused,
      use_existing_kyc: true,
      hosting_policies_accepted: data.hosting_policies_accepted,
      source: 'MOBILE',
      submitted_from: 'MOBILE_BECOME_HOST',
    };
    const result = await this.hostOnboarding.submitHostOnboarding(user, dto, {
      source: 'MOBILE',
      submitted_from: 'MOBILE_BECOME_HOST',
      requirePolicies: true,
    });
    return { id: result.id, status: result.status };
  }

  async getStatusByUserId(applicantUserId: string) {
    return this.hostOnboarding.getLegacyApplicationStatus(applicantUserId);
  }

  async list(params?: {
    status?: string;
    limit?: number;
    offset?: number;
  }) {
    return this.hostOnboarding.listForAdmin({
      application_status: params?.status,
      limit: params?.limit,
      offset: params?.offset,
    });
  }

  async getById(id: string): Promise<StaysHostProfile> {
    const profile = await this.hostProfileRepo.findOne({ where: { id } });
    if (profile) return profile;
    const legacy = await this.hostOnboarding.findProfileByLegacyApplicationId(id);
    if (legacy) return legacy;
    throw new NotFoundException('Host application not found');
  }

  async approve(id: string, reviewedBy: string) {
    const byProfile = await this.hostProfileRepo.findOne({ where: { id } });
    if (byProfile) {
      return this.hostOnboarding.approve(id, reviewedBy);
    }
    return this.hostOnboarding.approveLegacyApplication(id, reviewedBy);
  }

  async reject(id: string, reviewedBy: string, reason: string) {
    const byProfile = await this.hostProfileRepo.findOne({ where: { id } });
    if (byProfile) {
      return this.hostOnboarding.reject(id, reason, reviewedBy);
    }
    return this.hostOnboarding.rejectLegacyApplication(id, reason, reviewedBy);
  }

  async getVerificationDocumentPath(
    applicationId: string,
    kind: HostVerificationDocKind,
  ): Promise<string> {
    const profile = await this.getById(applicationId);
    const prefix =
      kind === 'front' ? 'id_front' : kind === 'back' ? 'id_back' : 'selfie';
    const assetId =
      kind === 'front'
        ? profile.document_front_asset_id
        : kind === 'back'
          ? profile.document_back_asset_id
          : profile.selfie_asset_id;
    if (!assetId?.trim()) {
      throw new NotFoundException(`${kind} document not uploaded`);
    }
    const candidates = VERIFY_EXTS.map(
      (ext) =>
        `host/${profile.user_id}/verification/${prefix}_${assetId}${ext}`,
    );
    const found = await this.mediaStorage.resolveFirstExisting(candidates);
    if (!found) {
      throw new NotFoundException(`${kind} document file not found`);
    }
    return found.delivery;
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, Repository } from 'typeorm';
import { StaysHostProfile } from '../entities/stays-host-profile.entity';
import { StaysAuditLog } from '../entities/stays-audit-log.entity';
import { normalizePhoneOrThrow } from '../../../common/phone/phone-normalizer';
import type { SubmitHostOnboardingDto } from '../dto/submit-host-onboarding.dto';
import type {
  HostApplicationStatus,
  HostIdentityStatus,
  HostOnboardingSource,
  StaysUserContext,
} from './host-onboarding.types';
import { StaysKycPolicyService } from '../../../common/identity/stays-kyc-policy.service';
import { MediaStorageService } from '../../../common/media/media-storage.module';

const VERIFY_EXTS = ['.jpg', '.jpeg', '.png', '.webp'];

/** Admin-safe host profile: never document_number_hash or sumsub_applicant_id. */
export function toAdminHostProfileDto(profile: StaysHostProfile) {
  return {
    id: profile.id,
    user_id: profile.user_id,
    host_verification_status: profile.host_verification_status,
    application_status: profile.application_status,
    identity_status: profile.identity_status,
    source: profile.source,
    submitted_from: profile.submitted_from,
    full_name: profile.full_name,
    email: profile.email,
    phone: profile.phone,
    city: profile.city,
    host_type: profile.host_type,
    hosting_policies_accepted_at: profile.hosting_policies_accepted_at,
    identity_reused: profile.identity_reused,
    listing_frozen: profile.listing_frozen,
    document_type: profile.document_type,
    document_front_asset_id: profile.document_front_asset_id,
    document_back_asset_id: profile.document_back_asset_id,
    selfie_asset_id: profile.selfie_asset_id,
    submitted_at: profile.submitted_at,
    reviewed_at: profile.reviewed_at,
    reviewed_by: profile.reviewed_by,
    rejection_reason: profile.rejection_reason,
    created_at: profile.created_at,
    updated_at: profile.updated_at,
  };
}

export type SubmitHostOnboardingContext = {
  source: HostOnboardingSource;
  submitted_from: string;
  requirePolicies?: boolean;
};

@Injectable()
export class HostOnboardingService {
  constructor(
    @InjectRepository(StaysHostProfile)
    private readonly hostProfileRepo: Repository<StaysHostProfile>,
    @InjectRepository(StaysAuditLog)
    private readonly auditRepo: Repository<StaysAuditLog>,
    private readonly dataSource: DataSource,
    private readonly kycPolicy: StaysKycPolicyService,
    private readonly mediaStorage: MediaStorageService,
  ) {}

  private isIdentityVerified(user: StaysUserContext): boolean {
    return this.kycPolicy.meetsHostIdentityReuse(user.identitySnapshot);
  }

  async submitHostOnboarding(
    user: StaysUserContext,
    dto: SubmitHostOnboardingDto,
    context: SubmitHostOnboardingContext,
  ) {
    if (!this.isIdentityVerified(user)) {
      const hasDocuments = !!(
        dto.document_front_asset_id?.trim() && dto.selfie_asset_id?.trim()
      );
      const useExisting = dto.use_existing_kyc === true;
      if (useExisting || !hasDocuments) {
        throw new ForbiddenException(
          'Identity verification required. Complete KYC in Nexa Identity or upload ID documents.',
        );
      }
    }

    if (context.requirePolicies && dto.hosting_policies_accepted !== true) {
      throw new BadRequestException(
        'You must accept hosting policies to apply',
      );
    }

    await this.assertOwnedVerificationAssets(user.userId, dto);

    let profile = await this.hostProfileRepo.findOne({
      where: { user_id: user.userId },
    });

    if (
      profile?.application_status === 'PENDING' ||
      profile?.application_status === 'APPROVED'
    ) {
      if (profile.application_status === 'APPROVED') {
        throw new ConflictException('You already have an approved host account');
      }
      return this.toSubmitResponse(profile);
    }

    if (!profile) {
      profile = this.hostProfileRepo.create({
        user_id: user.userId,
        application_status: 'DRAFT',
        identity_status: 'VERIFIED',
        host_verification_status: 'PENDING',
        source: context.source,
        submitted_from: context.submitted_from,
        identity_reused: true,
      });
    }

    const phone = dto.phone ?? user.phone_number ?? null;
    if (!phone?.trim()) {
      throw new BadRequestException(
        'A verified phone number is required to submit host onboarding',
      );
    }

    profile.full_name = dto.full_name ?? profile.full_name;
    profile.email = dto.email ?? user.email ?? profile.email;
    profile.phone = normalizePhoneOrThrow(phone);
    profile.city = dto.city ?? profile.city;
    profile.host_type = dto.host_type ?? profile.host_type;
    profile.source = context.source;
    profile.submitted_from = context.submitted_from;
    profile.document_type = dto.document_type ?? profile.document_type;
    profile.document_number_hash =
      dto.document_number_hash ?? profile.document_number_hash;
    profile.document_front_asset_id =
      dto.document_front_asset_id ?? profile.document_front_asset_id;
    profile.document_back_asset_id =
      dto.document_back_asset_id ?? profile.document_back_asset_id;
    profile.selfie_asset_id = dto.selfie_asset_id ?? profile.selfie_asset_id;

    const useExistingKyc = dto.use_existing_kyc === true && this.isIdentityVerified(user);
    if (useExistingKyc) {
      profile.identity_status = 'VERIFIED';
      profile.identity_reused = true;
    } else if (dto.document_front_asset_id && dto.selfie_asset_id) {
      profile.identity_status = this.isIdentityVerified(user) ? 'VERIFIED' : 'PENDING';
      profile.identity_reused = false;
    } else {
      profile.identity_status = 'VERIFIED';
      profile.identity_reused = dto.identity_reused ?? true;
    }

    if (dto.hosting_policies_accepted === true) {
      profile.hosting_policies_accepted_at = new Date();
    }

    profile.application_status = 'PENDING';
    profile.host_verification_status = 'PENDING';
    profile.submitted_at = new Date();
    profile.reviewed_at = null;
    profile.reviewed_by = null;
    profile.rejection_reason = null;

    const saved = await this.hostProfileRepo.save(profile);
    return {
      ...this.toSubmitResponse(saved),
      message:
        'Host onboarding submitted. Your application will be reviewed shortly.',
    };
  }

  async getHostMe(user: StaysUserContext) {
    const profile = await this.hostProfileRepo.findOne({
      where: { user_id: user.userId },
    });

    const isHost = profile?.application_status === 'APPROVED';
    const canList =
      !!profile &&
      profile.application_status === 'APPROVED' &&
      profile.host_verification_status === 'APPROVED' &&
      !profile.listing_frozen;

    return {
      is_host: isHost,
      host_user_id: isHost ? user.userId : null,
      profile_id: profile?.id ?? null,
      application_status: profile?.application_status ?? 'NOT_STARTED',
      identity_status:
        profile?.identity_status ??
        (this.isIdentityVerified(user) ? 'VERIFIED' : 'NOT_STARTED'),
      host_verification_status:
        profile?.host_verification_status ?? 'NOT_STARTED',
      can_create_listing: canList,
      can_publish_listing: canList,
      rejection_reason: profile?.rejection_reason ?? null,
      submitted_at: profile?.submitted_at ?? null,
      reviewed_at: profile?.reviewed_at ?? null,
      source: profile?.source ?? null,
      submitted_from: profile?.submitted_from ?? null,
      kyc_verified: this.isIdentityVerified(user),
      identity_snapshot: user.identitySnapshot ?? null,
    };
  }

  async getLegacyApplicationStatus(userId: string) {
    const profile = await this.hostProfileRepo.findOne({
      where: { user_id: userId },
    });
    if (!profile) return null;
    return {
      id: profile.id,
      status:
        profile.application_status === 'PENDING'
          ? 'PENDING'
          : profile.application_status,
      identity_status: profile.identity_status,
      host_verification_status: profile.host_verification_status,
      submitted_at: profile.submitted_at,
      reviewed_at: profile.reviewed_at,
      rejection_reason: profile.rejection_reason,
    };
  }

  async getVerificationStatus(userId: string) {
    const profile = await this.resolveProfileForUser(userId);
    if (!profile) {
      return {
        status: 'NOT_STARTED',
        application_status: 'NOT_STARTED',
        identity_status: 'NOT_STARTED',
        message:
          'Host verification required to publish listings. Submit your host onboarding to get approved.',
      };
    }

    return {
      status: profile.host_verification_status,
      application_status: profile.application_status,
      identity_status: profile.identity_status,
      submitted_at: profile.submitted_at,
      reviewed_at: profile.reviewed_at,
      rejection_reason: profile.rejection_reason,
    };
  }

  async listForAdmin(params?: {
    application_status?: string;
    status?: string;
    limit?: number;
    offset?: number;
  }) {
    const { application_status, status, limit = 50, offset = 0 } = params || {};
    const safeLimit = Math.min(Math.max(1, Number(limit) || 50), 500);
    const safeOffset = Math.max(0, Number(offset) || 0);
    const qb = this.hostProfileRepo
      .createQueryBuilder('hp')
      .orderBy('hp.submitted_at', 'DESC', 'NULLS LAST')
      .addOrderBy('hp.created_at', 'DESC')
      .take(safeLimit)
      .skip(safeOffset);

    const appStatus = application_status ?? status;
    if (appStatus && appStatus !== 'all') {
      if (appStatus === 'UNDER_REVIEW') {
        qb.andWhere('hp.application_status = :pending', { pending: 'PENDING' });
      } else {
        qb.andWhere('hp.application_status = :appStatus', { appStatus });
      }
    }

    const [items, total] = await qb.getManyAndCount();
    return { items: items.map(toAdminHostProfileDto), total };
  }

  async approve(
    profileId: string,
    reviewedBy: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.dataSource.transaction(async (manager) => {
      const locked = await manager
        .getRepository(StaysHostProfile)
        .createQueryBuilder('hp')
        .where('hp.id = :id', { id: profileId })
        .setLock('pessimistic_write')
        .getOne();
      if (!locked) {
        throw new NotFoundException('Host profile not found');
      }
      if (
        locked.application_status !== 'PENDING' &&
        locked.application_status !== 'DRAFT'
      ) {
        throw new BadRequestException(
          `Cannot approve host onboarding with status ${locked.application_status}`,
        );
      }
      locked.application_status = 'APPROVED';
      locked.host_verification_status = 'APPROVED';
      locked.reviewed_at = new Date();
      locked.reviewed_by = reviewedBy;
      locked.rejection_reason = null;
      await manager.save(StaysHostProfile, locked);
      return locked;
    });

    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: reviewedBy,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: profileId,
        action: 'HOST_ONBOARDING_APPROVED',
        metadata: { source: profile.source, submitted_from: profile.submitted_from },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );

    return {
      id: profile.id,
      status: 'APPROVED',
      application_status: 'APPROVED',
      host_user_id: profile.user_id,
      message: 'Host approved',
    };
  }

  async reject(
    profileId: string,
    reason: string,
    reviewedBy: string,
    auditContext?: { ip?: string; userAgent?: string },
  ) {
    const profile = await this.hostProfileRepo.findOne({
      where: { id: profileId },
    });
    if (!profile) {
      throw new NotFoundException('Host profile not found');
    }
    if (
      profile.application_status !== 'PENDING' &&
      profile.application_status !== 'DRAFT'
    ) {
      throw new BadRequestException(
        `Cannot reject host onboarding with status ${profile.application_status}`,
      );
    }

    profile.application_status = 'REJECTED';
    profile.host_verification_status = 'REJECTED';
    profile.reviewed_at = new Date();
    profile.reviewed_by = reviewedBy;
    profile.rejection_reason = reason || 'Rejected by admin';
    await this.hostProfileRepo.save(profile);

    await this.auditRepo.save(
      this.auditRepo.create({
        actor_user_id: reviewedBy,
        actor_role: 'ADMIN',
        entity_type: 'HOST_PROFILE',
        entity_id: profileId,
        action: 'HOST_ONBOARDING_REJECTED',
        metadata: { reason },
        ip: auditContext?.ip ?? null,
        user_agent: auditContext?.userAgent ?? null,
      }),
    );

    return {
      id: profile.id,
      status: 'REJECTED',
      application_status: 'REJECTED',
      message: 'Host rejected',
    };
  }

  async findProfileByLegacyApplicationId(
    applicationId: string,
  ): Promise<StaysHostProfile | null> {
    const row = await this.dataSource.query(
      `SELECT applicant_user_id FROM host_applications WHERE id = $1 LIMIT 1`,
      [applicationId],
    );
    const applicantId = row?.[0]?.applicant_user_id as string | undefined;
    if (!applicantId) return null;
    return this.hostProfileRepo.findOne({ where: { user_id: applicantId } });
  }

  async approveLegacyApplication(applicationId: string, reviewedBy: string) {
    const profile = await this.findProfileByLegacyApplicationId(applicationId);
    if (!profile) {
      throw new NotFoundException(
        'No host profile found for this application. Resubmit onboarding.',
      );
    }
    return this.approve(profile.id, reviewedBy);
  }

  async rejectLegacyApplication(
    applicationId: string,
    reason: string,
    reviewedBy: string,
  ) {
    const profile = await this.findProfileByLegacyApplicationId(applicationId);
    if (!profile) {
      throw new NotFoundException('No host profile found for this application');
    }
    return this.reject(profile.id, reason, reviewedBy);
  }

  async countPendingApplications(): Promise<number> {
    return this.hostProfileRepo.count({
      where: { application_status: 'PENDING' },
    });
  }

  async resolveProfileForUser(userId: string) {
    return this.hostProfileRepo.findOne({ where: { user_id: userId } });
  }

  async isApprovedHost(userId: string): Promise<boolean> {
    const profile = await this.resolveProfileForUser(userId);
    return profile?.application_status === 'APPROVED';
  }

  async canList(userId: string): Promise<boolean> {
    const profile = await this.resolveProfileForUser(userId);
    return (
      profile?.application_status === 'APPROVED' &&
      profile?.host_verification_status === 'APPROVED' &&
      !profile?.listing_frozen
    );
  }

  private async assertOwnedVerificationAssets(
    userId: string,
    dto: SubmitHostOnboardingDto,
  ): Promise<void> {
    const checks: Array<{ assetId?: string; prefix: string }> = [
      { assetId: dto.document_front_asset_id, prefix: 'id_front' },
      { assetId: dto.document_back_asset_id, prefix: 'id_back' },
      { assetId: dto.selfie_asset_id, prefix: 'selfie' },
    ];
    for (const { assetId, prefix } of checks) {
      const id = assetId?.trim();
      if (!id) continue;
      const candidates = VERIFY_EXTS.map(
        (ext) => `host/${userId}/verification/${prefix}_${id}${ext}`,
      );
      const found = await this.mediaStorage.resolveFirstExisting(candidates);
      if (!found) {
        throw new BadRequestException(
          `Invalid ${prefix} asset_id — upload the document first as this user`,
        );
      }
    }
  }

  private toSubmitResponse(profile: StaysHostProfile) {
    return {
      id: profile.id,
      application_status: profile.application_status as HostApplicationStatus,
      identity_status: profile.identity_status as HostIdentityStatus,
      status: profile.application_status,
      message: 'Host onboarding status retrieved',
    };
  }
}

import type { IdentitySnapshot } from '../../../common/identity/identity-snapshot.types';

export type StaysUserContext = {
  userId: string;
  unified_identity_id?: string;
  phone_number?: string;
  email?: string;
  account_type?: string;
  identitySnapshot?: IdentitySnapshot | null;
};

export type HostApplicationStatus =
  | 'NOT_STARTED'
  | 'DRAFT'
  | 'PENDING'
  | 'APPROVED'
  | 'REJECTED';

export type HostIdentityStatus =
  | 'NOT_STARTED'
  | 'PENDING'
  | 'VERIFIED'
  | 'REJECTED'
  | 'FAILED'
  | 'NOT_REQUIRED';

export type HostOnboardingSource = 'WEB' | 'MOBILE' | 'ADMIN' | 'UNKNOWN';

export const HOST_ONBOARDING_SOURCES: HostOnboardingSource[] = [
  'WEB',
  'MOBILE',
  'ADMIN',
  'UNKNOWN',
];

import {
  BadRequestException,
  Injectable,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { randomUUID } from 'crypto';
import { Repository } from 'typeorm';
import { StaysHostProfile } from '../entities/stays-host-profile.entity';
import { HostOnboardingService } from './host-onboarding.service';
import type { SubmitHostOnboardingDto } from '../dto/submit-host-onboarding.dto';
import type { StaysUserContext } from './host-onboarding.types';
import { detectImageType } from '../../../common/utils/image-type.util';
import { MediaStorageService } from '../../../common/media/media-storage.module';

const MAX_DOC_SIZE = 5 * 1024 * 1024;

@Injectable()
export class HostsService {
  constructor(
    @InjectRepository(StaysHostProfile)
    private readonly hostProfileRepo: Repository<StaysHostProfile>,
    private readonly hostOnboarding: HostOnboardingService,
    private readonly mediaStorage: MediaStorageService,
  ) {}

  async getHostVerificationStatus(user: StaysUserContext) {
    return this.hostOnboarding.getVerificationStatus(user.userId);
  }

  async submitHostVerification(
    user: StaysUserContext,
    data: SubmitHostOnboardingDto,
  ) {
    const useExisting = data.use_existing_kyc === true;
    const dto: SubmitHostOnboardingDto = {
      ...data,
      use_existing_kyc: useExisting,
      identity_reused: useExisting || data.identity_reused,
      source: data.source ?? 'WEB',
      submitted_from: data.submitted_from ?? 'WEB_BECOME_HOST',
    };
    const result = await this.hostOnboarding.submitHostOnboarding(user, dto, {
      source: 'WEB',
      submitted_from: dto.submitted_from ?? 'WEB_BECOME_HOST',
      requirePolicies: dto.hosting_policies_accepted === true,
    });
    return {
      status: result.application_status,
      application_status: result.application_status,
      identity_status: result.identity_status,
      message: result.message,
    };
  }

  async isHostVerified(userId: string): Promise<boolean> {
    return this.hostOnboarding.isApprovedHost(userId);
  }

  async getHostProfileOrNull(userId: string): Promise<StaysHostProfile | null> {
    return this.hostOnboarding.resolveProfileForUser(userId);
  }

  /**
   * Authoritative listing eligibility (H15).
   * Must match HostOnboardingService.canList — never use isApprovedHost alone.
   */
  async canList(userId: string): Promise<boolean> {
    return this.hostOnboarding.canList(userId);
  }

  uploadDocumentFront(
    userId: string,
    file: Express.Multer.File | undefined,
  ): Promise<{ asset_id: string }> {
    return this.saveHostVerificationImage(userId, file, 'id_front');
  }

  uploadDocumentBack(
    userId: string,
    file: Express.Multer.File | undefined,
  ): Promise<{ asset_id: string }> {
    return this.saveHostVerificationImage(userId, file, 'id_back');
  }

  uploadSelfie(
    userId: string,
    file: Express.Multer.File | undefined,
  ): Promise<{ asset_id: string }> {
    return this.saveHostVerificationImage(userId, file, 'selfie');
  }

  private async saveHostVerificationImage(
    userId: string,
    file: Express.Multer.File | undefined,
    prefix: string,
  ): Promise<{ asset_id: string }> {
    if (!file || !file.buffer || file.buffer.length === 0) {
      throw new BadRequestException('No file uploaded');
    }
    if (file.size > MAX_DOC_SIZE) {
      throw new BadRequestException(`File too large. Max ${MAX_DOC_SIZE / 1024 / 1024}MB`);
    }
    const detected = detectImageType(file.buffer);
    if (!detected) {
      throw new BadRequestException('Invalid image. Use JPEG, PNG, or WebP');
    }
    const ext = detected === 'png' ? '.png' : detected === 'webp' ? '.webp' : '.jpg';
    const mime =
      detected === 'png'
        ? 'image/png'
        : detected === 'webp'
          ? 'image/webp'
          : 'image/jpeg';
    const assetId = randomUUID();
    await this.mediaStorage.store({
      buffer: file.buffer,
      relativeKey: `host/${userId}/verification/${prefix}_${assetId}${ext}`,
      mimeType: mime,
      assetId,
    });
    return { asset_id: assetId };
  }
}

/**
 * Listing completion flags + weighted %.
 * Single source of truth for submit gates and dashboard progress.
 * Change weights here without migrating rows.
 */

export type ListingCompletionFlags = {
  location_complete: boolean;
  about_complete: boolean;
  pricing_complete: boolean;
  photos_complete: boolean;
  photos_quality_complete: boolean;
  rooms_complete: boolean;
  walkthrough_complete: boolean;
  amenities_complete: boolean;
  house_rules_complete: boolean;
};

export const COMPLETION_WEIGHTS = {
  location: 20,
  about: 20,
  pricing: 20,
  photos: 30,
  walkthrough: 5,
  optional: 5, // amenities / house rules / 12 photos quality
} as const;

export const SUBMIT_MIN_PHOTOS = 5;
export const QUALITY_TARGET_PHOTOS = 12;

export function roomsRequiredForType(
  listingType: string,
  bookingModel: string | null | undefined,
): boolean {
  if (listingType === 'HOTEL' || listingType === 'HOSTEL') return true;
  if (listingType === 'RIAD') {
    return bookingModel === 'ROOM_TYPES' || bookingModel === 'BOTH';
  }
  return false;
}

export type CompletionInput = {
  listing_type: string;
  booking_model?: string | null;
  title?: string | null;
  city?: string | null;
  address?: string | null;
  geo_lat?: number | null;
  geo_lng?: number | null;
  description?: string | null;
  max_guests?: number | null;
  base_price?: number | null;
  photo_count: number;
  has_walkthrough: boolean;
  unit_count: number;
  amenities_count?: number;
  has_house_rules_touch?: boolean;
  guest_house?: boolean;
};

export function computeCompletionFlags(input: CompletionInput): ListingCompletionFlags {
  const roomsNeeded = roomsRequiredForType(
    input.listing_type,
    input.booking_model,
  );
  const pricingOk = roomsNeeded
    ? input.unit_count > 0 && (input.base_price ?? 0) > 0
    : (input.base_price ?? 0) > 0;

  return {
    location_complete: Boolean(
      input.city?.trim() &&
        input.address?.trim() &&
        input.geo_lat != null &&
        input.geo_lng != null,
    ),
    about_complete: Boolean(
      input.title?.trim() &&
        input.title.trim() !== 'Untitled listing' &&
        (input.description?.trim()?.length ?? 0) >= 20 &&
        (input.max_guests ?? 0) >= 1,
    ),
    pricing_complete: pricingOk,
    photos_complete: input.photo_count >= SUBMIT_MIN_PHOTOS,
    photos_quality_complete: input.photo_count >= QUALITY_TARGET_PHOTOS,
    rooms_complete: roomsNeeded ? input.unit_count > 0 : true,
    walkthrough_complete: input.has_walkthrough,
    amenities_complete: (input.amenities_count ?? 0) > 0,
    house_rules_complete: Boolean(input.has_house_rules_touch),
  };
}

export function computeCompletionPercentage(flags: ListingCompletionFlags): number {
  let score = 0;
  if (flags.location_complete) score += COMPLETION_WEIGHTS.location;
  if (flags.about_complete) score += COMPLETION_WEIGHTS.about;
  if (flags.pricing_complete) score += COMPLETION_WEIGHTS.pricing;
  if (flags.photos_complete) score += COMPLETION_WEIGHTS.photos;
  if (flags.walkthrough_complete) score += COMPLETION_WEIGHTS.walkthrough;

  const optionalBits = [
    flags.photos_quality_complete,
    flags.amenities_complete,
    flags.house_rules_complete,
  ].filter(Boolean).length;
  if (optionalBits > 0) {
    score += Math.round((COMPLETION_WEIGHTS.optional * optionalBits) / 3);
  }

  // Rooms required: if incomplete, cap progress feel by not adding pricing/rooms fully —
  // rooms_complete already gates pricing for hotels via pricingOk.
  if (!flags.rooms_complete) {
    score = Math.min(score, 55);
  }

  return Math.min(100, Math.max(0, score));
}

export function assertCanSubmit(flags: ListingCompletionFlags): string | null {
  if (!flags.location_complete) return 'Location (city, address, and map pin) is required.';
  if (!flags.about_complete) return 'Title, description (20+ characters), and guest capacity are required.';
  if (!flags.rooms_complete) return 'Room configuration is required for this property type.';
  if (!flags.pricing_complete) return 'Pricing is required.';
  if (!flags.photos_complete) {
    return `At least ${SUBMIT_MIN_PHOTOS} photos are required to submit.`;
  }
  return null;
}

export type MissingItem = { key: string; label: string; required: boolean };

export function listMissing(flags: ListingCompletionFlags): MissingItem[] {
  const items: MissingItem[] = [];
  if (!flags.location_complete) {
    items.push({ key: 'location', label: 'Location', required: true });
  }
  if (!flags.about_complete) {
    items.push({ key: 'about', label: 'About your property', required: true });
  }
  if (!flags.rooms_complete) {
    items.push({ key: 'rooms', label: 'Room configuration', required: true });
  }
  if (!flags.pricing_complete) {
    items.push({ key: 'pricing', label: 'Pricing', required: true });
  }
  if (!flags.photos_complete) {
    items.push({
      key: 'photos',
      label: `${SUBMIT_MIN_PHOTOS} photos`,
      required: true,
    });
  }
  if (!flags.walkthrough_complete) {
    items.push({ key: 'walkthrough', label: 'Walkthrough video', required: false });
  }
  if (!flags.photos_quality_complete) {
    items.push({
      key: 'photos_quality',
      label: `${QUALITY_TARGET_PHOTOS} photos (recommended)`,
      required: false,
    });
  }
  if (!flags.amenities_complete) {
    items.push({ key: 'amenities', label: 'Amenities', required: false });
  }
  if (!flags.house_rules_complete) {
    items.push({ key: 'house_rules', label: 'House rules', required: false });
  }
  return items;
}

import { Inject, Injectable, Logger, Optional } from '@nestjs/common';
import { createHmac, randomBytes } from 'crypto';
import { isProductionRuntime, requirePublicBaseUrl } from '../../../common/security/secrets';

/** Optional Nest token so unit tests can inject a mock fetch without Nest DI. */
export const CMI_FETCH = 'CMI_FETCH';

export interface CmiOrderResult {
  provider: 'cmi';
  provider_intent_id: string;
  redirect_url: string;
  amount: number;
  currency: string;
}

export type CmiMerchantOp = 'PostAuth' | 'Void' | 'Credit';

export interface CmiMerchantResult {
  ok: boolean;
  op: CmiMerchantOp;
  providerIntentId: string;
  procReturnCode: string;
  raw?: string;
  error?: string;
}

function getCmiStoreKey(): string {
  const key = (process.env.CMI_STORE_KEY ?? '').trim();
  if (key) return key;
  if (isProductionRuntime() || process.env.STAYS_PAYMENT_PROVIDER === 'cmi') {
    throw new Error(
      'CMI_STORE_KEY is required when using CMI payments (set via environment variables).',
    );
  }
  return 'mock-store-key';
}

function getCmiClientId(): string {
  const id = (process.env.CMI_CLIENT_ID ?? '').trim();
  if (id) return id;
  if (isProductionRuntime() || process.env.STAYS_PAYMENT_PROVIDER === 'cmi') {
    throw new Error(
      'CMI_CLIENT_ID is required when using CMI payments (set via environment variables).',
    );
  }
  return 'mock-client';
}

/** Server-to-server merchant API (NestPay/CMI-style). Distinct from the 3D gate URL. */
export function getCmiApiUrl(env: NodeJS.ProcessEnv = process.env): string {
  const configured = (env.CMI_API_URL ?? '').trim();
  if (configured) return configured.replace(/\/$/, '');
  // Test gate host uses /fim/api for PostAuth/Void/Credit.
  const paymentUrl = (env.CMI_PAYMENT_URL ?? '').trim();
  if (paymentUrl.includes('est3Dgate')) {
    return paymentUrl.replace(/\/fim\/est3Dgate\/?$/i, '/fim/api');
  }
  return 'https://testpayment.cmi.co.ma/fim/api';
}

export type CmiFetch = (
  input: string,
  init?: RequestInit,
) => Promise<Response>;

@Injectable()
export class CmiPaymentProvider {
  private readonly logger = new Logger(CmiPaymentProvider.name);
  private readonly fetchImpl: CmiFetch;

  constructor(@Optional() @Inject(CMI_FETCH) fetchImpl?: CmiFetch) {
    this.fetchImpl = fetchImpl ?? fetch;
  }

  createOrder(input: {
    bookingId: string;
    amount: number;
    currency: string;
    guestUserId: string;
  }): CmiOrderResult {
    const clientId = getCmiClientId();
    const storeKey = getCmiStoreKey();
    const baseUrl =
      process.env.CMI_PAYMENT_URL ||
      'https://testpayment.cmi.co.ma/fim/est3Dgate';
    const callbackUrl =
      process.env.CMI_CALLBACK_URL ||
      `${requirePublicBaseUrl('STAYS_PUBLIC_URL', 'http://127.0.0.1:3002')}/api/v1/stays/webhooks/payments/cmi`;
    const okUrl =
      process.env.CMI_OK_URL ||
      `${requirePublicBaseUrl('STAYS_WEB_URL', 'http://127.0.0.1:3000')}/bookings`;
    const failUrl =
      process.env.CMI_FAIL_URL ||
      `${requirePublicBaseUrl('STAYS_WEB_URL', 'http://127.0.0.1:3000')}/bookings`;

    const orderId = `STAYS-${input.bookingId}-${Date.now()}`;
    const amount = input.amount.toFixed(2);
    const rnd = randomBytes(8).toString('hex');

    const hashPlain = [
      clientId,
      orderId,
      amount,
      input.currency,
      okUrl,
      failUrl,
      'PreAuth',
      rnd,
      storeKey,
    ].join('|');

    const hash = createHmac('sha512', storeKey).update(hashPlain).digest('base64');

    const params = new URLSearchParams({
      clientid: clientId,
      oid: orderId,
      amount,
      currency: input.currency,
      okUrl,
      failUrl,
      callbackUrl,
      TranType: 'PreAuth',
      rnd,
      hash,
      email: '',
      BillToName: input.guestUserId,
      lang: 'fr',
    });

    return {
      provider: 'cmi',
      provider_intent_id: orderId,
      redirect_url: `${baseUrl}?${params.toString()}`,
      amount: input.amount,
      currency: input.currency,
    };
  }

  verifyCallback(body: Record<string, unknown>): {
    valid: boolean;
    providerIntentId?: string;
    success: boolean;
  } {
    // Always verify HMAC — never accept unsigned callbacks (fail closed).
    const storeKey = getCmiStoreKey();
    const oid = String(body.oid ?? body.OID ?? '');
    const amount = String(body.amount ?? '');
    const procReturnCode = String(
      body.ProcReturnCode ?? body.procReturnCode ?? '',
    );
    const hashFromGateway = String(body.HASH ?? body.hash ?? '');

    if (!hashFromGateway || !oid) {
      return { valid: false, providerIntentId: oid || undefined, success: false };
    }

    const hashPlain = [oid, storeKey, procReturnCode, amount].join('|');
    const expected = createHmac('sha512', storeKey)
      .update(hashPlain)
      .digest('base64');
    const valid = expected === hashFromGateway;
    return {
      valid,
      providerIntentId: oid || undefined,
      success: valid && procReturnCode === '00',
    };
  }

  /** Capture a successful PreAuth (PostAuth). */
  async capture(input: {
    providerIntentId: string;
    amount: number;
    currency: string;
  }): Promise<CmiMerchantResult> {
    return this.merchantRequest('PostAuth', input);
  }

  /** Release an unpaid PreAuth hold. */
  async voidAuthorization(input: {
    providerIntentId: string;
  }): Promise<CmiMerchantResult> {
    return this.merchantRequest('Void', {
      providerIntentId: input.providerIntentId,
      amount: 0,
      currency: 'MAD',
      omitAmount: true,
    });
  }

  /** Credit/refund after capture. */
  async refund(input: {
    providerIntentId: string;
    amount: number;
    currency: string;
  }): Promise<CmiMerchantResult> {
    return this.merchantRequest('Credit', input);
  }

  /**
   * NestPay/CMI merchant API: form POST with HASH.
   * Hash material: ClientId|OrderId|Amount|Currency|storeKey (Amount empty for Void).
   */
  async merchantRequest(
    op: CmiMerchantOp,
    input: {
      providerIntentId: string;
      amount: number;
      currency: string;
      omitAmount?: boolean;
    },
  ): Promise<CmiMerchantResult> {
    const clientId = getCmiClientId();
    const storeKey = getCmiStoreKey();
    const amount = input.omitAmount ? '' : Number(input.amount).toFixed(2);
    const currency = input.omitAmount ? '' : input.currency;
    const hashPlain = [clientId, input.providerIntentId, amount, currency, storeKey].join(
      '|',
    );
    const hash = createHmac('sha512', storeKey).update(hashPlain).digest('base64');

    const body = new URLSearchParams({
      CLIENTID: clientId,
      ORDERID: input.providerIntentId,
      NAME: op,
      TYPE: op,
      HASH: hash,
    });
    if (!input.omitAmount) {
      body.set('AMOUNT', amount);
      body.set('currency', currency);
    }

    const apiUrl = getCmiApiUrl();
    try {
      const res = await this.fetchImpl(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      });
      const raw = await res.text();
      const procReturnCode = parseProcReturnCode(raw);
      const ok = res.ok && procReturnCode === '00';
      if (!ok) {
        this.logger.warn(
          `CMI ${op} failed for ${input.providerIntentId}: HTTP ${res.status} code=${procReturnCode}`,
        );
      }
      return {
        ok,
        op,
        providerIntentId: input.providerIntentId,
        procReturnCode,
        raw: raw.slice(0, 2000),
        error: ok ? undefined : `CMI_${op}_FAILED`,
      };
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.logger.error(`CMI ${op} network error: ${message}`);
      return {
        ok: false,
        op,
        providerIntentId: input.providerIntentId,
        procReturnCode: '',
        error: message,
      };
    }
  }
}

function parseProcReturnCode(raw: string): string {
  const xml = /<ProcReturnCode>([^<]*)<\/ProcReturnCode>/i.exec(raw);
  if (xml?.[1]) return xml[1].trim();
  const form = /(?:^|[&\n])ProcReturnCode=([^&\n\r]*)/i.exec(raw);
  if (form?.[1]) return decodeURIComponent(form[1].trim());
  try {
    const json = JSON.parse(raw) as { ProcReturnCode?: string; procReturnCode?: string };
    return String(json.ProcReturnCode ?? json.procReturnCode ?? '').trim();
  } catch {
    return '';
  }
}

