  private assertCanList(userId: string) {
    return this.hostsService.canList(userId).then(async (canList) => {
      if (canList) return;
      const profile = await this.hostsService.getHostProfileOrNull(userId);
      if (profile?.listing_frozen) {
        throw new BadRequestException(
          'Your host account is temporarily frozen. You can still book stays. Contact support to restore listing access.',
        );
      }
      throw new BadRequestException(
        'Host verification required. Your host application must be approved before creating listings.',
      );
    });
  }

  /** Type-first DRAFT create (no media required). */
  async createListing(userId: string, dto: CreateDraftListingDto) {
    await this.assertCanList(userId);
    const hostProfile = await this.hostsService.getHostProfileOrNull(userId);
    const hostName = (hostProfile?.full_name ?? '').trim();
    const hostPhone = (hostProfile?.phone ?? '').trim();

    const defaultBookingModel =
      dto.listing_type === 'HOTEL'
        ? 'ROOM_TYPES'
        : dto.listing_type === 'HOSTEL'
          ? 'DORM_AND_PRIVATE'
          : 'ENTIRE_PROPERTY';

    const propertyDetails = {
      ...(dto.property_details ?? {}),
      ...(dto.guest_house ? { guest_house: true } : {}),
    };

    return this.dataSource.transaction(async (manager) => {
      const listingRepo = manager.getRepository(StaysListing);
      const rulesRepo = manager.getRepository(StaysListingRules);
      const ratePlanRepo = manager.getRepository(StaysRatePlan);
      const checkInRepo = manager.getRepository(StaysCheckInContact);
      const unitTypeRepo = manager.getRepository(StaysListingUnitType);

      const now = new Date();
      const listing = listingRepo.create({
        host_user_id: userId,
        title: 'Untitled listing',
        listing_type: dto.listing_type,
        booking_model: defaultBookingModel,
        city: '',
        country: 'MA',
        neighborhood: null,
        postal_code: null,
        building_name: null,
        landmark: null,
        address_encrypted: null,
        geo_lat: null,
        geo_lng: null,
        property_details: propertyDetails,
        safety_features: {},
        policies: {},
        status: 'DRAFT',
        checkin_time: '14:00',
        checkout_time: '11:00',
        description: null,
        instant_booking: false,
        last_edited_at: now,
        archived_at: null,
      });
      await listingRepo.save(listing);

      await rulesRepo.save(
        rulesRepo.create({
          listing_id: listing.id,
          pets_policy: 'NO',
          smoking_policy: 'NOT_ALLOWED',
          quiet_hours: false,
          couples_welcome: true,
          max_guests: 2,
          amenities: [],
          cancellation_policy: 'MODERATE',
        }),
      );

      await ratePlanRepo.save(
        ratePlanRepo.create({
          listing_id: listing.id,
          currency: 'MAD',
          base_price: 0,
          weekend_price: null,
          deposit_policy_text: null,
        }),
      );

      await checkInRepo.save(
        checkInRepo.create({
          listing_id: listing.id,
          full_name: hostName,
          phone_encrypted: hostPhone,
          role: 'OWNER',
          access_instructions: null,
        }),
      );

      if (!roomsRequiredForType(dto.listing_type, defaultBookingModel)) {
        const kind =
          dto.listing_type === 'VILLA'
            ? ('VILLA_UNIT' as const)
            : dto.listing_type === 'RIAD'
              ? ('RIAD_ROOM' as const)
              : ('APARTMENT_UNIT' as const);
        await unitTypeRepo.save(
          unitTypeRepo.create({
            listing_id: listing.id,
            kind,
            name: 'Entire place',
            quantity: 1,
            max_guests: 2,
            bed_config: [],
            size_sqm: null,
            amenities: [],
            pricing_unit: 'NIGHT',
            base_price: 0,
            currency: 'MAD',
            details: {},
            sort_order: 0,
            is_active: true,
          }),
        );
      }

      return {
        id: listing.id,
        status: 'DRAFT' as const,
        message: 'Draft listing created. Continue editing to submit for review.',
      };
    });
  }

  /** Legacy full create kept for compatibility — prefer createListing draft + submit. */
  async createListingLegacy(userId: string, dto: CreateHostListingDto) {
    const draft = await this.createListing(userId, {
      listing_type: dto.listing_type,
      property_details: dto.property_details,
    });
    await this.updateListing(userId, draft.id, {
      title: dto.title,
      city: dto.city,
      neighborhood: dto.neighborhood,
      address: dto.address,
      geo_lat: dto.geo_lat,
      geo_lng: dto.geo_lng,
      description: dto.description,
      checkin_time: dto.checkin_time,
      checkout_time: dto.checkout_time,
      instant_booking: dto.instant_booking,
      property_details: dto.property_details,
      rules: dto.rules,
      rate_plan: dto.rate_plan,
      check_in_contact: dto.check_in_contact,
    });
    if (dto.media?.length) {
      await this.replaceListingMedia(userId, draft.id, { media: dto.media });
    }
    return this.submitListing(userId, draft.id);
  }

  async replaceListingMedia(
    userId: string,
    listingId: string,
    dto: ReplaceListingMediaDto,
  ) {
    await this.assertCanList(userId);
    const listing = await this.requireOwnedListing(userId, listingId, ['media']);
    if (!EDITABLE_STATUSES.includes(listing.status)) {
      throw new BadRequestException(
        'Media cannot be changed in the current listing status.',
      );
    }
    for (const m of dto.media) {
      await this.assertOwnedListingAsset(userId, m.asset_id, m.kind);
    }

    await this.dataSource.transaction(async (manager) => {
      const mediaRepo = manager.getRepository(StaysListingMedia);
      await mediaRepo.delete({ listing_id: listingId });
      for (let i = 0; i < dto.media.length; i++) {
        const m = dto.media[i];
        await mediaRepo.save(
          mediaRepo.create({
            listing_id: listingId,
            kind: m.kind,
            asset_id: m.asset_id,
            sort_order: m.sort_order ?? i,
            is_required: m.kind === 'WALKTHROUGH',
            category: m.category ?? null,
            is_cover: m.is_cover ?? false,
          }),
        );
      }
      await manager.getRepository(StaysListing).update(listingId, {
        last_edited_at: new Date(),
      });
    });

    return this.getHostListingById(userId, listingId);
  }

  async replaceListingUnitTypes(
    userId: string,
    listingId: string,
    dto: { unit_types: Array<{
      kind: string;
      name: string;
      quantity?: number;
      max_guests?: number;
      base_price: number;
      currency?: string;
      pricing_unit?: string;
      amenities?: string[];
      bed_config?: unknown[];
      size_sqm?: number;
      details?: Record<string, unknown>;
      sort_order?: number;
      is_active?: boolean;
    }> },
  ) {
    await this.assertCanList(userId);
    const listing = await this.requireOwnedListing(userId, listingId);
    if (!EDITABLE_STATUSES.includes(listing.status)) {
      throw new BadRequestException(
        'Unit types cannot be changed in the current listing status.',
      );
    }
    if (
      (listing.status === 'LIVE' || listing.status === 'APPROVED') &&
      dto.unit_types.length === 0
    ) {
      throw new BadRequestException(
        'Live or approved listings must keep at least one unit type.',
      );
    }

    await this.dataSource.transaction(async (manager) => {
      const unitRepo = manager.getRepository(StaysListingUnitType);
      await unitRepo.delete({ listing_id: listingId });
      for (let i = 0; i < dto.unit_types.length; i++) {
        const u = dto.unit_types[i];
        const details = { ...(u.details ?? {}) };
        const bedFromDetails = details.bed_config;
        const sizeFromDetails = details.size_sqm;
        delete details.bed_config;
        delete details.size_sqm;
        const bedConfig = Array.isArray(u.bed_config)
          ? u.bed_config
          : Array.isArray(bedFromDetails)
            ? bedFromDetails
            : typeof bedFromDetails === 'string' && bedFromDetails.trim()
              ? [{ summary: bedFromDetails.trim() }]
              : [];
        const sizeRaw =
          u.size_sqm != null
            ? u.size_sqm
            : sizeFromDetails != null && Number.isFinite(Number(sizeFromDetails))
              ? Number(sizeFromDetails)
              : null;
        await unitRepo.save(
          unitRepo.create({
            listing_id: listingId,
            kind: u.kind as StaysListingUnitType['kind'],
            name: u.name,
            quantity: u.quantity ?? 1,
            max_guests: u.max_guests ?? 2,
            bed_config: bedConfig,
            size_sqm: sizeRaw != null && Number.isFinite(Number(sizeRaw))
              ? Number(sizeRaw)
              : null,
            amenities: u.amenities ?? [],
            pricing_unit: (u.pricing_unit as StaysListingUnitType['pricing_unit']) ?? 'NIGHT',
            base_price: u.base_price,
            currency: u.currency ?? 'MAD',
            details,
            sort_order: u.sort_order ?? i,
            is_active: u.is_active ?? true,
          }),
        );
      }
      const minPrice =
        dto.unit_types.length > 0
          ? Math.min(...dto.unit_types.map((x) => x.base_price))
          : 0;
      await manager.getRepository(StaysRatePlan).update(
        { listing_id: listingId },
        { base_price: minPrice },
      );
      await manager.getRepository(StaysListing).update(listingId, {
        last_edited_at: new Date(),
      });
    });

    return this.getHostListingById(userId, listingId);
  }

  async submitListing(userId: string, listingId: string) {
    await this.assertCanList(userId);
    const listing = await this.requireOwnedListing(userId, listingId, [
      'rate_plan',
      'rules',
      'media',
      'unit_types',
      'check_in_contact',
    ]);
    if (listing.status !== 'DRAFT' && listing.status !== 'REJECTED') {
      throw new BadRequestException(
        'Only draft listings (or listings that need changes) can be submitted.',
      );
    }
    if (listing.archived_at) {
      throw new BadRequestException('This draft has been archived.');
    }

    const completion = this.completionPayload(listing);
    const err = assertCanSubmit(completion.completion_flags);
    if (err) throw new BadRequestException(err);

    // Hotel/hostel: each unit must have price > 0
    if (
      roomsRequiredForType(listing.listing_type, listing.booking_model) &&
      (listing.unit_types || []).some((u) => Number(u.base_price) <= 0)
    ) {
      throw new BadRequestException(
        'Each room type needs a price greater than zero.',
      );
    }

    listing.status = 'SUBMITTED';
    listing.last_edited_at = new Date();
    await this.listingRepo.save(listing);

    return {
      id: listing.id,
      status: 'SUBMITTED' as const,
      message:
        'Listing submitted for review. Our team will review it within 1–2 business days.',
      completion_percentage: completion.completion_percentage,
    };
  }

  // --- media uploads (MediaStorageService) ---
  private listingMediaCandidates(
    userId: string,
    assetId: string,
    kind: string,
  ): string[] {
    const prefixes =
      kind === 'WALKTHROUGH'
        ? [`walkthrough_${assetId}`]
        : [`photo_${assetId}`];
    const exts =
      kind === 'WALKTHROUGH'
        ? ['.mp4', '.webm']
        : ['.jpg', '.jpeg', '.png', '.webp'];
    const keys: string[] = [];
    for (const prefix of prefixes) {
      for (const ext of exts) {
        keys.push(`host/${userId}/listing/${prefix}${ext}`);
      }
    }
    return keys;
  }

  private async assertOwnedListingAsset(
    userId: string,
    assetId: string,
    kind: string,
  ): Promise<void> {
    const found = await this.mediaStorage.resolveFirstExisting(
      this.listingMediaCandidates(userId, assetId, kind),
    );
    if (!found) {
      throw new BadRequestException(
        'Invalid media asset_id — upload the file first as this host',
      );
    }
  }

  async uploadListingPhoto(
    userId: string,
    file: Express.Multer.File | undefined,
  ): Promise<{ asset_id: string }> {
    if (!file || !file.buffer || file.buffer.length === 0) {
      throw new BadRequestException('No file uploaded');
    }
    if (file.size > MAX_PHOTO_SIZE) {
      throw new BadRequestException(`Photo too large. Max ${MAX_PHOTO_SIZE / 1024 / 1024}MB`);
    }
    const detected = detectImageType(file.buffer);
    if (!detected) {
      throw new BadRequestException('Invalid image. Use JPEG, PNG, or WebP');
    }
    const ext = detected === 'png' ? '.png' : detected === 'webp' ? '.webp' : '.jpg';
    const mime =
      detected === 'png'
        ? 'image/png'
        : detected === 'webp'
          ? 'image/webp'
          : 'image/jpeg';
    const assetId = randomUUID();
    await this.mediaStorage.store({
      buffer: file.buffer,
      relativeKey: `host/${userId}/listing/photo_${assetId}${ext}`,
      mimeType: mime,
      assetId,
    });
    return { asset_id: assetId };
  }

  async uploadListingWalkthrough(
    userId: string,
    file: Express.Multer.File | undefined,
  ): Promise<{ asset_id: string }> {
    if (!file || !file.buffer || file.buffer.length === 0) {
      throw new BadRequestException('No file uploaded');
    }
    if (file.size > MAX_VIDEO_SIZE) {
      throw new BadRequestException(`Video too large. Max ${MAX_VIDEO_SIZE / 1024 / 1024}MB`);
    }
    const detected = detectVideoType(file.buffer);
    if (!detected) {
      throw new BadRequestException(
        'Invalid video file. Only MP4/MOV (ftyp) or WebM are allowed.',
      );
    }
    const assetId = randomUUID();
    const ext = detected === 'webm' ? '.webm' : '.mp4';
    const mime = detected === 'webm' ? 'video/webm' : 'video/mp4';
    await this.mediaStorage.store({
      buffer: file.buffer,
      relativeKey: `host/${userId}/listing/walkthrough_${assetId}${ext}`,
      mimeType: mime,
      assetId,
    });
    return { asset_id: assetId };
  }
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { EntityManager, Repository } from 'typeorm';
import { StaysBooking } from '../entities/stays-booking.entity';
import { StaysAvailabilityBlock } from '../entities/stays-availability-block.entity';

/** Statuses that occupy listing nights (hotel model: [checkin, checkout)).
 * Must match DB EXCLUDE predicate on ex_stays_bookings_active_overlap.
 * COMPLETED does not occupy inventory (stay already ended). */
export const BOOKED_STATUSES = [
  'INITIATED',
  'PAYMENT_PENDING',
  'CONFIRMED',
  'CHECKED_IN',
] as const;

export type BookedStatus = (typeof BOOKED_STATUSES)[number];

export type BlockedDateRange = {
  checkin_date: string;
  checkout_date: string;
  source: 'BOOKING' | 'BLOCK';
};

@Injectable()
export class StaysAvailabilityService {
  constructor(
    @InjectRepository(StaysBooking)
    private readonly bookingRepo: Repository<StaysBooking>,
    @InjectRepository(StaysAvailabilityBlock)
    private readonly availabilityRepo: Repository<StaysAvailabilityBlock>,
  ) {}

  /**
   * Returns listing IDs that are NOT available for the given date range.
   * A listing is unavailable if:
   * 1. It has an overlapping active/paid booking (incl. pending payment holds)
   * 2. It has any blocked date in the range (stays_availability_blocks.is_blocked = true)
   */
  async getUnavailableListingIds(
    checkinDate: Date | string,
    checkoutDate: Date | string,
    listingIds?: string[],
    options?: { excludeBookingId?: string; manager?: EntityManager },
  ): Promise<string[]> {
    const checkin = this.toDateString(checkinDate);
    const checkout = this.toDateString(checkoutDate);
    const bookingRepo = options?.manager
      ? options.manager.getRepository(StaysBooking)
      : this.bookingRepo;
    const availabilityRepo = options?.manager
      ? options.manager.getRepository(StaysAvailabilityBlock)
      : this.availabilityRepo;

    const bookingQb = bookingRepo
      .createQueryBuilder('b')
      .select('DISTINCT b.listing_id', 'listing_id')
      .where('b.status IN (:...statuses)', { statuses: [...BOOKED_STATUSES] })
      .andWhere('b.checkin_date < :checkout', { checkout })
      .andWhere('b.checkout_date > :checkin', { checkin });

    if (listingIds?.length) {
      bookingQb.andWhere('b.listing_id IN (:...listingIds)', { listingIds });
    }
    if (options?.excludeBookingId) {
      bookingQb.andWhere('b.id != :excludeBookingId', {
        excludeBookingId: options.excludeBookingId,
      });
    }

    const unavailableFromBookings = await bookingQb
      .getRawMany<{ listing_id: string }>()
      .then((rows) =>
        rows
          .map((r) => r.listing_id)
          .filter((id): id is string => typeof id === 'string' && id.length > 0),
      );

    const blocksQb = availabilityRepo
      .createQueryBuilder('ab')
      .select('DISTINCT ab.listing_id', 'listing_id')
      .where('ab.is_blocked = true')
      .andWhere('ab.date >= :checkin', { checkin })
      .andWhere('ab.date < :checkout', { checkout });

    if (listingIds?.length) {
      blocksQb.andWhere('ab.listing_id IN (:...listingIds)', { listingIds });
    }

    const unavailableFromBlocks = await blocksQb
      .getRawMany<{ listing_id: string }>()
      .then((rows) =>
        rows
          .map((r) => r.listing_id)
          .filter((id): id is string => typeof id === 'string' && id.length > 0),
      );

    return [...new Set([...unavailableFromBookings, ...unavailableFromBlocks])];
  }

  /**
   * Check if a specific listing is available for the date range.
   */
  async isListingAvailable(
    listingId: string,
    checkinDate: Date | string,
    checkoutDate: Date | string,
    options?: { excludeBookingId?: string; manager?: EntityManager },
  ): Promise<boolean> {
    const checkin = this.toDateString(checkinDate);
    const checkout = this.toDateString(checkoutDate);
    const bookingRepo = options?.manager
      ? options.manager.getRepository(StaysBooking)
      : this.bookingRepo;
    const availabilityRepo = options?.manager
      ? options.manager.getRepository(StaysAvailabilityBlock)
      : this.availabilityRepo;

    const bookingQb = bookingRepo
      .createQueryBuilder('b')
      .where('b.listing_id = :listingId', { listingId })
      .andWhere('b.status IN (:...statuses)', { statuses: [...BOOKED_STATUSES] })
      .andWhere('b.checkin_date < :checkout', { checkout })
      .andWhere('b.checkout_date > :checkin', { checkin });

    if (options?.excludeBookingId) {
      bookingQb.andWhere('b.id != :excludeBookingId', {
        excludeBookingId: options.excludeBookingId,
      });
    }

    const overlappingBookings = await bookingQb.getCount();
    if (overlappingBookings > 0) return false;

    const blockedNights = await availabilityRepo
      .createQueryBuilder('ab')
      .where('ab.listing_id = :listingId', { listingId })
      .andWhere('ab.is_blocked = true')
      .andWhere('ab.date >= :checkin', { checkin })
      .andWhere('ab.date < :checkout', { checkout })
      .getCount();

    return blockedNights === 0;
  }

  /**
   * Occupied night ranges for a listing (for calendar UI).
   * Nights are [checkin_date, checkout_date) — checkout day is free for a new arrival.
   */
  async getBlockedDateRanges(
    listingId: string,
    fromDate: Date | string,
    toDate: Date | string,
  ): Promise<BlockedDateRange[]> {
    const from = this.toDateString(fromDate);
    const to = this.toDateString(toDate);

    const bookings = await this.bookingRepo
      .createQueryBuilder('b')
      .select(['b.checkin_date', 'b.checkout_date'])
      .where('b.listing_id = :listingId', { listingId })
      .andWhere('b.status IN (:...statuses)', { statuses: [...BOOKED_STATUSES] })
      .andWhere('b.checkin_date < :to', { to })
      .andWhere('b.checkout_date > :from', { from })
      .getMany();

    const ranges: BlockedDateRange[] = bookings.map((b) => ({
      checkin_date: this.toDateString(b.checkin_date),
      checkout_date: this.toDateString(b.checkout_date),
      source: 'BOOKING' as const,
    }));

    const blocks = await this.availabilityRepo
      .createQueryBuilder('ab')
      .select(['ab.date'])
      .where('ab.listing_id = :listingId', { listingId })
      .andWhere('ab.is_blocked = true')
      .andWhere('ab.date >= :from', { from })
      .andWhere('ab.date < :to', { to })
      .getMany();

    for (const block of blocks) {
      const night = this.toDateString(block.date);
      ranges.push({
        checkin_date: night,
        checkout_date: this.addDays(night, 1),
        source: 'BLOCK',
      });
    }

    return ranges;
  }

  /** Calendar-safe YYYY-MM-DD (no UTC day shift). */
  toDateString(d: Date | string): string {
    if (typeof d === 'string') {
      const match = /^(\d{4}-\d{2}-\d{2})/.exec(d.trim());
      if (match) return match[1];
      const parsed = new Date(d);
      if (!Number.isNaN(parsed.getTime())) {
        return this.formatLocalDate(parsed);
      }
      return d.split('T')[0];
    }
    return this.formatLocalDate(d);
  }

  private formatLocalDate(d: Date): string {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }

  private addDays(isoDate: string, days: number): string {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(isoDate);
    if (!match) return isoDate;
    const d = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
    d.setDate(d.getDate() + days);
    return this.formatLocalDate(d);
  }
}

