  async exportHostBookingsCsv(
    hostUserId: string,
    query: {
      format?: string;
      period?: string;
      from?: string;
      to?: string;
      listing_id?: string;
      status?: string;
    },
  ): Promise<{ csv: string; filename: string }> {
    const format = (query.format || 'csv').toLowerCase();
    if (format !== 'csv') {
      throw new BadRequestException('Unsupported format');
    }

    const period = (query.period || 'all').toLowerCase();
    if (!['last_30_days', 'this_year', 'all', 'custom'].includes(period)) {
      throw new BadRequestException('Invalid period');
    }

    let fromDate: string | undefined;
    let toDate: string | undefined;
    const today = new Date();
    const todayIso = formatCsvDate(today);

    if (period === 'last_30_days') {
      const from = new Date(
        Date.UTC(
          today.getUTCFullYear(),
          today.getUTCMonth(),
          today.getUTCDate() - 29,
        ),
      );
      fromDate = formatCsvDate(from);
      toDate = todayIso;
    } else if (period === 'this_year') {
      fromDate = `${today.getUTCFullYear()}-01-01`;
      toDate = todayIso;
    } else if (period === 'custom') {
      if (!query.from || !query.to) {
        throw new BadRequestException(
          'Custom period requires from and to (YYYY-MM-DD)',
        );
      }
      if (
        !/^\d{4}-\d{2}-\d{2}$/.test(query.from) ||
        !/^\d{4}-\d{2}-\d{2}$/.test(query.to)
      ) {
        throw new BadRequestException('from and to must be YYYY-MM-DD');
      }
      if (query.from > query.to) {
        throw new BadRequestException('from must be on or before to');
      }
      fromDate = query.from;
      toDate = query.to;
    }

    const qb = this.bookingRepo
      .createQueryBuilder('b')
      .innerJoinAndSelect('b.listing', 'listing')
      .leftJoinAndSelect('b.occupants', 'occupants')
      .where('listing.host_user_id = :hostUserId', { hostUserId });

    if (fromDate) {
      qb.andWhere('b.checkin_date >= :fromDate', { fromDate });
    }
    if (toDate) {
      qb.andWhere('b.checkin_date <= :toDate', { toDate });
    }
    if (query.listing_id) {
      qb.andWhere('b.listing_id = :listingId', { listingId: query.listing_id });
    }
    if (query.status) {
      qb.andWhere('b.status = :status', { status: query.status });
    }

    qb.orderBy('b.created_at', 'DESC');
    const bookings = await qb.getMany();

    const headers = [
      'Booking Reference',
      'Internal ID',
      'Guest Name',
      'Listing',
      'City',
      'Check-in',
      'Check-out',
      'Nights',
      'Guests',
      'Status',
      'Currency',
      'Guest Total',
      'Platform Commission',
      'Host Payout',
      'Created At',
      'Completed At',
    ];

    const rows = bookings.map((b) => {
      const hostFee = Number(b.host_fee ?? 0);
      const subtotal = Number(b.total_subtotal ?? 0);
      const payout =
        b.payout_amount != null
          ? Number(b.payout_amount)
          : Math.max(0, subtotal - hostFee);
      const guestTotal = b.total_paid != null ? Number(b.total_paid) : '';

      return [
        b.booking_reference ?? '',
        b.id,
        this.resolveGuestDisplayName(b) ?? '',
        b.listing?.title ?? '',
        b.listing?.city ?? '',
        formatCsvDate(b.checkin_date),
        formatCsvDate(b.checkout_date),
        bookingNights(b.checkin_date, b.checkout_date),
        b.guest_count,
        b.status,
        b.currency,
        guestTotal,
        hostFee,
        payout,
        formatCsvTimestamp(b.created_at),
        formatCsvTimestamp(b.completed_at),
      ];
    });

    let filename = 'nexa-bookings-all.csv';
    if (period === 'last_30_days') filename = 'nexa-bookings-last-30-days.csv';
    else if (period === 'this_year') filename = 'nexa-bookings-this-year.csv';
    else if (period === 'custom' && fromDate && toDate) {
      filename = `nexa-bookings-${fromDate}-to-${toDate}.csv`;
    }

    return { csv: buildCsv(headers, rows), filename };
  }

  private resolveGuestDisplayName(booking: StaysBooking): string | null {
    const occupants = booking.occupants ?? [];
    if (occupants.length > 0) {
      const primary =
        occupants.find((o) => o.is_primary) ??
        occupants.find((o) => o.full_name?.trim()) ??
        occupants[0];
      const name = primary?.full_name?.trim();
      if (name) return name;
    }
    return null;
  }

  private resolveGuestPhone(booking: StaysBooking): string | null {
    const occupants = booking.occupants ?? [];
    const primary =
      occupants.find((o) => o.is_primary) ??
      occupants.find((o) => o.phone?.trim()) ??
      occupants[0];
    const phone = primary?.phone?.trim();
    return phone || null;
  }

  private toBookingResponse(
    booking: StaysBooking,
    revealContact = false,
    includeOccupants = false,
    extras: {
      paymentFailed?: boolean;
      has_reviewed?: boolean;
      review_rating?: number;
    } = {},
    hostView = false,
  ) {
    const listing = booking.listing as StaysListing & {
      check_in_contact?: {
        full_name: string;
        phone_encrypted?: string;
        role?: string;
        access_instructions?: string | null;
      };
      media?: Array<{ asset_id: string; kind: string; sort_order?: number }>;
    };
    const contact = listing?.check_in_contact;
    const lifecycleCtx = { paymentFailed: extras.paymentFailed };
    const booking_lifecycle = this.lifecycleService.computeLifecycle(
      booking,
      lifecycleCtx,
    );
    const payment_expires_at =
      booking.status === 'PAYMENT_PENDING' || booking.status === 'INITIATED'
        ? this.lifecycleService.getPaymentExpiresAt(booking.created_at).toISOString()
        : null;

    const ownListing =
      (listing as StaysListing | undefined)?.host_user_id ===
      booking.guest_user_id;
    const can_review =
      !hostView &&
      this.lifecycleService.canReview(booking, lifecycleCtx) &&
      !extras.has_reviewed;
    const review_blocked_reason =
      !hostView &&
      !extras.has_reviewed &&
      booking_lifecycle === 'COMPLETED' &&
      ownListing
        ? ('OWN_LISTING' as const)
        : undefined;

    let review_status: 'NONE' | 'ELIGIBLE' | 'REVIEWED' | 'BLOCKED' = 'NONE';
    if (!hostView && booking_lifecycle === 'COMPLETED') {
      if (extras.has_reviewed) review_status = 'REVIEWED';
      else if (can_review) review_status = 'ELIGIBLE';
      else review_status = 'BLOCKED';
    }

    return {
      id: booking.id,
      booking_reference: booking.booking_reference ?? null,
      listing_id: booking.listing_id,
      status: booking.status,
      booking_lifecycle,
      checkin_date: booking.checkin_date,
      checkout_date: booking.checkout_date,
      guest_count: booking.guest_count,
      total_subtotal: Number(booking.total_subtotal),
      guest_fee: Number(booking.guest_fee),
      ...(hostView
        ? {
            host_fee: Number(booking.host_fee),
            payout_amount: booking.payout_amount
              ? Number(booking.payout_amount)
              : null,
          }
        : {}),
      total_paid: booking.total_paid ? Number(booking.total_paid) : null,
      currency: booking.currency,
      created_at: booking.created_at,
      completed_at: booking.completed_at,
      payment_expires_at,
      payment_failed: !!extras.paymentFailed,
      can_review,
      review_blocked_reason,
      can_complain: this.lifecycleService.canComplain(booking, lifecycleCtx),
      can_cancel: this.lifecycleService.canCancel(booking, lifecycleCtx),
      has_reviewed: !!extras.has_reviewed,
      review_status,
      review_rating:
        extras.has_reviewed && extras.review_rating != null
          ? extras.review_rating
          : undefined,
      listing: listing
        ? {
            id: listing.id,
            title: listing.title,
            city: listing.city,
            checkin_time: listing.checkin_time ?? null,
            checkout_time: listing.checkout_time ?? null,
            address: revealContact && listing.address_encrypted ? listing.address_encrypted : null,
            check_in_instructions:
              revealContact && contact?.access_instructions
                ? contact.access_instructions
                : null,
            check_in_contact:
              revealContact && contact
                ? {
                    full_name: contact.full_name,
                    phone: contact.phone_encrypted ?? '[contact host]',
                    role: contact.role,
                    access_instructions: contact.access_instructions ?? null,
                  }
                : null,
            media: (listing.media || [])
              .sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0))
              .map((m) => ({
                asset_id: m.asset_id,
                kind: m.kind,
                sort_order: m.sort_order ?? 0,
              })),
          }
        : null,
      occupants:
        includeOccupants && booking.occupants?.length
          ? booking.occupants.map((o) => ({
              full_name: o.full_name,
              id_number: o.id_number ?? null,
              is_primary: o.is_primary,
              ...(hostView
                ? {
                    phone: o.phone ?? null,
                    email: o.email ?? null,
                    gender: o.gender ?? null,
                  }
                : {}),
            }))
          : undefined,
    };
  }
}

import { BadRequestException } from '@nestjs/common';

type Ymd = { year: number; month: number; day: number };

/** Parse YYYY-MM-DD components (also accepts trailing time suffixes). */
export function parseBookingYmd(value: string): Ymd {
  const match = /^(\d{4})-(\d{2})-(\d{2})/.exec(value.trim());
  if (!match) {
    throw new BadRequestException('Invalid date format. Use YYYY-MM-DD.');
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  // Validate calendar date via UTC construction (DST-independent).
  const probe = new Date(Date.UTC(year, month - 1, day));
  if (
    probe.getUTCFullYear() !== year ||
    probe.getUTCMonth() !== month - 1 ||
    probe.getUTCDate() !== day
  ) {
    throw new BadRequestException('Invalid date.');
  }
  return { year, month, day };
}

/** Parse YYYY-MM-DD as a local calendar date for DB date columns. */
export function parseBookingDateOnly(value: string): Date {
  const { year, month, day } = parseBookingYmd(value);
  return new Date(year, month - 1, day);
}

/**
 * Authoritative stay length: check-in inclusive, check-out exclusive.
 * Uses UTC calendar midnights so DST cannot change night counts.
 *
 * Examples: 2026-08-10 → 2026-08-11 = 1; 2026-08-10 → 2026-08-12 = 2.
 */
export function bookingNightsBetween(checkin: string, checkout: string): number {
  const a = parseBookingYmd(checkin);
  const b = parseBookingYmd(checkout);
  const ms =
    Date.UTC(b.year, b.month - 1, b.day) -
    Date.UTC(a.year, a.month - 1, a.day);
  return Math.trunc(ms / 86_400_000);
}

export function assertMinOneNightStay(checkin: string, checkout: string): void {
  if (bookingNightsBetween(checkin, checkout) < 1) {
    throw new BadRequestException(
      'Check-out must be at least one night after check-in.',
    );
  }
}

import { bookingNightsBetween } from './booking-date.util';

export function escapeCsv(value: unknown): string {
  if (value == null) return '';
  const stringValue = String(value);
  if (
    stringValue.includes(',') ||
    stringValue.includes('"') ||
    stringValue.includes('\n') ||
    stringValue.includes('\r')
  ) {
    return `"${stringValue.replace(/"/g, '""')}"`;
  }
  return stringValue;
}

export function buildCsv(headers: string[], rows: unknown[][]): string {
  const lines = [
    headers.map(escapeCsv).join(','),
    ...rows.map((row) => row.map(escapeCsv).join(',')),
  ];
  return `\uFEFF${lines.join('\n')}`;
}

export function formatCsvDate(value: Date | string | null | undefined): string {
  if (value == null || value === '') return '';
  if (typeof value === 'string') {
    const m = /^(\d{4}-\d{2}-\d{2})/.exec(value);
    if (m) return m[1];
    const d = new Date(value);
    if (Number.isNaN(d.getTime())) return '';
    return formatUtcDate(d);
  }
  return formatUtcDate(value);
}

export function formatCsvTimestamp(
  value: Date | string | null | undefined,
): string {
  if (value == null || value === '') return '';
  const d = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const hh = String(d.getUTCHours()).padStart(2, '0');
  const mi = String(d.getUTCMinutes()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd} ${hh}:${mi} UTC`;
}

function formatUtcDate(d: Date): string {
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

/** Same rule as bookingNightsBetween; accepts Date values via UTC calendar day. */
export function bookingNights(
  checkin: Date | string,
  checkout: Date | string,
): number {
  const a = typeof checkin === 'string' ? checkin : formatUtcYmd(checkin);
  const b = typeof checkout === 'string' ? checkout : formatUtcYmd(checkout);
  try {
    return Math.max(0, bookingNightsBetween(a, b));
  } catch {
    return 0;
  }
}

function formatUtcYmd(d: Date): string {
  const yyyy = d.getUTCFullYear();
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(d.getUTCDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

/**
 * Host booking list filter / ops-rank SQL — exact parity with
 * nexastays_web/lib/host-booking-center.ts
 * (matchesHostBookingFilter, classifyHostBookingUrgency, URGENCY_RANK).
 *
 * Ops ORDER BY equivalence (proven against client sortHostBookingsForOps):
 *   urgency rank ASC → checkin_date ASC → id ASC
 * using only persisted columns status, checkin_date, checkout_date.
 */

import type { HostBookingFilterParam } from '../dto/host-bookings-list.dto';

export const STAY_ACTIVE_SQL = `('CONFIRMED', 'CHECKED_IN')`;
export const CHECKOUT_ELIGIBLE_SQL = `('CONFIRMED', 'CHECKED_IN', 'COMPLETED')`;
export const PAYMENT_PENDING_SQL = `('INITIATED', 'PAYMENT_PENDING')`;
export const CANCELLED_SQL = `('CANCELLED_BY_GUEST', 'CANCELLED_BY_HOST', 'EXPIRED')`;

/**
 * Urgency rank 0..8 matching URGENCY_RANK — branch order matches
 * classifyHostBookingUrgency (checkout_today before checkin_today, etc.).
 */
export function opsUrgencyRankSql(alias = 'b'): string {
  return `
CASE
  WHEN ${alias}.status IN ${CHECKOUT_ELIGIBLE_SQL}
    AND ${alias}.checkout_date = CAST(:today AS date) THEN 0
  WHEN ${alias}.status IN ${STAY_ACTIVE_SQL}
    AND ${alias}.checkin_date = CAST(:today AS date) THEN 1
  WHEN ${alias}.status IN ${STAY_ACTIVE_SQL}
    AND ${alias}.checkin_date = CAST(:tomorrow AS date) THEN 2
  WHEN ${alias}.status IN ${PAYMENT_PENDING_SQL} THEN 3
  WHEN ${alias}.status IN ${STAY_ACTIVE_SQL}
    AND ${alias}.checkin_date <= CAST(:today AS date)
    AND ${alias}.checkout_date > CAST(:today AS date) THEN 4
  WHEN ${alias}.status IN ${STAY_ACTIVE_SQL}
    AND ${alias}.checkin_date > CAST(:today AS date) THEN 5
  WHEN ${alias}.status = 'COMPLETED' THEN 6
  WHEN ${alias}.status IN ${CANCELLED_SQL} THEN 7
  ELSE 8
END`.replace(/\s+/g, ' ').trim();
}

/** Primary guest display name — parity with resolveGuestDisplayName. */
export function guestDisplayNameSql(bookingAlias = 'b'): string {
  return `COALESCE(
    (SELECT TRIM(o.full_name) FROM stays_booking_occupants o
      WHERE o.booking_id = ${bookingAlias}.id AND o.is_primary = true
      LIMIT 1),
    (SELECT TRIM(o.full_name) FROM stays_booking_occupants o
      WHERE o.booking_id = ${bookingAlias}.id
        AND TRIM(COALESCE(o.full_name, '')) <> ''
      ORDER BY o.id ASC
      LIMIT 1),
    (SELECT TRIM(o.full_name) FROM stays_booking_occupants o
      WHERE o.booking_id = ${bookingAlias}.id
      ORDER BY o.id ASC
      LIMIT 1)
  )`;
}

/**
 * Filter predicates — exact parity with matchesHostBookingFilter.
 * checkin_today excludes checkout_today (classifier checks checkout first).
 */
export function applyHostBookingFilterSql(
  filter: HostBookingFilterParam,
  alias = 'b',
): string | null {
  switch (filter) {
    case 'all':
      return null;
    case 'today':
      return `(
        (
          ${alias}.status IN ${STAY_ACTIVE_SQL}
          AND ${alias}.checkin_date = CAST(:today AS date)
          AND NOT (
            ${alias}.status IN ${CHECKOUT_ELIGIBLE_SQL}
            AND ${alias}.checkout_date = CAST(:today AS date)
          )
        )
        OR (
          ${alias}.status IN ${CHECKOUT_ELIGIBLE_SQL}
          AND ${alias}.checkout_date = CAST(:today AS date)
        )
      )`;
    case 'checkin_today':
      return `(
        ${alias}.status IN ${STAY_ACTIVE_SQL}
        AND ${alias}.checkin_date = CAST(:today AS date)
        AND NOT (
          ${alias}.status IN ${CHECKOUT_ELIGIBLE_SQL}
          AND ${alias}.checkout_date = CAST(:today AS date)
        )
      )`;
    case 'checkout_today':
      return `(
        ${alias}.status IN ${CHECKOUT_ELIGIBLE_SQL}
        AND ${alias}.checkout_date = CAST(:today AS date)
      )`;
    case 'upcoming':
      return `(
        ${alias}.status IN ${STAY_ACTIVE_SQL}
        AND ${alias}.checkin_date > CAST(:today AS date)
      )`;
    case 'current':
      // staying OR (checkin_today && checkout > today)
      // ≡ STAY_ACTIVE && checkin <= today && checkout > today
      // (checkout_today has checkout = today, so excluded)
      return `(
        ${alias}.status IN ${STAY_ACTIVE_SQL}
        AND ${alias}.checkin_date <= CAST(:today AS date)
        AND ${alias}.checkout_date > CAST(:today AS date)
      )`;
    case 'awaiting_payment':
      return `(${alias}.status IN ${PAYMENT_PENDING_SQL})`;
    case 'completed':
      return `(${alias}.status = 'COMPLETED')`;
    case 'cancelled':
      return `(${alias}.status IN ${CANCELLED_SQL})`;
    default:
      return null;
  }
}

export function escapeIlikePattern(raw: string): string {
  return raw.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

import { BadRequestException } from '@nestjs/common';
import { createHmac, timingSafeEqual } from 'crypto';

/**
 * Context-bound, HMAC-signed opaque cursors for host list pagination.
 * Payload binds host + query dimensions so reuse under another filter/sort fails.
 */

export type HostListCursorKind = 'bookings' | 'listings';

export type HostListCursorPayload = {
  v: 1;
  kind: HostListCursorKind;
  hostId: string;
  sort: string;
  filter: string;
  search: string;
  listingId: string;
  status: string;
  /** Sort-key tuple for keyset (string|number|null). */
  keys: Record<string, string | number | null>;
  id: string;
};

export type HostListCursorContext = {
  kind: HostListCursorKind;
  hostId: string;
  sort: string;
  filter?: string;
  search?: string;
  listingId?: string;
  status?: string;
};

function signingSecret(): string {
  const fromEnv =
    process.env.HOST_LIST_CURSOR_SECRET?.trim() ||
    process.env.JWT_SECRET?.trim();
  if (fromEnv) return fromEnv;
  if (process.env.NODE_ENV === 'production') {
    throw new Error(
      'HOST_LIST_CURSOR_SECRET or JWT_SECRET is required in production for list cursors.',
    );
  }
  return 'nexa-host-list-cursor-dev';
}

function b64urlEncode(buf: Buffer | string): string {
  const b = typeof buf === 'string' ? Buffer.from(buf, 'utf8') : buf;
  return b
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function b64urlDecode(s: string): Buffer {
  const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + pad;
  return Buffer.from(b64, 'base64');
}

function normalizeContext(ctx: HostListCursorContext) {
  return {
    kind: ctx.kind,
    hostId: ctx.hostId,
    sort: ctx.sort,
    filter: ctx.filter ?? '',
    search: (ctx.search ?? '').trim().toLowerCase(),
    listingId: ctx.listingId ?? '',
    status: ctx.status ?? '',
  };
}

function signBody(bodyB64: string): string {
  const digest = createHmac('sha256', signingSecret())
    .update(bodyB64)
    .digest();
  return b64urlEncode(digest);
}

export function encodeHostListCursor(
  ctx: HostListCursorContext,
  keys: Record<string, string | number | null>,
  id: string,
): string {
  const norm = normalizeContext(ctx);
  const payload: HostListCursorPayload = {
    v: 1,
    ...norm,
    keys,
    id,
  };
  const bodyB64 = b64urlEncode(JSON.stringify(payload));
  return `${bodyB64}.${signBody(bodyB64)}`;
}

export function decodeHostListCursor(
  cursor: string | undefined | null,
  ctx: HostListCursorContext,
): HostListCursorPayload | null {
  if (cursor == null || cursor === '') return null;
  const parts = cursor.split('.');
  if (parts.length !== 2) {
    throw new BadRequestException('Invalid cursor');
  }
  const [bodyB64, sig] = parts;
  const expected = signBody(bodyB64);
  try {
    const a = Buffer.from(sig);
    const b = Buffer.from(expected);
    if (a.length !== b.length || !timingSafeEqual(a, b)) {
      throw new BadRequestException('Invalid cursor');
    }
  } catch (e) {
    if (e instanceof BadRequestException) throw e;
    throw new BadRequestException('Invalid cursor');
  }

  let payload: HostListCursorPayload;
  try {
    payload = JSON.parse(b64urlDecode(bodyB64).toString('utf8')) as HostListCursorPayload;
  } catch {
    throw new BadRequestException('Invalid cursor');
  }

  if (payload?.v !== 1 || !payload.id || !payload.kind) {
    throw new BadRequestException('Invalid cursor');
  }

  const norm = normalizeContext(ctx);
  if (
    payload.kind !== norm.kind ||
    payload.hostId !== norm.hostId ||
    payload.sort !== norm.sort ||
    payload.filter !== norm.filter ||
    payload.search !== norm.search ||
    payload.listingId !== norm.listingId ||
    payload.status !== norm.status
  ) {
    throw new BadRequestException(
      'Cursor does not match the current list query context',
    );
  }

  return payload;
}

