    | 'ISSUE_FIXED'
    | 'INFORMATION_PROVIDED'
    | 'PAYMENT_RESOLVED'
    | 'BOOKING_UPDATED'
    | 'POLICY_EXPLAINED'
    | 'DUPLICATE'
    | 'NO_ACTION_POSSIBLE'
    | 'OTHER'
    | null;
}

