import type {
  SupportTicketCategory,
  SupportTicketPriority,
} from './entities/stays-support-ticket.entity';

/** Shared PostgreSQL advisory lock for auto-assignment (int4 range). */
export const SUPPORT_ROUTING_ADVISORY_LOCK = 874512031;

export const SUPPORT_ROUTING_SCORE_WEIGHTS = {
  active: 1,
  inProgress: 1.5,
  waiting: 0.5,
  atRisk: 4,
  breached: 8,
} as const;

export const SUPPORT_ROUTING_URGENT_HEADROOM = 0.7;
export const SUPPORT_MAX_ACTIVE_TICKETS_PER_AGENT_DEFAULT = 20;

export type RoutingAgentWorkload = {
  agentId: string;
  assigned: number;
  inProgress: number;
  waiting: number;
  atRisk: number;
  breached: number;
};

export type RoutingAgentSkills = {
  languages: string[];
  categories: string[];
};

export type RoutingSkillTier =
  | 'CATEGORY_AND_LANGUAGE'
  | 'CATEGORY'
  | 'LANGUAGE'
  | 'GENERAL';

export function isSupportAutoAssignEnabled(): boolean {
  const raw = process.env.SUPPORT_AUTO_ASSIGN;
  if (raw == null || raw.trim() === '') return true;
  return !['0', 'false', 'off', 'no'].includes(raw.trim().toLowerCase());
}

export function maxActiveTicketsPerAgent(): number {
  const n = Number(process.env.SUPPORT_MAX_ACTIVE_TICKETS_PER_AGENT);
  if (!Number.isFinite(n) || n < 1) {
    return SUPPORT_MAX_ACTIVE_TICKETS_PER_AGENT_DEFAULT;
  }
  return Math.floor(n);
}

export function emptyWorkload(agentId: string): RoutingAgentWorkload {
  return {
    agentId,
    assigned: 0,
    inProgress: 0,
    waiting: 0,
    atRisk: 0,
    breached: 0,
  };
}

export function calculateRoutingScore(workload: RoutingAgentWorkload): number {
  return (
    workload.assigned * SUPPORT_ROUTING_SCORE_WEIGHTS.active +
    workload.inProgress * SUPPORT_ROUTING_SCORE_WEIGHTS.inProgress +
    workload.waiting * SUPPORT_ROUTING_SCORE_WEIGHTS.waiting +
    workload.atRisk * SUPPORT_ROUTING_SCORE_WEIGHTS.atRisk +
    workload.breached * SUPPORT_ROUTING_SCORE_WEIGHTS.breached
  );
}

function prefersUrgentHeadroom(priority: SupportTicketPriority): boolean {
  return priority === 'HIGH' || priority === 'URGENT';
}

/** Capacity first, then urgent headroom. Empty skill arrays are not wildcards. */
export function capacityEligibleAgentIds(input: {
  agentIds: string[];
  workloads: Map<string, RoutingAgentWorkload>;
  priority: SupportTicketPriority;
  maxActive: number;
  urgentHeadroom?: number;
}): string[] {
  const headroom = input.urgentHeadroom ?? SUPPORT_ROUTING_URGENT_HEADROOM;
  const unique = [...new Set(input.agentIds.filter(Boolean))];
  const underCap = unique.filter((id) => {
    const assigned = input.workloads.get(id)?.assigned ?? 0;
    return assigned < input.maxActive;
  });
  if (underCap.length === 0) return [];
  if (prefersUrgentHeadroom(input.priority)) {
    const preferred = underCap.filter((id) => {
      const assigned = input.workloads.get(id)?.assigned ?? 0;
      return assigned < input.maxActive * headroom;
    });
    if (preferred.length > 0) return preferred;
  }
  return underCap;
}

function matchesCategory(
  skills: RoutingAgentSkills | undefined,
  category: string,
): boolean {
  return (skills?.categories ?? []).includes(category);
}

function matchesLanguage(
  skills: RoutingAgentSkills | undefined,
  language: string | null,
): boolean {
  if (!language) return false;
  return (skills?.languages ?? []).includes(language);
}

export function pickSkillTier(input: {
  agentIds: string[];
  skills: Map<string, RoutingAgentSkills>;
  category: SupportTicketCategory | string;
  language: string | null;
}): {
  agentIds: string[];
  skillTier: RoutingSkillTier;
  categoryMatch: boolean;
  languageMatch: boolean;
} {
  const catLang = input.agentIds.filter(
    (id) =>
      matchesCategory(input.skills.get(id), input.category) &&
      matchesLanguage(input.skills.get(id), input.language),
  );
  if (catLang.length > 0) {
    return {
      agentIds: catLang,
      skillTier: 'CATEGORY_AND_LANGUAGE',
      categoryMatch: true,
      languageMatch: true,
    };
  }
  const cat = input.agentIds.filter((id) =>
    matchesCategory(input.skills.get(id), input.category),
  );
  if (cat.length > 0) {
    return {
      agentIds: cat,
      skillTier: 'CATEGORY',
      categoryMatch: true,
      languageMatch: false,
    };
  }
  const lang = input.agentIds.filter((id) =>
    matchesLanguage(input.skills.get(id), input.language),
  );
  if (lang.length > 0) {
    return {
      agentIds: lang,
      skillTier: 'LANGUAGE',
      categoryMatch: false,
      languageMatch: true,
    };
  }
  return {
    agentIds: input.agentIds,
    skillTier: 'GENERAL',
    categoryMatch: false,
    languageMatch: false,
  };
}

/**
 * Lowest score wins. Ties: lowest active count, then oldest last assignment
 * (missing timestamp counts as never assigned), then stable agent id.
 * Returns null when nobody is under capacity.
 */
export function selectBestAgent(input: {
  agentIds: string[];
  workloads: Map<string, RoutingAgentWorkload>;
  lastAssignedAt: Map<string, number>;
  priority: SupportTicketPriority;
  maxActive: number;
  urgentHeadroom?: number;
}): string | null {
  const pool = capacityEligibleAgentIds(input);
  if (pool.length === 0) return null;

  pool.sort((a, b) => {
    const wa = input.workloads.get(a) ?? emptyWorkload(a);
    const wb = input.workloads.get(b) ?? emptyWorkload(b);
    const scoreDiff = calculateRoutingScore(wa) - calculateRoutingScore(wb);
    if (scoreDiff !== 0) return scoreDiff;
    if (wa.assigned !== wb.assigned) return wa.assigned - wb.assigned;
    const lastA = input.lastAssignedAt.get(a) ?? 0;
    const lastB = input.lastAssignedAt.get(b) ?? 0;
    if (lastA !== lastB) return lastA - lastB;
    return a.localeCompare(b);
  });

  return pool[0] ?? null;
}

import type { SupportTicketPriority } from './entities/stays-support-ticket.entity';

export const SUPPORT_SLA = {
  LOW: { firstResponseHours: 24, resolutionHours: 120 },
  NORMAL: { firstResponseHours: 12, resolutionHours: 72 },
  HIGH: { firstResponseHours: 4, resolutionHours: 24 },
  URGENT: { firstResponseHours: 1, resolutionHours: 8 },
} as const satisfies Record<
  SupportTicketPriority,
  { firstResponseHours: number; resolutionHours: number }
>;

export type SupportSlaState = 'ON_TRACK' | 'AT_RISK' | 'BREACHED';

export type SupportSlaLeg = {
  targetAt: string;
  completedAt: string | null;
  state: SupportSlaState;
};

export type SupportSlaPayload = {
  firstResponse: SupportSlaLeg;
  /** First-resolution SLA (completed when resolved_at is set). */
  resolution: SupportSlaLeg;
};

function addHours(base: Date, hours: number): Date {
  return new Date(base.getTime() + hours * 60 * 60 * 1000);
}

/**
 * Incomplete: <80% ON_TRACK, 80–<100% AT_RISK, ≥100% BREACHED.
 * Complete: on/before target ON_TRACK, else BREACHED.
 */
export function slaStateFor(
  createdAt: Date,
  targetAt: Date,
  completedAt: Date | null,
  now: Date,
): SupportSlaState {
  if (completedAt) {
    return completedAt.getTime() <= targetAt.getTime() ? 'ON_TRACK' : 'BREACHED';
  }
  const windowMs = targetAt.getTime() - createdAt.getTime();
  if (windowMs <= 0) return 'BREACHED';
  const elapsed = now.getTime() - createdAt.getTime();
  const ratio = elapsed / windowMs;
  if (ratio < 0.8) return 'ON_TRACK';
  if (ratio < 1) return 'AT_RISK';
  return 'BREACHED';
}

export function computeSupportSla(
  input: {
    createdAt: Date;
    priority: SupportTicketPriority;
    firstAdminResponseAt: Date | null;
    resolvedAt: Date | null;
  },
  now: Date = new Date(),
): SupportSlaPayload {
  const policy = SUPPORT_SLA[input.priority] ?? SUPPORT_SLA.NORMAL;
  const frTarget = addHours(input.createdAt, policy.firstResponseHours);
  const resTarget = addHours(input.createdAt, policy.resolutionHours);
  return {
    firstResponse: {
      targetAt: frTarget.toISOString(),
      completedAt: input.firstAdminResponseAt?.toISOString() ?? null,
      state: slaStateFor(
        input.createdAt,
        frTarget,
        input.firstAdminResponseAt,
        now,
      ),
    },
    resolution: {
      targetAt: resTarget.toISOString(),
      completedAt: input.resolvedAt?.toISOString() ?? null,
      state: slaStateFor(input.createdAt, resTarget, input.resolvedAt, now),
    },
  };
}

const PRIORITY_RANK: Record<SupportTicketPriority, number> = {
  LOW: 1,
  NORMAL: 2,
  HIGH: 3,
  URGENT: 4,
};

const CATEGORY_MIN_PRIORITY: Partial<
  Record<string, SupportTicketPriority>
> = {
  FRAUD: 'HIGH',
  KYC: 'HIGH',
  PAYMENT: 'NORMAL',
  REFUND: 'NORMAL',
  BOOKING: 'NORMAL',
  CANCELLATION: 'NORMAL',
  HOST: 'NORMAL',
  GUEST: 'NORMAL',
  LISTING: 'LOW',
  TECHNICAL: 'NORMAL',
  OTHER: 'LOW',
};

/**
 * Deterministic routing suggestion only — never auto-applied.
 * Never suggests below current priority when current is URGENT (or higher rank).
 */
export function suggestRouting(input: {
  category: string;
  currentPriority: SupportTicketPriority;
  hasReportId?: boolean;
  hasSafetyIssueId?: boolean;
}): { suggestedPriority: SupportTicketPriority; reason: string } {
  let suggested: SupportTicketPriority =
    CATEGORY_MIN_PRIORITY[input.category] ?? 'NORMAL';
  let reason = `Category ${input.category} → ${suggested}`;

  if (input.hasSafetyIssueId) {
    suggested = 'HIGH';
    reason = 'Linked safety issue → HIGH minimum';
  } else if (input.hasReportId) {
    suggested = 'HIGH';
    reason = 'Linked conversation report → HIGH minimum';
  }

  // Never downgrade URGENT (or any higher current priority).
  if (PRIORITY_RANK[input.currentPriority] > PRIORITY_RANK[suggested]) {
    return {
      suggestedPriority: input.currentPriority,
      reason: `Keep ${input.currentPriority} (never downgrade)`,
    };
  }
  return { suggestedPriority: suggested, reason };
}

import type {
  SupportTicketParty,
  SupportTicketStatus,
} from './entities/stays-support-ticket.entity';

/**
 * Customer-message ticket status transitions for SUPPORT threads.
 * Documented for Phase 1.1 — do not drift without an explicit product change.
 *
 * WAITING_FOR_HOST advances only when the ticket party is HOST.
 * WAITING_FOR_CUSTOMER → IN_PROGRESS (customer reply reactivates work).
 * RESOLVED → OPEN (first resolved_at is preserved by the caller — Phase 3).
 * CLOSED is rejected before this runs (409).
 */
export function nextStatusAfterCustomerMessage(input: {
  status: SupportTicketStatus;
  party: SupportTicketParty;
}): SupportTicketStatus {
  switch (input.status) {
    case 'RESOLVED':
      return 'OPEN';
    case 'WAITING_FOR_CUSTOMER':
      return 'IN_PROGRESS';
    case 'WAITING_FOR_HOST':
      return input.party === 'HOST' ? 'OPEN' : 'WAITING_FOR_HOST';
    case 'OPEN':
    case 'IN_PROGRESS':
    case 'ESCALATED':
    case 'CLOSED':
      return input.status;
    default:
      return input.status;
  }
}

export const CLOSED_SUPPORT_TICKET_MESSAGE =
  'This support ticket is closed.';

export const TICKET_MUST_BE_REOPENED_MESSAGE =
  'Ticket must be reopened using the reopen action';

export const TICKET_IS_NOT_CLOSED_MESSAGE = 'Ticket is not closed';

import {
  Body,
  Controller,
  Get,
  Param,
  ParseUUIDPipe,
  Post,
  Query,
} from '@nestjs/common';
import { ApiBearerAuth, ApiTags } from '@nestjs/swagger';
import { Throttle } from '@nestjs/throttler';
import { CurrentUser } from '../../common/decorators/current-user.decorator';
import { SupportTicketsService } from './support-tickets.service';
import { CreateSupportTicketDto, CreateSupportTicketCsatDto } from './dto/support-ticket.dto';

@ApiTags('Support')
@Controller('support')
@Throttle({
  short: { limit: 10, ttl: 1000 },
  default: { limit: 60, ttl: 60000 },
})
@ApiBearerAuth()
export class SupportTicketsController {
  constructor(private readonly supportTickets: SupportTicketsService) {}

  @Post('tickets')
  create(
    @CurrentUser() user: { userId: string },
    @Body() dto: CreateSupportTicketDto,
  ) {
    return this.supportTickets.createTicketForUser(user.userId, dto);
  }

  @Get('tickets')
  list(
    @CurrentUser() user: { userId: string },
    @Query('limit') limit?: string,
  ) {
    const parsed = limit ? Number(limit) : 50;
    return this.supportTickets.listForUser(
      user.userId,
      Number.isFinite(parsed) ? parsed : 50,
    );
  }

  @Get('tickets/:id')
  get(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    return this.supportTickets.getForUser(user.userId, id);
  }

  @Get('tickets/:id/csat')
  getCsat(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
  ) {
    return this.supportTickets.getCsatForUser(user.userId, id);
  }

  @Post('tickets/:id/csat')
  submitCsat(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) id: string,
    @Body() body: CreateSupportTicketCsatDto,
  ) {
    return this.supportTickets.submitCsatForUser(user.userId, id, body);
  }
}

